-- ==============================================================================
-- File: supabase/migrations/20261108_seed_8_domains_curriculum.sql
-- Mục đích: Khởi tạo schema và SEED dữ liệu 8 Nhóm Ngành, Hệ thống Môn học (chung & chuyên ngành)
--           và toàn bộ Bài học (10-15 bài/môn) cho dự án Feynman Stage.
-- ==============================================================================

-- 1. Xóa bảng cũ nếu tồn tại (Đảm bảo seed lại dữ liệu mới sạch sẽ)
DROP TABLE IF EXISTS public.academic_topics CASCADE;
DROP TABLE IF EXISTS public.domain_subjects CASCADE;
DROP TABLE IF EXISTS public.academic_subjects CASCADE;
DROP TABLE IF EXISTS public.academic_domains CASCADE;

-- 2. Tạo bảng 8 Nhóm Ngành (academic_domains)
CREATE TABLE public.academic_domains (
    id TEXT PRIMARY KEY,
    slug TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    description TEXT NOT NULL,
    icon_name TEXT DEFAULT 'BookOpen',
    color TEXT DEFAULT '#3B82F6',
    color_hex TEXT DEFAULT '#3B82F6',
    accent_bg TEXT DEFAULT 'bg-blue-500/10',
    order_index INTEGER DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 3. Tạo bảng Môn học (academic_subjects)
CREATE TABLE public.academic_subjects (
    id TEXT PRIMARY KEY,
    slug TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    description TEXT NOT NULL,
    difficulty_level INTEGER DEFAULT 2,
    order_index INTEGER DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 4. Tạo bảng liên kết N-N Môn học & Ngành học (domain_subjects) - Cơ chế môn chung & chuyên ngành
CREATE TABLE public.domain_subjects (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    domain_id TEXT NOT NULL REFERENCES public.academic_domains(id) ON DELETE CASCADE,
    subject_id TEXT NOT NULL REFERENCES public.academic_subjects(id) ON DELETE CASCADE,
    is_core BOOLEAN DEFAULT true,
    order_index INTEGER DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL,
    UNIQUE(domain_id, subject_id)
);

-- 5. Tạo bảng Bài học chi tiết (academic_topics)
CREATE TABLE public.academic_topics (
    id TEXT PRIMARY KEY,
    subject_id TEXT NOT NULL REFERENCES public.academic_subjects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    slug TEXT NOT NULL,
    summary TEXT NOT NULL,
    difficulty_level INTEGER NOT NULL DEFAULT 2,
    order_index INTEGER NOT NULL DEFAULT 1,
    estimated_reading_minutes INTEGER DEFAULT 10,
    required_concepts JSONB NOT NULL DEFAULT '[]'::jsonb,
    status TEXT NOT NULL DEFAULT 'NOT_STARTED',
    highest_clarity_score INTEGER DEFAULT NULL,
    active_session_id TEXT DEFAULT NULL,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 6. Tạo chỉ mục tối ưu truy vấn (Indexes)
CREATE INDEX idx_domain_subjects_domain ON public.domain_subjects(domain_id);
CREATE INDEX idx_domain_subjects_subject ON public.domain_subjects(subject_id);
CREATE INDEX idx_academic_topics_subject ON public.academic_topics(subject_id);
CREATE INDEX idx_academic_topics_status ON public.academic_topics(status);

-- 7. Kích hoạt Row Level Security (RLS) & Phân quyền truy cập
ALTER TABLE public.academic_domains ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.academic_subjects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.domain_subjects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.academic_topics ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Cho phép đọc academic_domains" ON public.academic_domains FOR SELECT USING (true);
CREATE POLICY "Cho phép ghi academic_domains" ON public.academic_domains FOR ALL USING (true);

CREATE POLICY "Cho phép đọc academic_subjects" ON public.academic_subjects FOR SELECT USING (true);
CREATE POLICY "Cho phép ghi academic_subjects" ON public.academic_subjects FOR ALL USING (true);

CREATE POLICY "Cho phép đọc domain_subjects" ON public.domain_subjects FOR SELECT USING (true);
CREATE POLICY "Cho phép ghi domain_subjects" ON public.domain_subjects FOR ALL USING (true);

CREATE POLICY "Cho phép đọc academic_topics" ON public.academic_topics FOR SELECT USING (true);
CREATE POLICY "Cho phép ghi academic_topics" ON public.academic_topics FOR ALL USING (true);

-- Cấp quyền cho các role anon và authenticated
GRANT SELECT ON public.academic_domains TO anon, authenticated;
GRANT SELECT ON public.academic_subjects TO anon, authenticated;
GRANT SELECT ON public.domain_subjects TO anon, authenticated;
GRANT SELECT ON public.academic_topics TO anon, authenticated;

-- ==============================================================================
-- BẮT ĐẦU CHÈN DỮ LIỆU SEED (INSERT DATA)
-- ==============================================================================
BEGIN;

-- Chèn 8 Nhóm Ngành học

-- Chèn Danh sách Môn học

-- Chèn Quan hệ Môn học - Ngành học (domain_subjects)

-- Chèn Danh sách Bài học chi tiết (academic_topics)
COMMIT;

-- ==============================================================================
-- 8. THIẾT LẬP RÀNG BUỘC KHÓA NGOẠI (FOREIGN KEYS) VỚI CÁC BẢNG KHÁC TRONG HỆ THỐNG
-- ==============================================================================
DO $$
BEGIN
    -- 8.1 Liên kết bảng learning_sessions (bảng gốc lưu phiên học)
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'learning_sessions' AND table_type = 'BASE TABLE') THEN
        ALTER TABLE public.learning_sessions DROP CONSTRAINT IF EXISTS learning_sessions_topic_id_fkey;
        ALTER TABLE public.learning_sessions DROP CONSTRAINT IF EXISTS fk_learning_sessions_topic;
        ALTER TABLE public.learning_sessions ALTER COLUMN topic_id TYPE TEXT USING topic_id::text;
        
        ALTER TABLE public.learning_sessions
            ADD CONSTRAINT fk_learning_sessions_topic
            FOREIGN KEY (topic_id) REFERENCES public.academic_topics(id) ON DELETE SET NULL;
    END IF;

    -- 8.2 Trường hợp bảng sessions là BASE TABLE (không phải VIEW)
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'sessions' AND table_type = 'BASE TABLE') THEN
        ALTER TABLE public.sessions DROP CONSTRAINT IF EXISTS fk_sessions_topic;
        ALTER TABLE public.sessions DROP CONSTRAINT IF EXISTS fk_sessions_domain;
        ALTER TABLE public.sessions ALTER COLUMN topic_id TYPE TEXT USING topic_id::text;
        ALTER TABLE public.sessions ALTER COLUMN domain_id TYPE TEXT USING domain_id::text;
        
        ALTER TABLE public.sessions
            ADD CONSTRAINT fk_sessions_topic
            FOREIGN KEY (topic_id) REFERENCES public.academic_topics(id) ON DELETE SET NULL;
            
        ALTER TABLE public.sessions
            ADD CONSTRAINT fk_sessions_domain
            FOREIGN KEY (domain_id) REFERENCES public.academic_domains(id) ON DELETE SET NULL;
    END IF;

    -- 8.3 Liên kết bảng topic_edges (Đồ thị tri thức Knowledge Graph)
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'topic_edges' AND table_type = 'BASE TABLE') THEN
        -- Phải drop check constraint chk_no_self_loop trước khi alter để tránh lỗi so sánh text <> uuid
        ALTER TABLE public.topic_edges DROP CONSTRAINT IF EXISTS chk_no_self_loop;
        ALTER TABLE public.topic_edges DROP CONSTRAINT IF EXISTS uq_topic_edge;
        ALTER TABLE public.topic_edges DROP CONSTRAINT IF EXISTS topic_edges_source_topic_id_fkey;
        ALTER TABLE public.topic_edges DROP CONSTRAINT IF EXISTS topic_edges_target_topic_id_fkey;
        ALTER TABLE public.topic_edges DROP CONSTRAINT IF EXISTS fk_topic_edges_source;
        ALTER TABLE public.topic_edges DROP CONSTRAINT IF EXISTS fk_topic_edges_target;
        
        ALTER TABLE public.topic_edges ALTER COLUMN source_topic_id TYPE TEXT USING source_topic_id::text;
        ALTER TABLE public.topic_edges ALTER COLUMN target_topic_id TYPE TEXT USING target_topic_id::text;
        
        -- Tái tạo lại ràng buộc sau khi cả 2 cột đã cùng kiểu TEXT
        ALTER TABLE public.topic_edges ADD CONSTRAINT chk_no_self_loop CHECK (source_topic_id <> target_topic_id);
        ALTER TABLE public.topic_edges ADD CONSTRAINT uq_topic_edge UNIQUE (source_topic_id, target_topic_id);
        
        ALTER TABLE public.topic_edges
            ADD CONSTRAINT fk_topic_edges_source
            FOREIGN KEY (source_topic_id) REFERENCES public.academic_topics(id) ON DELETE CASCADE;
            
        ALTER TABLE public.topic_edges
            ADD CONSTRAINT fk_topic_edges_target
            FOREIGN KEY (target_topic_id) REFERENCES public.academic_topics(id) ON DELETE CASCADE;
    END IF;

    -- 8.4 Liên kết bảng academic_materials (Tài liệu học tập RAG / Embeddings)
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'academic_materials' AND table_type = 'BASE TABLE') THEN
        ALTER TABLE public.academic_materials DROP CONSTRAINT IF EXISTS academic_materials_topic_id_fkey;
        ALTER TABLE public.academic_materials DROP CONSTRAINT IF EXISTS fk_academic_materials_topic;
        ALTER TABLE public.academic_materials ALTER COLUMN topic_id TYPE TEXT USING topic_id::text;
        
        ALTER TABLE public.academic_materials
            ADD CONSTRAINT fk_academic_materials_topic
            FOREIGN KEY (topic_id) REFERENCES public.academic_topics(id) ON DELETE CASCADE;
    END IF;

    -- 8.5 Liên kết bảng profiles (Hồ sơ người dùng)
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'profiles' AND table_type = 'BASE TABLE') THEN
        ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS fk_profiles_primary_domain;
        ALTER TABLE public.profiles ALTER COLUMN primary_domain_id TYPE TEXT USING primary_domain_id::text;
        
        ALTER TABLE public.profiles
            ADD CONSTRAINT fk_profiles_primary_domain
            FOREIGN KEY (primary_domain_id) REFERENCES public.academic_domains(id) ON DELETE SET NULL;
    END IF;
END $$;

-- 8.6 Cập nhật VIEW public.sessions để ánh xạ chuẩn từ learning_sessions
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.views WHERE table_schema = 'public' AND table_name = 'sessions') THEN
        CREATE OR REPLACE VIEW public.sessions AS
        SELECT
            id,
            COALESCE(custom_topic_title, 'General') AS topic,
            topic_id,
            persona_id,
            difficulty,
            status,
            current_clarity AS clarity_score,
            started_at AS created_at
        FROM public.learning_sessions;
    END IF;
END $$;

-- Tạo các Indexes cho các khóa ngoại liên kết hệ thống
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'learning_sessions' AND table_type = 'BASE TABLE') THEN
        CREATE INDEX IF NOT EXISTS idx_learning_sessions_topic_id ON public.learning_sessions(topic_id);
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'sessions' AND table_type = 'BASE TABLE') THEN
        CREATE INDEX IF NOT EXISTS idx_sessions_topic_id ON public.sessions(topic_id);
        CREATE INDEX IF NOT EXISTS idx_sessions_domain_id ON public.sessions(domain_id);
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'topic_edges' AND table_type = 'BASE TABLE') THEN
        CREATE INDEX IF NOT EXISTS idx_topic_edges_source ON public.topic_edges(source_topic_id);
        CREATE INDEX IF NOT EXISTS idx_topic_edges_target ON public.topic_edges(target_topic_id);
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'academic_materials' AND table_type = 'BASE TABLE') THEN
        CREATE INDEX IF NOT EXISTS idx_academic_materials_topic ON public.academic_materials(topic_id);
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'profiles' AND table_type = 'BASE TABLE') THEN
        CREATE INDEX IF NOT EXISTS idx_profiles_primary_domain ON public.profiles(primary_domain_id);
    END IF;
END $$;

-- Hoàn tất seed dữ liệu thành công!