INSERT INTO public.academic_domains (id, slug, name, description, icon_name, color, color_hex, accent_bg, order_index) VALUES ('dom-it', 'cong-nghe-thong-tin', 'Công Nghệ Thông Tin', 'Quản trị hạ tầng mạng, an toàn thông tin, điện toán đám mây và phát triển giải pháp số toàn diện.', 'Cpu', '#3B82F6', '#3B82F6', 'bg-blue-500/10', 1);
INSERT INTO public.academic_domains (id, slug, name, description, icon_name, color, color_hex, accent_bg, order_index) VALUES ('dom-cs', 'khoa-hoc-may-tinh', 'Khoa Học Máy Tính', 'Thuật toán nền tảng, trí tuệ nhân tạo, lý thuyết tính toán, thị giác máy tính và kiến trúc hệ thống.', 'Terminal', '#6366F1', '#6366F1', 'bg-indigo-500/10', 2);
INSERT INTO public.academic_domains (id, slug, name, description, icon_name, color, color_hex, accent_bg, order_index) VALUES ('dom-se', 'ky-thuat-phan-mem', 'Kỹ Thuật Phần Mềm', 'Kiến trúc hệ thống, quy trình phát triển Agile/DevOps, kiểm thử chất lượng và thiết kế phần mềm quy mô lớn.', 'Code2', '#8B5CF6', '#8B5CF6', 'bg-purple-500/10', 3);
INSERT INTO public.academic_domains (id, slug, name, description, icon_name, color, color_hex, accent_bg, order_index) VALUES ('dom-ecom', 'thuong-mai-dien-tu', 'Thương Mại Điện Tử', 'Mô hình kinh doanh số, thanh toán điện tử, tiếp thị số, phân tích dữ liệu tiêu dùng và chuỗi cung ứng.', 'ShoppingCart', '#EC4899', '#EC4899', 'bg-pink-500/10', 4);
INSERT INTO public.academic_domains (id, slug, name, description, icon_name, color, color_hex, accent_bg, order_index) VALUES ('dom-acc', 'ke-toan-kiem-toan', 'Kế Toán - Kiểm Toán', 'Hệ thống chuẩn mực kế toán tài chính, kế toán quản trị, kiểm toán độc lập và lập báo cáo thuế chuyên sâu.', 'Calculator', '#06B6D4', '#06B6D4', 'bg-cyan-500/10', 5);
INSERT INTO public.academic_domains (id, slug, name, description, icon_name, color, color_hex, accent_bg, order_index) VALUES ('dom-biz', 'quan-tri-kinh-doanh', 'Quản Trị Kinh Doanh', 'Hoạch định chiến lược doanh nghiệp, quản trị nhân sự, tài chính đầu tư, đàm phán thương mại và khởi sự đổi mới.', 'Briefcase', '#10B981', '#10B981', 'bg-emerald-500/10', 6);
INSERT INTO public.academic_domains (id, slug, name, description, icon_name, color, color_hex, accent_bg, order_index) VALUES ('dom-tour', 'du-lich-lu-hanh', 'Du Lịch Lữ Hành', 'Nghiệp vụ hướng dẫn lữ hành, quản trị khách sạn resort, marketing điểm đến du lịch và tổ chức sự kiện MICE.', 'Compass', '#F59E0B', '#F59E0B', 'bg-amber-500/10', 7);
INSERT INTO public.academic_domains (id, slug, name, description, icon_name, color, color_hex, accent_bg, order_index) VALUES ('dom-med', 'y-khoa', 'Y Khoa & Sức Khỏe', 'Khoa học y sinh cơ sở, giải phẫu, sinh lý bệnh, dược lý điều trị, đạo đức nghề y và chẩn đoán cận lâm sàng.', 'Stethoscope', '#EF4444', '#EF4444', 'bg-rose-500/10', 8);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-discrete-math', 'toan-roi-rac', 'Toán Rời Rạc & Lý Thuyết Đồ Thị', 'Logic mệnh đề, tập hợp, quan hệ tương đương, đồ thị Euler-Hamilton và cây bao trùm tối thiểu.', 2, 1);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-dsa', 'cau-truc-du-lieu-giai-thuat', 'Cấu Trúc Dữ Liệu & Giải Thuật', 'Mảng động, danh sách liên kết, ngăn xếp, hàng đợi, cây nhị phân, bảng băm và thuật toán sắp xếp.', 3, 2);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-db', 'co-so-du-lieu-sql', 'Cơ Sở Dữ Liệu & Hệ Quản Trị SQL', 'Mô hình quan hệ, đại số quan hệ, chuẩn hóa dữ liệu 1NF-BCNF, chỉ mục B-Tree và giao dịch ACID.', 2, 3);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-networks', 'mang-may-tinh-truyen-thong', 'Mạng Máy Tính & Truyền Thông', 'Mô hình OSI, TCP/IP, định tuyến IP, giao thức tầng truyền vận và an toàn mạng.', 2, 4);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-microecon', 'kinh-te-vi-mo', 'Kinh Tế Học Vi Mô', 'Cung cầu, độ co giãn, lý thuyết hành vi người tiêu dùng, chi phí sản xuất và cấu trúc thị trường.', 2, 5);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-macroecon', 'kinh-te-vi-mo-macro', 'Kinh Tế Học Vĩ Mô', 'Tổng sản phẩm quốc nội GDP, lạm phát, thất nghiệp, chính sách tài khóa và chính sách tiền tệ.', 2, 6);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-acc-principles', 'nguyen-ly-ke-toan', 'Nguyên Lý Kế Toán Căn Bản', 'Phương trình kế toán, định khoản kép, chứng từ sổ sách và hệ thống báo cáo tài chính căn bản.', 2, 7);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-basic-marketing', 'marketing-can-ban', 'Marketing Căn Bản & Hành Vi Tiêu Dùng', 'Nghiên cứu thị trường, phân khúc STP, phối thức Marketing Mix 4P/7P và xây dựng thương hiệu.', 2, 8);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-biz-law', 'phap-luat-dai-cuong-kinh-te', 'Pháp Luật Đại Cương & Luật Kinh Tế', 'Địa vị pháp lý của doanh nghiệp, hợp đồng thương mại, giải quyết tranh chấp và luật sở hữu trí tuệ.', 2, 9);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-service-comm', 'tam-ly-giao-tiep-dich-vu', 'Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng', 'Kỹ năng lắng nghe thấu cảm, xử lý phàn nàn, đàm phán thương lượng và xây dựng trải nghiệm khách hàng xuất sắc.', 2, 10);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-it-cloud', 'dien-toan-dam-may-cloud', 'Quản Trị Hệ Thống & Điện Toán Đám Mây', 'AWS, Azure, hạ tầng máy chủ Linux, tự động hóa hạ tầng IaC và giải pháp lưu trữ đám mây.', 3, 11);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-it-security', 'an-toan-thong-tin-cybersecurity', 'An Toàn Thông Tin & An Ninh Mạng', 'Mã hóa khóa công khai, tấn công mạng OWASP, phòng chống mã độc và kiểm thử bảo mật thâm nhập.', 3, 12);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-it-web', 'lap-trinh-web-fullstack', 'Phát Triển Ứng Dụng Web & API', 'Kiến trúc RESTful API, Single Page Application, xác thực JWT, State Management và triển khai SSR.', 2, 13);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-cs-ai-ml', 'tri-tue-nhan-tao-machine-learning', 'Trí Tuệ Nhân Tạo & Học Máy', 'Học có giám sát, học không giám sát, mạng nơ-ron học sâu, Gradient Descent và đánh giá mô hình.', 3, 14);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-cs-automata', 'ly-thuyet-tinh-toan-automata', 'Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức', 'Ôtômat hữu hạn, ngữ pháp phi ngữ cảnh, máy Turing, bài toán Halting và phân lớp P vs NP.', 3, 15);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-cs-os', 'kien-truc-may-tinh-he-dieu-hanh', 'Kiến Trúc Máy Tính & Hệ Điều Hành', 'Quản lý tiến trình, bộ nhớ ảo, ngắt phần cứng, lập lịch CPU và hệ thống tập tin.', 3, 16);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-se-testing', 'kiem-thu-chat-luong-phan-mem', 'Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng', 'Unit testing, Integration testing, kiểm thử hộp đen/hộp trắng, tự động hóa với Selenium/Cypress.', 2, 17);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-se-patterns', 'kien-truc-mau-thiet-ke-software', 'Kiến Trúc Phần Mềm & Mẫu Thiết Kế (Design Patterns)', 'Nguyên lý SOLID, Clean Architecture, GoF Patterns (Creational, Structural, Behavioral) và Microservices.', 3, 18);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-se-devops', 'agile-devops-quy-trinh-phan-mem', 'Quy Trình Phát Triển Agile & Văn Hóa DevOps', 'Scrum, Kanban, đường ống CI/CD, Infrastructure as Code, giám sát vận hành và tự động hóa release.', 2, 19);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-ecom-payments', 'thanh-toan-dien-tu-fintech', 'Hệ Thống Thanh Toán Điện Tử & FinTech', 'Cổng thanh toán, ví điện tử, QR Code, tokenization thẻ tín dụng, bảo mật PCI-DSS và công nghệ Blockchain.', 3, 20);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-ecom-digital-mkt', 'digital-marketing-seo-sem', 'Digital Marketing, SEO & Quảng Cáo Số', 'Tối ưu hóa công cụ tìm kiếm SEO, quảng cáo Google Ads, Facebook Ads, Content Marketing và Email Marketing.', 2, 21);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-ecom-logistics', 'quan-tri-san-tmdt-supply-chain', 'Quản Trị Sàn TMĐT & Chuỗi Cung Ứng Số', 'Vận hành gian hàng Shopee/Lazada/TikTok Shop, hoàn tất đơn hàng Fulfillment, logistics chặng cuối và Dropshipping.', 2, 22);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-acc-financial', 'ke-toan-tai-chinh-doanh-nghiep', 'Kế Toán Tài Chính Doanh Nghiệp Nâng Cao', 'Chuẩn mực VAS/IFRS, hợp nhất báo cáo tài chính, kế toán công cụ tài chính và giao dịch ngoại tệ.', 3, 23);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-acc-managerial', 'ke-toan-quan-tri-chi-phi', 'Kế Toán Quản Trị & Phân Tích Chi Phí', 'Phân loại chi phí, phân tích CVP, định giá sản phẩm, lập dự toán ngân sách và thẻ điểm cân bằng BSC.', 3, 24);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-acc-audit', 'kiem-toan-can-ban-chuan-muc', 'Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán', 'Bằng chứng kiểm toán, đánh giá rủi ro, kiểm soát nội bộ, lấy mẫu kiểm toán và phát hành báo cáo kiểm toán.', 3, 25);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-acc-tax', 'thue-bao-cao-thue-doanh-nghiep', 'Thuế & Báo Cáo Thuế Doanh Nghiệp', 'Thuế GTGT, thuế TNDN, thuế TNCN, hóa đơn điện tử và lập kế hoạch thuế hợp pháp.', 2, 26);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-biz-strategy', 'quan-tri-chien-luoc-kinh-doanh', 'Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh', 'Mô hình 5 lực lượng cạnh tranh Porter, ma trận SWOT, chiến lược đại dương xanh và thực thi chiến lược.', 3, 27);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-biz-finance', 'tai-chinh-doanh-nghiep-dau-tu', 'Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư', 'Giá trị thời gian của tiền, thẩm định dự án NPV/IRR, cấu trúc vốn WACC và quản trị vốn lưu động.', 3, 28);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-biz-hrm', 'quan-tri-nhan-su-to-chuc', 'Quản Trị Nguồn Nhân Lực & Văn Hóa Tổ Chức', 'Tuyển dụng nhân tài, đào tạo phát triển, đánh giá hiệu quả KPI/OKR, lương thưởng và tạo động lực.', 2, 29);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-biz-startup', 'khoi-nghiep-doi-moi-sang-tao', 'Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup)', 'Tư duy tinh gọn Lean Startup, mô hình Business Model Canvas, tìm kiếm Product-Market Fit và gọi vốn đầu tư.', 2, 30);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-tour-guiding', 'nghiep-vu-huong-dan-thiet-ke-tour', 'Nghiệp Vụ Hướng Dẫn Viên & Thiết Kế Tour', 'Xây dựng lịch trình tour, tính giá tour, thuyết minh tuyến điểm và xử lý khủng hoảng lữ hành.', 2, 31);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-tour-hotel', 'quan-tri-khach-san-resort', 'Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality)', 'Nghiệp vụ tiền sảnh Front Office, bộ phận phòng Buồng phòng, quản trị F&B và quản trị doanh thu RevPAR.', 2, 32);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-tour-geography', 'dia-ly-du-lich-tai-nguyen-van-hoa', 'Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản', 'Các vùng du lịch trọng điểm Việt Nam, di sản thế giới UNESCO, phong tục tập quán và văn hóa ẩm thực.', 2, 33);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-med-anatomy', 'giai-phau-hoc-nguoi-anatomy', 'Giải Phẫu Học Người (Human Anatomy)', 'Giải phẫu hệ xương khớp, hệ cơ, hệ tim mạch, hệ hô hấp, hệ tiêu hóa và hệ thần kinh trung ương.', 3, 34);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-med-physiology', 'sinh-ly-hoc-y-khoa', 'Sinh Lý Học Y Khoa (Medical Physiology)', 'Cơ chế nội môi, điện thế màng, sinh lý co cơ, sinh lý tuần hoàn huyết áp và trao đổi khí tại phổi.', 3, 35);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-med-pharma', 'duoc-ly-hoc-lam-sang', 'Dược Lý Học & Cơ Chế Tác Dụng Thuốc', 'Dược động học hấp thu phân bố chuyển hóa thải trừ, dược lực học thụ thể và các nhóm thuốc chính.', 3, 36);
INSERT INTO public.academic_subjects (id, slug, name, description, difficulty_level, order_index) VALUES ('sub-med-internal', 'benh-hoc-noi-khoa', 'Bệnh Học Nội Khoa Cơ Bản', 'Bệnh tăng huyết áp, nhồi máu cơ tim, đái tháo đường, viêm phổi và suy thận mạn.', 3, 37);
