INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-01', 'sub-discrete-math', 'Mệnh Đề Logic & Bảng Chân Trị', 'toan-roi-rac-1', 'Bài học ''Mệnh Đề Logic & Bảng Chân Trị'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Nền tảng logic toán học Nội dung trọng tâm gồm việc hiểu rõ bản chất của Mệnh đề, Phép hội/tuyển, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 1, 10, '["Mệnh đề", "Phép hội/tuyển", "Bảng chân trị", "Tương đương logic"]'::jsonb, 'COMPLETED', 88, 'ses-top-toan-roi-rac-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-02', 'sub-discrete-math', 'Vị Từ & Lượng Từ Toán Học (∀, ∃)', 'toan-roi-rac-2', 'Bài học ''Vị Từ & Lượng Từ Toán Học (∀, ∃)'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Biểu diễn logic toán bậc nhất Nội dung trọng tâm gồm việc hiểu rõ bản chất của Lượng từ với mọi, Lượng từ tồn tại, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 2, 15, '["Lượng từ với mọi", "Lượng từ tồn tại", "Phạm vi biến", "Phủ định vị từ"]'::jsonb, 'COMPLETED', 85, 'ses-top-toan-roi-rac-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-03', 'sub-discrete-math', 'Phương Pháp Chứng Minh Quy Nạp Toán Học', 'toan-roi-rac-3', 'Bài học ''Phương Pháp Chứng Minh Quy Nạp Toán Học'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Kỹ thuật chứng minh trong khoa học máy tính Nội dung trọng tâm gồm việc hiểu rõ bản chất của Bước cơ sở, Giả thiết quy nạp, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 3, 7, '["Bước cơ sở", "Giả thiết quy nạp", "Bước quy nạp", "Quy nạp mạnh"]'::jsonb, 'NEEDS_REVIEW', 49, 'ses-top-toan-roi-rac-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-04', 'sub-discrete-math', 'Quan Hệ Tương Đương & Phân Hoạch Tập Hợp', 'toan-roi-rac-4', 'Bài học ''Quan Hệ Tương Đương & Phân Hoạch Tập Hợp'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Cấu trúc quan hệ toán học cơ bản Nội dung trọng tâm gồm việc hiểu rõ bản chất của Phản xạ, Đối xứng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 4, 7, '["Phản xạ", "Đối xứng", "Bắc cầu", "Lớp tương đương"]'::jsonb, 'COMPLETED', 92, 'ses-top-toan-roi-rac-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-05', 'sub-discrete-math', 'Lý Thuyết Tập Hợp & Ánh Xạ Bijective', 'toan-roi-rac-5', 'Bài học ''Lý Thuyết Tập Hợp & Ánh Xạ Bijective'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Nền tảng cấu trúc dữ liệu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tập hợp con, Tập lũy thừa, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 5, 15, '["Tập hợp con", "Tập lũy thừa", "Đơn ánh", "Toàn ánh", "Song ánh"]'::jsonb, 'COMPLETED', 94, 'ses-top-toan-roi-rac-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-06', 'sub-discrete-math', 'Đại Số Boole & Tối Thiểu Hóa Hàm Boole', 'toan-roi-rac-6', 'Bài học ''Đại Số Boole & Tối Thiểu Hóa Hàm Boole'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Thiết kế mạch logic số học Nội dung trọng tâm gồm việc hiểu rõ bản chất của Biểu thức Boole, Cổng logic, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 6, 11, '["Biểu thức Boole", "Cổng logic", "Bản đồ Karnaugh", "Dạng chuẩn tắc"]'::jsonb, 'COMPLETED', 93, 'ses-top-toan-roi-rac-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-07', 'sub-discrete-math', 'Lý Thuyết Đồ Thị: Đỉnh, Cạnh & Bậc Đồ Thị', 'toan-roi-rac-7', 'Bài học ''Lý Thuyết Đồ Thị: Đỉnh, Cạnh & Bậc Đồ Thị'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Khái niệm nền tảng về đồ thị Nội dung trọng tâm gồm việc hiểu rõ bản chất của Bậc của đỉnh, Định lý bắt tay, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 7, 9, '["Bậc của đỉnh", "Định lý bắt tay", "Ma trận kề", "Danh sách kề"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-08', 'sub-discrete-math', 'Chu Trình Euler & Chu Trình Hamilton', 'toan-roi-rac-8', 'Bài học ''Chu Trình Euler & Chu Trình Hamilton'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Các bài toán kinh điển trên đồ thị Nội dung trọng tâm gồm việc hiểu rõ bản chất của Đồ thị Euler, Định lý Dirac, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 8, 11, '["Đồ thị Euler", "Định lý Dirac", "Chu trình Hamilton", "Đường đi Euler"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-toan-roi-rac-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-09', 'sub-discrete-math', 'Cây & Cây Khung Nhỏ Nhất (MST)', 'toan-roi-rac-9', 'Bài học ''Cây & Cây Khung Nhỏ Nhất (MST)'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Cấu trúc cây và bài toán tối ưu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Cây tự do, Rừng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 9, 12, '["Cây tự do", "Rừng", "Thuật toán Kruskal", "Thuật toán Prim"]'::jsonb, 'COMPLETED', 96, 'ses-top-toan-roi-rac-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-10', 'sub-discrete-math', 'Đồ Thị Phẳng & Định Lý Bốn Màu', 'toan-roi-rac-10', 'Bài học ''Đồ Thị Phẳng & Định Lý Bốn Màu'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Hình học topo của đồ thị phẳng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Công thức Euler v-e+f=2, Đồ thị phẳng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 12, '["Công thức Euler v-e+f=2", "Đồ thị phẳng", "Tô màu đồ thị", "Sắc số"]'::jsonb, 'COMPLETED', 85, 'ses-top-toan-roi-rac-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-11', 'sub-discrete-math', 'Quan Hệ Thứ Tự & Biểu Đồ Hasse', 'toan-roi-rac-11', 'Bài học ''Quan Hệ Thứ Tự & Biểu Đồ Hasse'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Thứ tự một phần và toàn phần Nội dung trọng tâm gồm việc hiểu rõ bản chất của Poset, Phản đối xứng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 11, 7, '["Poset", "Phản đối xứng", "Phần tử tối đại/tối tiểu", "Biểu đồ Hasse"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-12', 'sub-discrete-math', 'Giải Thuật Dijkstra Tìm Đường Đi Ngắn Nhất', 'toan-roi-rac-12', 'Bài học ''Giải Thuật Dijkstra Tìm Đường Đi Ngắn Nhất'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Tối ưu hóa đường đi trên đồ thị có trọng số Nội dung trọng tâm gồm việc hiểu rõ bản chất của Hàng đợi ưu tiên, Thư giãn cạnh, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 12, 8, '["Hàng đợi ưu tiên", "Thư giãn cạnh", "Chi phí đường đi", "Độ phức tạp O(E log V)"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-toan-roi-rac-12');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-13', 'sub-discrete-math', 'Toán Rời Rạc & Lý Thuyết Đồ Thị - Chuyên Đề Nâng Cao #1', 'toan-roi-rac-13', 'Bài học ''Toán Rời Rạc & Lý Thuyết Đồ Thị - Chuyên Đề Nâng Cao #1'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Toán Rời Rạc & Lý Thuyết Đồ Thị. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 13, 12, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'COMPLETED', 88, 'ses-top-toan-roi-rac-13');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-14', 'sub-discrete-math', 'Toán Rời Rạc & Lý Thuyết Đồ Thị - Chuyên Đề Nâng Cao #2', 'toan-roi-rac-14', 'Bài học ''Toán Rời Rạc & Lý Thuyết Đồ Thị - Chuyên Đề Nâng Cao #2'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Toán Rời Rạc & Lý Thuyết Đồ Thị. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #2A, Kỹ thuật tối ưu #2B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 14, 7, '["Khái niệm nâng cao #2A", "Kỹ thuật tối ưu #2B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'COMPLETED', 85, 'ses-top-toan-roi-rac-14');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-toan-roi-rac-15', 'sub-discrete-math', 'Toán Rời Rạc & Lý Thuyết Đồ Thị - Chuyên Đề Nâng Cao #3', 'toan-roi-rac-15', 'Bài học ''Toán Rời Rạc & Lý Thuyết Đồ Thị - Chuyên Đề Nâng Cao #3'' thuộc môn Toán Rời Rạc & Lý Thuyết Đồ Thị. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Toán Rời Rạc & Lý Thuyết Đồ Thị. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #3A, Kỹ thuật tối ưu #3B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 15, 8, '["Khái niệm nâng cao #3A", "Kỹ thuật tối ưu #3B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'COMPLETED', 88, 'ses-top-toan-roi-rac-15');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-cau-truc-du-lieu-giai-thuat-01', 'sub-dsa', 'Phân Tích Độ Phức Tạp Thuật Toán (Big-O)', 'cau-truc-du-lieu-giai-thuat-1', 'Bài học ''Phân Tích Độ Phức Tạp Thuật Toán (Big-O)'' thuộc môn Cấu Trúc Dữ Liệu & Giải Thuật. Đo lường hiệu năng thời gian và không gian Nội dung trọng tâm gồm việc hiểu rõ bản chất của Big-O, Big-Omega, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 1, 14, '["Big-O", "Big-Omega", "Big-Theta", "Độ phức tạp tiệm cận"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-cau-truc-du-lieu-giai-thuat-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-cau-truc-du-lieu-giai-thuat-02', 'sub-dsa', 'Danh Sách Liên Kết Đơn & Kép (Linked List)', 'cau-truc-du-lieu-giai-thuat-2', 'Bài học ''Danh Sách Liên Kết Đơn & Kép (Linked List)'' thuộc môn Cấu Trúc Dữ Liệu & Giải Thuật. Cấu trúc dữ liệu tuyến tính động Nội dung trọng tâm gồm việc hiểu rõ bản chất của Node, Con trỏ Next/Prev, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 9, '["Node", "Con trỏ Next/Prev", "Thêm/Xóa nút", "Truy cập tuần tự"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-cau-truc-du-lieu-giai-thuat-03', 'sub-dsa', 'Ngăn Xếp (Stack) & Ứng Dụng Khử Đệ Quy', 'cau-truc-du-lieu-giai-thuat-3', 'Bài học ''Ngăn Xếp (Stack) & Ứng Dụng Khử Đệ Quy'' thuộc môn Cấu Trúc Dữ Liệu & Giải Thuật. Nguyên lý Last-In-First-Out Nội dung trọng tâm gồm việc hiểu rõ bản chất của LIFO, Push/Pop, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 11, '["LIFO", "Push/Pop", "Call Stack", "Biểu thức tiền/hậu tố"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-cau-truc-du-lieu-giai-thuat-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-cau-truc-du-lieu-giai-thuat-04', 'sub-dsa', 'Hàng Đợi (Queue) & Hàng Đợi Ưu Tiên (Priority Queue)', 'cau-truc-du-lieu-giai-thuat-4', 'Bài học ''Hàng Đợi (Queue) & Hàng Đợi Ưu Tiên (Priority Queue)'' thuộc môn Cấu Trúc Dữ Liệu & Giải Thuật. Nguyên lý First-In-First-Out và Binary Heap Nội dung trọng tâm gồm việc hiểu rõ bản chất của FIFO, Enqueue/Dequeue, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 4, 8, '["FIFO", "Enqueue/Dequeue", "Max Heap", "Min Heap"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-cau-truc-du-lieu-giai-thuat-05', 'sub-dsa', 'Bảng Băm & Thuật Toán Xử Lý Xung Đột', 'cau-truc-du-lieu-giai-thuat-5', 'Bài học ''Bảng Băm & Thuật Toán Xử Lý Xung Đột'' thuộc môn Cấu Trúc Dữ Liệu & Giải Thuật. Tra cứu dữ liệu O(1) trung bình Nội dung trọng tâm gồm việc hiểu rõ bản chất của Hàm băm, Load Factor, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 5, 15, '["Hàm băm", "Load Factor", "Separate Chaining", "Open Addressing"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-cau-truc-du-lieu-giai-thuat-06', 'sub-dsa', 'Cây Nhị Phân Tìm Kiếm (BST)', 'cau-truc-du-lieu-giai-thuat-6', 'Bài học ''Cây Nhị Phân Tìm Kiếm (BST)'' thuộc môn Cấu Trúc Dữ Liệu & Giải Thuật. Cấu trúc cây có thứ tự Nội dung trọng tâm gồm việc hiểu rõ bản chất của In-order Traversal, Pre-order, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 6, 13, '["In-order Traversal", "Pre-order", "Post-order", "Tìm kiếm nhị phân"]'::jsonb, 'COMPLETED', 91, 'ses-top-cau-truc-du-lieu-giai-thuat-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-cau-truc-du-lieu-giai-thuat-07', 'sub-dsa', 'Cây Cân Bằng AVL & Kỹ Thuật Phép Quay', 'cau-truc-du-lieu-giai-thuat-7', 'Bài học ''Cây Cân Bằng AVL & Kỹ Thuật Phép Quay'' thuộc môn Cấu Trúc Dữ Liệu & Giải Thuật. Tự cân bằng để bảo đảm O(log N) Nội dung trọng tâm gồm việc hiểu rõ bản chất của Hệ số cân bằng, Quay đơn LL/RR, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 15, '["Hệ số cân bằng", "Quay đơn LL/RR", "Quay kép LR/RL", "Chiều cao cây"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-cau-truc-du-lieu-giai-thuat-08', 'sub-dsa', 'Thuật Toán Sắp Xếp Nhanh (Quicksort)', 'cau-truc-du-lieu-giai-thuat-8', 'Bài học ''Thuật Toán Sắp Xếp Nhanh (Quicksort)'' thuộc môn Cấu Trúc Dữ Liệu & Giải Thuật. Chiến lược chia để trị hiệu năng cao Nội dung trọng tâm gồm việc hiểu rõ bản chất của Pivot Selection, Partitioning, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 7, '["Pivot Selection", "Partitioning", "Best/Worst Case", "In-place Sorting"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-cau-truc-du-lieu-giai-thuat-09', 'sub-dsa', 'Thuật Toán Sắp Xếp Trộn (Mergesort)', 'cau-truc-du-lieu-giai-thuat-9', 'Bài học ''Thuật Toán Sắp Xếp Trộn (Mergesort)'' thuộc môn Cấu Trúc Dữ Liệu & Giải Thuật. Sắp xếp ổn định với độ phức tạp O(N log N) Nội dung trọng tâm gồm việc hiểu rõ bản chất của Chia để trị, Merge hai mảng con, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 9, 12, '["Chia để trị", "Merge hai mảng con", "Bộ nhớ phụ O(N)", "Tính ổn định"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-cau-truc-du-lieu-giai-thuat-10', 'sub-dsa', 'Thuật Toán Tìm Kiếm Theo Chiều Rộng (BFS)', 'cau-truc-du-lieu-giai-thuat-10', 'Bài học ''Thuật Toán Tìm Kiếm Theo Chiều Rộng (BFS)'' thuộc môn Cấu Trúc Dữ Liệu & Giải Thuật. Duyệt đồ thị theo từng lớp lân cận Nội dung trọng tâm gồm việc hiểu rõ bản chất của Queue, Đường đi ngắn nhất không trọng số, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 10, 12, '["Queue", "Đường đi ngắn nhất không trọng số", "Visited Set", "Cây khung BFS"]'::jsonb, 'COMPLETED', 87, 'ses-top-cau-truc-du-lieu-giai-thuat-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-cau-truc-du-lieu-giai-thuat-11', 'sub-dsa', 'Thuật Toán Tìm Kiếm Theo Chiều Sâu (DFS)', 'cau-truc-du-lieu-giai-thuat-11', 'Bài học ''Thuật Toán Tìm Kiếm Theo Chiều Sâu (DFS)'' thuộc môn Cấu Trúc Dữ Liệu & Giải Thuật. Duyệt đồ thị đi sâu khám phá Nội dung trọng tâm gồm việc hiểu rõ bản chất của Recursion Stack, Thời gian vào/ra Discovery/Finish, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 11, 13, '["Recursion Stack", "Thời gian vào/ra Discovery/Finish", "Phân loại cạnh", "Tìm chu trình"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-01', 'sub-db', 'Mô Hình Thực Thể Mối Kết Hợp (ERD)', 'co-so-du-lieu-sql-1', 'Bài học ''Mô Hình Thực Thể Mối Kết Hợp (ERD)'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Thiết kế cơ sở dữ liệu mức khái niệm Nội dung trọng tâm gồm việc hiểu rõ bản chất của Entity, Attribute, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 1, 10, '["Entity", "Attribute", "Relationship", "Cardinality (1:1, 1:N, N:M)"]'::jsonb, 'COMPLETED', 86, 'ses-top-co-so-du-lieu-sql-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-02', 'sub-db', 'Chuyển Đổi Mô Hình ERD Sang Lược Đồ Quan Hệ', 'co-so-du-lieu-sql-2', 'Bài học ''Chuyển Đổi Mô Hình ERD Sang Lược Đồ Quan Hệ'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Hiện thực hóa lược đồ bảng dữ liệu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khóa chính Primary Key, Khóa ngoại Foreign Key, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 13, '["Khóa chính Primary Key", "Khóa ngoại Foreign Key", "Bảng trung gian", "Ràng buộc toàn vẹn"]'::jsonb, 'NEEDS_REVIEW', 56, 'ses-top-co-so-du-lieu-sql-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-03', 'sub-db', 'Ngôn Ngữ SQL: Truy Vấn SELECT & Mệnh Đề JOIN', 'co-so-du-lieu-sql-3', 'Bài học ''Ngôn Ngữ SQL: Truy Vấn SELECT & Mệnh Đề JOIN'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Khai vấn dữ liệu quan hệ nâng cao Nội dung trọng tâm gồm việc hiểu rõ bản chất của INNER JOIN, LEFT JOIN, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 3, 10, '["INNER JOIN", "LEFT JOIN", "GROUP BY", "HAVING", "Subquery"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-co-so-du-lieu-sql-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-04', 'sub-db', 'Chuẩn Hóa Dữ Liệu: 1NF, 2NF và 3NF', 'co-so-du-lieu-sql-4', 'Bài học ''Chuẩn Hóa Dữ Liệu: 1NF, 2NF và 3NF'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Loại bỏ dư thừa và bất thường cập nhật Nội dung trọng tâm gồm việc hiểu rõ bản chất của Phụ thuộc hàm, 1NF (Nguyên tử), vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 4, 7, '["Phụ thuộc hàm", "1NF (Nguyên tử)", "2NF (Phụ thuộc đầy đủ)", "3NF (Không bắc cầu)"]'::jsonb, 'NEEDS_REVIEW', 50, 'ses-top-co-so-du-lieu-sql-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-05', 'sub-db', 'Chuẩn Boyce-Codd (BCNF) & Phân Rã Không Mất Thông Tin', 'co-so-du-lieu-sql-5', 'Bài học ''Chuẩn Boyce-Codd (BCNF) & Phân Rã Không Mất Thông Tin'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Mức chuẩn hóa khắt khe Nội dung trọng tâm gồm việc hiểu rõ bản chất của Định thức là siêu khóa, Bảo toàn phụ thuộc hàm, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 5, 13, '["Định thức là siêu khóa", "Bảo toàn phụ thuộc hàm", "Mất mát thông tin"]'::jsonb, 'COMPLETED', 86, 'ses-top-co-so-du-lieu-sql-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-06', 'sub-db', 'Giao Dịch Dữ Liệu & Đặc Tính ACID', 'co-so-du-lieu-sql-6', 'Bài học ''Giao Dịch Dữ Liệu & Đặc Tính ACID'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Bảo đảm tính toàn vẹn hệ thống giao dịch Nội dung trọng tâm gồm việc hiểu rõ bản chất của Atomicity, Consistency, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 6, 14, '["Atomicity", "Consistency", "Isolation", "Durability"]'::jsonb, 'COMPLETED', 90, 'ses-top-co-so-du-lieu-sql-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-07', 'sub-db', 'Các Cấp Độ Cô Lập Giao Dịch (Isolation Levels)', 'co-so-du-lieu-sql-7', 'Bài học ''Các Cấp Độ Cô Lập Giao Dịch (Isolation Levels)'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Ngăn chặn các hiện tượng dị thường đồng thời Nội dung trọng tâm gồm việc hiểu rõ bản chất của Read Uncommitted, Read Committed, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 7, 7, '["Read Uncommitted", "Read Committed", "Repeatable Read", "Serializable", "Phantom Read"]'::jsonb, 'COMPLETED', 92, 'ses-top-co-so-du-lieu-sql-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-08', 'sub-db', 'Chỉ Mục B-Tree & Tối Ưu Hóa Truy Vấn', 'co-so-du-lieu-sql-8', 'Bài học ''Chỉ Mục B-Tree & Tối Ưu Hóa Truy Vấn'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Tăng tốc độ truy xuất dữ liệu Nội dung trọng tâm gồm việc hiểu rõ bản chất của B-Tree Node, Index Scan vs Seq Scan, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 8, 15, '["B-Tree Node", "Index Scan vs Seq Scan", "Composite Index", "Cost Planner"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-09', 'sub-db', 'Cơ Chế Khóa (Locking) & Phòng Chống Deadlock Trong CSDL', 'co-so-du-lieu-sql-9', 'Bài học ''Cơ Chế Khóa (Locking) & Phòng Chống Deadlock Trong CSDL'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Quản lý truy cập tương tranh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Shared Lock, Exclusive Lock, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 9, 12, '["Shared Lock", "Exclusive Lock", "Two-Phase Locking (2PL)", "Deadlock Detection"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-10', 'sub-db', 'Thủ Tục Lưu Trữ (Stored Procedure) & Trigger', 'co-so-du-lieu-sql-10', 'Bài học ''Thủ Tục Lưu Trữ (Stored Procedure) & Trigger'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Lập trình logic mức cơ sở dữ liệu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Trigger BEFORE/AFTER, Stored Procedure, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 14, '["Trigger BEFORE/AFTER", "Stored Procedure", "Function", "Audit Logging"]'::jsonb, 'COMPLETED', 86, 'ses-top-co-so-du-lieu-sql-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-11', 'sub-db', 'Cơ Chế Nhật Ký Ghi Trước WAL (Write-Ahead Logging)', 'co-so-du-lieu-sql-11', 'Bài học ''Cơ Chế Nhật Ký Ghi Trước WAL (Write-Ahead Logging)'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Khôi phục dữ liệu sau sự cố hệ thống Nội dung trọng tâm gồm việc hiểu rõ bản chất của WAL Buffer, Checkpoint, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 11, 11, '["WAL Buffer", "Checkpoint", "Crash Recovery", "Redo/Undo Log"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-12', 'sub-db', 'Mô Hình Cơ Sở Dữ Liệu NoSQL & Định Lý CAP', 'co-so-du-lieu-sql-12', 'Bài học ''Mô Hình Cơ Sở Dữ Liệu NoSQL & Định Lý CAP'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Hệ thống lưu trữ phi quan hệ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Document Store, Key-Value, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 12, 15, '["Document Store", "Key-Value", "Consistency vs Availability vs Partition"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-13', 'sub-db', 'Cơ Sở Dữ Liệu & Hệ Quản Trị SQL - Chuyên Đề Nâng Cao #1', 'co-so-du-lieu-sql-13', 'Bài học ''Cơ Sở Dữ Liệu & Hệ Quản Trị SQL - Chuyên Đề Nâng Cao #1'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 13, 11, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-14', 'sub-db', 'Cơ Sở Dữ Liệu & Hệ Quản Trị SQL - Chuyên Đề Nâng Cao #2', 'co-so-du-lieu-sql-14', 'Bài học ''Cơ Sở Dữ Liệu & Hệ Quản Trị SQL - Chuyên Đề Nâng Cao #2'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #2A, Kỹ thuật tối ưu #2B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 14, 9, '["Khái niệm nâng cao #2A", "Kỹ thuật tối ưu #2B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NEEDS_REVIEW', 54, 'ses-top-co-so-du-lieu-sql-14');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-co-so-du-lieu-sql-15', 'sub-db', 'Cơ Sở Dữ Liệu & Hệ Quản Trị SQL - Chuyên Đề Nâng Cao #3', 'co-so-du-lieu-sql-15', 'Bài học ''Cơ Sở Dữ Liệu & Hệ Quản Trị SQL - Chuyên Đề Nâng Cao #3'' thuộc môn Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Cơ Sở Dữ Liệu & Hệ Quản Trị SQL. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #3A, Kỹ thuật tối ưu #3B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 15, 15, '["Khái niệm nâng cao #3A", "Kỹ thuật tối ưu #3B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-01', 'sub-networks', 'Mô Hình Tham Chiếu OSI & Bộ Giao Thức TCP/IP', 'mang-may-tinh-truyen-thong-1', 'Bài học ''Mô Hình Tham Chiếu OSI & Bộ Giao Thức TCP/IP'' thuộc môn Mạng Máy Tính & Truyền Thông. Kiến trúc mạng phân tầng kinh điển Nội dung trọng tâm gồm việc hiểu rõ bản chất của 7 tầng OSI, 4 tầng TCP/IP, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 1, 7, '["7 tầng OSI", "4 tầng TCP/IP", "Đóng gói dữ liệu", "PDU"]'::jsonb, 'NEEDS_REVIEW', 63, 'ses-top-mang-may-tinh-truyen-thong-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-02', 'sub-networks', 'Tầng Liên Kết Dữ Liệu: Khung Tin & Giao Thức Ethernet', 'mang-may-tinh-truyen-thong-2', 'Bài học ''Tầng Liên Kết Dữ Liệu: Khung Tin & Giao Thức Ethernet'' thuộc môn Mạng Máy Tính & Truyền Thông. Truyền thông tin cậy trong mạng cục bộ LAN Nội dung trọng tâm gồm việc hiểu rõ bản chất của Frame, Địa chỉ MAC, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 2, 11, '["Frame", "Địa chỉ MAC", "CSMA/CD", "VLAN"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-03', 'sub-networks', 'Giao Thức IP & Kỹ Thuật Chia Mạng Con (Subnetting / CIDR)', 'mang-may-tinh-truyen-thong-3', 'Bài học ''Giao Thức IP & Kỹ Thuật Chia Mạng Con (Subnetting / CIDR)'' thuộc môn Mạng Máy Tính & Truyền Thông. Định danh và định tuyến trong liên mạng Nội dung trọng tâm gồm việc hiểu rõ bản chất của IPv4, Subnet Mask, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 3, 8, '["IPv4", "Subnet Mask", "CIDR Prefix", "Default Gateway"]'::jsonb, 'COMPLETED', 98, 'ses-top-mang-may-tinh-truyen-thong-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-04', 'sub-networks', 'Giao Thức Phân Giải Địa Chỉ ARP & DHCP', 'mang-may-tinh-truyen-thong-4', 'Bài học ''Giao Thức Phân Giải Địa Chỉ ARP & DHCP'' thuộc môn Mạng Máy Tính & Truyền Thông. Cơ chế cấu hình mạng tự động Nội dung trọng tâm gồm việc hiểu rõ bản chất của ARP Request/Reply, ARP Cache, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 4, 8, '["ARP Request/Reply", "ARP Cache", "DHCP DORA", "IP Lease"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-05', 'sub-networks', 'Giao Thức Bắt Tay 3 Bước TCP (3-Way Handshake)', 'mang-may-tinh-truyen-thong-5', 'Bài học ''Giao Thức Bắt Tay 3 Bước TCP (3-Way Handshake)'' thuộc môn Mạng Máy Tính & Truyền Thông. Thiết lập kết nối truyền vận tin cậy Nội dung trọng tâm gồm việc hiểu rõ bản chất của SYN, SYN-ACK, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 5, 9, '["SYN", "SYN-ACK", "ACK", "Sequence Number", "TCP Teardown"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-06', 'sub-networks', 'Cơ Chế Kiểm Soát Tắc Nghẽn & Luồng Dữ Liệu TCP', 'mang-may-tinh-truyen-thong-6', 'Bài học ''Cơ Chế Kiểm Soát Tắc Nghẽn & Luồng Dữ Liệu TCP'' thuộc môn Mạng Máy Tính & Truyền Thông. Ổn định băng thông mạng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Sliding Window, Slow Start, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 6, 9, '["Sliding Window", "Slow Start", "Congestion Avoidance", "Fast Retransmit"]'::jsonb, 'NEEDS_REVIEW', 65, 'ses-top-mang-may-tinh-truyen-thong-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-07', 'sub-networks', 'Giao Thức UDP & Ứng Dụng Truyền Phát Thời Gian Thực', 'mang-may-tinh-truyen-thong-7', 'Bài học ''Giao Thức UDP & Ứng Dụng Truyền Phát Thời Gian Thực'' thuộc môn Mạng Máy Tính & Truyền Thông. Truyền tải phi kết nối tốc độ cao Nội dung trọng tâm gồm việc hiểu rõ bản chất của Connectionless, Header 8 bytes, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 10, '["Connectionless", "Header 8 bytes", "VoIP", "Video Streaming"]'::jsonb, 'NEEDS_REVIEW', 61, 'ses-top-mang-may-tinh-truyen-thong-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-08', 'sub-networks', 'Hệ Thống Phân Giải Tên Miền DNS', 'mang-may-tinh-truyen-thong-8', 'Bài học ''Hệ Thống Phân Giải Tên Miền DNS'' thuộc môn Mạng Máy Tính & Truyền Thông. Bản đồ địa chỉ Internet toàn cầu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Recursive Resolver, Root/TLD Server, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 8, 10, '["Recursive Resolver", "Root/TLD Server", "Authoritative DNS", "DNS Cache"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-09', 'sub-networks', 'Giao Thức HTTP/1.1, HTTP/2 và HTTP/3 (QUIC)', 'mang-may-tinh-truyen-thong-9', 'Bài học ''Giao Thức HTTP/1.1, HTTP/2 và HTTP/3 (QUIC)'' thuộc môn Mạng Máy Tính & Truyền Thông. Tiến trình phát triển giao thức Web Nội dung trọng tâm gồm việc hiểu rõ bản chất của Keep-Alive, Multiplexing, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 9, 12, '["Keep-Alive", "Multiplexing", "QUIC UDP", "Head-of-Line Blocking"]'::jsonb, 'COMPLETED', 94, 'ses-top-mang-may-tinh-truyen-thong-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-10', 'sub-networks', 'Bảo Mật Giao Vận TLS/SSL & Chứng Chỉ Số', 'mang-may-tinh-truyen-thong-10', 'Bài học ''Bảo Mật Giao Vận TLS/SSL & Chứng Chỉ Số'' thuộc môn Mạng Máy Tính & Truyền Thông. Mã hóa bảo vệ dữ liệu truyền tải Nội dung trọng tâm gồm việc hiểu rõ bản chất của TLS Handshake, Asymmetric Key, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 10, 14, '["TLS Handshake", "Asymmetric Key", "Symmetric Cipher", "CA Certificate"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-11', 'sub-networks', 'Định Tuyến Động: Giao Thức OSPF & BGP', 'mang-may-tinh-truyen-thong-11', 'Bài học ''Định Tuyến Động: Giao Thức OSPF & BGP'' thuộc môn Mạng Máy Tính & Truyền Thông. Tìm đường tối ưu trên mạng toàn cầu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Link-State OSPF, Path-Vector BGP, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 11, 12, '["Link-State OSPF", "Path-Vector BGP", "Autonomous System", "Routing Table"]'::jsonb, 'COMPLETED', 85, 'ses-top-mang-may-tinh-truyen-thong-11');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-12', 'sub-networks', 'Tường Lửa (Firewall) & Dịch Địa Chỉ Mạng NAT', 'mang-may-tinh-truyen-thong-12', 'Bài học ''Tường Lửa (Firewall) & Dịch Địa Chỉ Mạng NAT'' thuộc môn Mạng Máy Tính & Truyền Thông. Bảo vệ an ninh mạng biên Nội dung trọng tâm gồm việc hiểu rõ bản chất của Stateful Firewall, Packet Filtering, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 12, 10, '["Stateful Firewall", "Packet Filtering", "NAT Overload (PAT)", "DMZ"]'::jsonb, 'NEEDS_REVIEW', 55, 'ses-top-mang-may-tinh-truyen-thong-12');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-13', 'sub-networks', 'Mạng Máy Tính & Truyền Thông - Chuyên Đề Nâng Cao #1', 'mang-may-tinh-truyen-thong-13', 'Bài học ''Mạng Máy Tính & Truyền Thông - Chuyên Đề Nâng Cao #1'' thuộc môn Mạng Máy Tính & Truyền Thông. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Mạng Máy Tính & Truyền Thông. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 13, 7, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'COMPLETED', 94, 'ses-top-mang-may-tinh-truyen-thong-13');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-mang-may-tinh-truyen-thong-14', 'sub-networks', 'Mạng Máy Tính & Truyền Thông - Chuyên Đề Nâng Cao #2', 'mang-may-tinh-truyen-thong-14', 'Bài học ''Mạng Máy Tính & Truyền Thông - Chuyên Đề Nâng Cao #2'' thuộc môn Mạng Máy Tính & Truyền Thông. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Mạng Máy Tính & Truyền Thông. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #2A, Kỹ thuật tối ưu #2B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 14, 12, '["Khái niệm nâng cao #2A", "Kỹ thuật tối ưu #2B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'COMPLETED', 84, 'ses-top-mang-may-tinh-truyen-thong-14');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-01', 'sub-microecon', 'Quy Luật Cung Cầu & Trọng Tâm Giá Cân Bằng', 'kinh-te-vi-mo-1', 'Bài học ''Quy Luật Cung Cầu & Trọng Tâm Giá Cân Bằng'' thuộc môn Kinh Tế Học Vi Mô. Cơ chế vận hành của bàn tay vô hình Nội dung trọng tâm gồm việc hiểu rõ bản chất của Cầu thị trường, Cung thị trường, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 1, 14, '["Cầu thị trường", "Cung thị trường", "Giá cân bằng", "Dư thừa và thiếu hụt"]'::jsonb, 'COMPLETED', 94, 'ses-top-kinh-te-vi-mo-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-02', 'sub-microecon', 'Độ Co Giãn Của Cầu Theo Giá & Doanh Thu', 'kinh-te-vi-mo-2', 'Bài học ''Độ Co Giãn Của Cầu Theo Giá & Doanh Thu'' thuộc môn Kinh Tế Học Vi Mô. Đo lường mức độ phản ứng của người mua Nội dung trọng tâm gồm việc hiểu rõ bản chất của Co giãn theo giá, Co giãn chéo, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 2, 10, '["Co giãn theo giá", "Co giãn chéo", "Co giãn theo thu nhập", "Doanh thu tối đa"]'::jsonb, 'NEEDS_REVIEW', 63, 'ses-top-kinh-te-vi-mo-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-03', 'sub-microecon', 'Lý Thuyết Lợi Ích & Sự Lựa Chọn Của Người Tiêu Dùng', 'kinh-te-vi-mo-3', 'Bài học ''Lý Thuyết Lợi Ích & Sự Lựa Chọn Của Người Tiêu Dùng'' thuộc môn Kinh Tế Học Vi Mô. Quyết định tối đa hóa thỏa dụng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tổng lợi ích TU, Lợi ích cận biên MU, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 10, '["Tổng lợi ích TU", "Lợi ích cận biên MU", "Quy luật lợi ích cận biên giảm dần", "Đường đẳng ích"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-04', 'sub-microecon', 'Chi Phí Cơ Hội & Đường Giới Hạn Khả Năng Sản Xuất (PPF)', 'kinh-te-vi-mo-4', 'Bài học ''Chi Phí Cơ Hội & Đường Giới Hạn Khả Năng Sản Xuất (PPF)'' thuộc môn Kinh Tế Học Vi Mô. Sự đánh đổi trong phân bổ nguồn lực Nội dung trọng tâm gồm việc hiểu rõ bản chất của Sự khan hiếm, Chi phí cơ hội, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 4, 12, '["Sự khan hiếm", "Chi phí cơ hội", "Hiệu quả sản xuất", "Tăng trưởng kinh tế"]'::jsonb, 'COMPLETED', 90, 'ses-top-kinh-te-vi-mo-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-05', 'sub-microecon', 'Hàm Sản Xuất & Năng Suất Cận Biên Giảm Dần', 'kinh-te-vi-mo-5', 'Bài học ''Hàm Sản Xuất & Năng Suất Cận Biên Giảm Dần'' thuộc môn Kinh Tế Học Vi Mô. Hiệu suất yếu tố đầu vào Nội dung trọng tâm gồm việc hiểu rõ bản chất của Đầu vào cố định/biến đổi, Năng suất trung bình AP, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 5, 7, '["Đầu vào cố định/biến đổi", "Năng suất trung bình AP", "Năng suất cận biên MP", "Quy mô tối ưu"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-kinh-te-vi-mo-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-06', 'sub-microecon', 'Cấu Trúc Chi Phí Doanh Nghiệp Trong Ngắn Hạn & Dài Hạn', 'kinh-te-vi-mo-6', 'Bài học ''Cấu Trúc Chi Phí Doanh Nghiệp Trong Ngắn Hạn & Dài Hạn'' thuộc môn Kinh Tế Học Vi Mô. Phân tích kinh tế cho quyết định sản xuất Nội dung trọng tâm gồm việc hiểu rõ bản chất của Chi phí cố định FC, Chi phí biến đổi VC, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 6, 8, '["Chi phí cố định FC", "Chi phí biến đổi VC", "Chi phí cận biên MC", "Chi phí trung bình ATC"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-07', 'sub-microecon', 'Thị Trường Cạnh Tranh Hoàn Hảo & Điểm Hòa Vốn', 'kinh-te-vi-mo-7', 'Bài học ''Thị Trường Cạnh Tranh Hoàn Hảo & Điểm Hòa Vốn'' thuộc môn Kinh Tế Học Vi Mô. Mô hình cạnh tranh lý tưởng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Người chấp nhận giá, Tối đa hóa lợi nhuận P=MC, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 7, 12, '["Người chấp nhận giá", "Tối đa hóa lợi nhuận P=MC", "Điểm hòa vốn", "Điểm đóng cửa"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-kinh-te-vi-mo-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-08', 'sub-microecon', 'Thị Trường Độc Quyền Hoàn Toàn & Định Giá Độc Quyền', 'kinh-te-vi-mo-8', 'Bài học ''Thị Trường Độc Quyền Hoàn Toàn & Định Giá Độc Quyền'' thuộc môn Kinh Tế Học Vi Mô. Quyền lực thị trường và tổn thất vô ích Nội dung trọng tâm gồm việc hiểu rõ bản chất của Rào cản gia nhập, Doanh thu cận biên MR < P, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 15, '["Rào cản gia nhập", "Doanh thu cận biên MR < P", "Sức mạnh độc quyền", "Tổn thất xã hội DWL"]'::jsonb, 'COMPLETED', 87, 'ses-top-kinh-te-vi-mo-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-09', 'sub-microecon', 'Thị Trường Cạnh Tranh Mang Tính Độc Quyền', 'kinh-te-vi-mo-9', 'Bài học ''Thị Trường Cạnh Tranh Mang Tính Độc Quyền'' thuộc môn Kinh Tế Học Vi Mô. Khác biệt hóa sản phẩm và cạnh tranh phi giá Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khác biệt hóa sản phẩm, Quảng cáo thương hiệu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 9, 11, '["Khác biệt hóa sản phẩm", "Quảng cáo thương hiệu", "Cân bằng dài hạn lợi nhuận bằng 0"]'::jsonb, 'COMPLETED', 86, 'ses-top-kinh-te-vi-mo-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-10', 'sub-microecon', 'Thị Trường Độc Quyền Nhóm & Lý Thuyết Trò Chơi', 'kinh-te-vi-mo-10', 'Bài học ''Thị Trường Độc Quyền Nhóm & Lý Thuyết Trò Chơi'' thuộc môn Kinh Tế Học Vi Mô. Hành vi tương tác chiến lược giữa các đối thủ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thế lưỡng nan của người tù, Cân bằng Nash, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 10, 8, '["Thế lưỡng nan của người tù", "Cân bằng Nash", "Cấu kết ngầm Cartel", "Đường cầu gãy"]'::jsonb, 'COMPLETED', 98, 'ses-top-kinh-te-vi-mo-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-01', 'sub-macroecon', 'Tổng Sản Phẩm Quốc Nội (GDP): Các Phương Pháp Đo Lường', 'kinh-te-vi-mo-macro-1', 'Bài học ''Tổng Sản Phẩm Quốc Nội (GDP): Các Phương Pháp Đo Lường'' thuộc môn Kinh Tế Học Vĩ Mô. Thước đo sức khỏe của toàn bộ nền kinh tế Nội dung trọng tâm gồm việc hiểu rõ bản chất của GDP danh nghĩa vs thực tế, Phương pháp chi tiêu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 1, 15, '["GDP danh nghĩa vs thực tế", "Phương pháp chi tiêu", "Phương pháp thu nhập", "Chỉ số giảm phát GDP"]'::jsonb, 'COMPLETED', 94, 'ses-top-kinh-te-vi-mo-macro-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-02', 'sub-macroecon', 'Lạm Phát & Chỉ Số Giá Tiêu Dùng (CPI)', 'kinh-te-vi-mo-macro-2', 'Bài học ''Lạm Phát & Chỉ Số Giá Tiêu Dùng (CPI)'' thuộc môn Kinh Tế Học Vĩ Mô. Biến động mức giá chung và sức mua đồng tiền Nội dung trọng tâm gồm việc hiểu rõ bản chất của Rổ hàng hóa CPI, Lạm phát cầu kéo, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 2, 10, '["Rổ hàng hóa CPI", "Lạm phát cầu kéo", "Lạm phát chi phí đẩy", "Lãi suất thực tế Fisher"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-03', 'sub-macroecon', 'Thất Nghiệp & Mối Quan Hệ Đánh Đổi Lạm Phát (Đường Phillips)', 'kinh-te-vi-mo-macro-3', 'Bài học ''Thất Nghiệp & Mối Quan Hệ Đánh Đổi Lạm Phát (Đường Phillips)'' thuộc môn Kinh Tế Học Vĩ Mô. Thị trường lao động vĩ mô Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thất nghiệp tự nhiên, Thất nghiệp chu kỳ, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 3, 14, '["Thất nghiệp tự nhiên", "Thất nghiệp chu kỳ", "Lực lượng lao động", "Đường cong Phillips"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-kinh-te-vi-mo-macro-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-04', 'sub-macroecon', 'Mô Hình Tổng Cung - Tổng Cầu (AD-AS)', 'kinh-te-vi-mo-macro-4', 'Bài học ''Mô Hình Tổng Cung - Tổng Cầu (AD-AS)'' thuộc môn Kinh Tế Học Vĩ Mô. Cân bằng vĩ mô và chu kỳ kinh tế Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tổng cầu AD, Tổng cung ngắn hạn SRAS, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 4, 7, '["Tổng cầu AD", "Tổng cung ngắn hạn SRAS", "Tổng cung dài hạn LRAS", "Cú sốc kinh tế"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-05', 'sub-macroecon', 'Chính Sách Tài Khóa & Số Nhân Chi Tiêu Chính Phủ', 'kinh-te-vi-mo-macro-5', 'Bài học ''Chính Sách Tài Khóa & Số Nhân Chi Tiêu Chính Phủ'' thuộc môn Kinh Tế Học Vĩ Mô. Công cụ điều tiết ngân sách quốc gia Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thuế và chi tiêu, Số nhân Keynes, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 5, 13, '["Thuế và chi tiêu", "Số nhân Keynes", "Thâm hụt ngân sách", "Hiệu ứng lấn át Crowding-out"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-kinh-te-vi-mo-macro-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-06', 'sub-macroecon', 'Tiền Tệ, Ngân Hàng Trung Ương & Cung Tiền (M1, M2)', 'kinh-te-vi-mo-macro-6', 'Bài học ''Tiền Tệ, Ngân Hàng Trung Ương & Cung Tiền (M1, M2)'' thuộc môn Kinh Tế Học Vĩ Mô. Hệ thống tiền tệ và tạo tiền Nội dung trọng tâm gồm việc hiểu rõ bản chất của Chức năng tiền tệ, Dự trữ bắt buộc, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 6, 14, '["Chức năng tiền tệ", "Dự trữ bắt buộc", "Số nhân tiền", "Nghiệp vụ thị trường mở OMO"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-07', 'sub-macroecon', 'Chính Sách Tiền Tệ: Lãi Suất & Kiểm Soát Lạm Phát', 'kinh-te-vi-mo-macro-7', 'Bài học ''Chính Sách Tiền Tệ: Lãi Suất & Kiểm Soát Lạm Phát'' thuộc môn Kinh Tế Học Vĩ Mô. Điều hành kinh tế qua kênh tiền tệ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Lãi suất tái cấp vốn, Nới lỏng định lượng QE, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 15, '["Lãi suất tái cấp vốn", "Nới lỏng định lượng QE", "Mục tiêu lạm phát", "Truyền dẫn chính sách"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-kinh-te-vi-mo-macro-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-08', 'sub-macroecon', 'Tỷ Giá Hối Đoái & Cán Cân Thanh Toán Quốc Tế (BOP)', 'kinh-te-vi-mo-macro-8', 'Bài học ''Tỷ Giá Hối Đoái & Cán Cân Thanh Toán Quốc Tế (BOP)'' thuộc môn Kinh Tế Học Vĩ Mô. Tương tác kinh tế qua biên giới Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tỷ giá danh nghĩa/thực, Ngang giá sức mua PPP, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 8, 9, '["Tỷ giá danh nghĩa/thực", "Ngang giá sức mua PPP", "Tài khoản vãng lai", "Dự trữ ngoại hối"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-09', 'sub-macroecon', 'Mô Hình IS-LM Trong Nền Kinh Tế Đóng', 'kinh-te-vi-mo-macro-9', 'Bài học ''Mô Hình IS-LM Trong Nền Kinh Tế Đóng'' thuộc môn Kinh Tế Học Vĩ Mô. Tương tác giữa thị trường hàng hóa và tiền tệ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Đường IS, Đường LM, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 9, 15, '["Đường IS", "Đường LM", "Cân bằng đồng thời", "Tác động chính sách tài khóa/tiền tệ"]'::jsonb, 'COMPLETED', 84, 'ses-top-kinh-te-vi-mo-macro-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-10', 'sub-macroecon', 'Tăng Trưởng Kinh Tế & Mô Hình Solow-Swan', 'kinh-te-vi-mo-macro-10', 'Bài học ''Tăng Trưởng Kinh Tế & Mô Hình Solow-Swan'' thuộc môn Kinh Tế Học Vĩ Mô. Động lực phát triển thịnh vượng dài hạn Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tích lũy vốn, Tiến bộ công nghệ, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 7, '["Tích lũy vốn", "Tiến bộ công nghệ", "Trạng thái dừng Steady State", "Năng suất tổng nhân tố TFP"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-11', 'sub-macroecon', 'Khủng Hoảng Tài Chính & Chu Kỳ Kinh Tế Toàn Cầu', 'kinh-te-vi-mo-macro-11', 'Bài học ''Khủng Hoảng Tài Chính & Chu Kỳ Kinh Tế Toàn Cầu'' thuộc môn Kinh Tế Học Vĩ Mô. Bong bóng tài sản và suy thoái kinh tế Nội dung trọng tâm gồm việc hiểu rõ bản chất của Suy thoái kinh tế, Bẫy thanh khoản, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 11, 15, '["Suy thoái kinh tế", "Bẫy thanh khoản", "Chính sách nghịch chu kỳ", "Rủi ro hệ thống"]'::jsonb, 'NEEDS_REVIEW', 64, 'ses-top-kinh-te-vi-mo-macro-11');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-12', 'sub-macroecon', 'Kinh Tế Học Vĩ Mô - Chuyên Đề Nâng Cao #1', 'kinh-te-vi-mo-macro-12', 'Bài học ''Kinh Tế Học Vĩ Mô - Chuyên Đề Nâng Cao #1'' thuộc môn Kinh Tế Học Vĩ Mô. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Kinh Tế Học Vĩ Mô. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 12, 8, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'COMPLETED', 92, 'ses-top-kinh-te-vi-mo-macro-12');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kinh-te-vi-mo-macro-13', 'sub-macroecon', 'Kinh Tế Học Vĩ Mô - Chuyên Đề Nâng Cao #2', 'kinh-te-vi-mo-macro-13', 'Bài học ''Kinh Tế Học Vĩ Mô - Chuyên Đề Nâng Cao #2'' thuộc môn Kinh Tế Học Vĩ Mô. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Kinh Tế Học Vĩ Mô. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #2A, Kỹ thuật tối ưu #2B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 13, 10, '["Khái niệm nâng cao #2A", "Kỹ thuật tối ưu #2B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'COMPLETED', 85, 'ses-top-kinh-te-vi-mo-macro-13');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-01', 'sub-acc-principles', 'Phương Trình Kế Toán Cơ Bản: Tài Sản & Nguồn Vốn', 'nguyen-ly-ke-toan-1', 'Bài học ''Phương Trình Kế Toán Cơ Bản: Tài Sản & Nguồn Vốn'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Nền móng của toàn bộ hệ thống kế toán Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tài sản = Nợ phải trả + Vốn chủ sở hữu, Đối ứng kế toán, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 1, 10, '["Tài sản = Nợ phải trả + Vốn chủ sở hữu", "Đối ứng kế toán", "Thực thể kinh doanh"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-02', 'sub-acc-principles', 'Hệ Thống Tài Khoản Kế Toán & Nguyên Lý Ghi Kép (Nợ - Có)', 'nguyen-ly-ke-toan-2', 'Bài học ''Hệ Thống Tài Khoản Kế Toán & Nguyên Lý Ghi Kép (Nợ - Có)'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Phương pháp hạch toán sổ sách Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tài khoản chữ T, Quy tắc ghi Nợ/Có, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 13, '["Tài khoản chữ T", "Quy tắc ghi Nợ/Có", "Số dư đầu/cuối kỳ", "Bảng cân đối số phát sinh"]'::jsonb, 'NEEDS_REVIEW', 50, 'ses-top-nguyen-ly-ke-toan-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-03', 'sub-acc-principles', 'Chứng Từ Kế Toán & Quy Trình Luân Chuyển Chứng Từ', 'nguyen-ly-ke-toan-3', 'Bài học ''Chứng Từ Kế Toán & Quy Trình Luân Chuyển Chứng Từ'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Bằng chứng pháp lý cho các nghiệp vụ phát sinh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Hóa đơn GTGT, Phiếu thu/chi, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 3, 12, '["Hóa đơn GTGT", "Phiếu thu/chi", "Phiếu nhập/xuất kho", "Kiểm tra tính hợp lệ"]'::jsonb, 'NEEDS_REVIEW', 64, 'ses-top-nguyen-ly-ke-toan-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-04', 'sub-acc-principles', 'Kế Toán Nghiệp Vụ Mua Hàng & Quản Lý Hàng Tồn Kho', 'nguyen-ly-ke-toan-4', 'Bài học ''Kế Toán Nghiệp Vụ Mua Hàng & Quản Lý Hàng Tồn Kho'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Theo dõi dòng vận chuyển hàng hóa Nội dung trọng tâm gồm việc hiểu rõ bản chất của Phương pháp kê khai thường xuyên, Kiểm kê định kỳ, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 4, 12, '["Phương pháp kê khai thường xuyên", "Kiểm kê định kỳ", "Chi phí mua hàng", "Chiết khấu thương mại"]'::jsonb, 'COMPLETED', 95, 'ses-top-nguyen-ly-ke-toan-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-05', 'sub-acc-principles', 'Các Phương Pháp Tính Giá Hàng Tồn Kho (FIFO, Bình Quân)', 'nguyen-ly-ke-toan-5', 'Bài học ''Các Phương Pháp Tính Giá Hàng Tồn Kho (FIFO, Bình Quân)'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Định giá giá vốn hàng bán Nội dung trọng tâm gồm việc hiểu rõ bản chất của FIFO (Nhập trước xuất trước), Bình quân gia quyền, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 5, 11, '["FIFO (Nhập trước xuất trước)", "Bình quân gia quyền", "Ảnh hưởng đến lợi nhuận và thuế"]'::jsonb, 'COMPLETED', 86, 'ses-top-nguyen-ly-ke-toan-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-06', 'sub-acc-principles', 'Kế Toán Bán Hàng & Xác Định Kết Quả Kinh Doanh', 'nguyen-ly-ke-toan-6', 'Bài học ''Kế Toán Bán Hàng & Xác Định Kết Quả Kinh Doanh'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Ghi nhận doanh thu và chi phí hợp lý Nội dung trọng tâm gồm việc hiểu rõ bản chất của Doanh thu thuần, Giá vốn hàng bán COGS, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 6, 8, '["Doanh thu thuần", "Giá vốn hàng bán COGS", "Chi phí bán hàng", "Lợi nhuận gộp"]'::jsonb, 'COMPLETED', 96, 'ses-top-nguyen-ly-ke-toan-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-07', 'sub-acc-principles', 'Kế Toán Tiền Lương & Các Khoản Trích Theo Lương', 'nguyen-ly-ke-toan-7', 'Bài học ''Kế Toán Tiền Lương & Các Khoản Trích Theo Lương'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Quyền lợi người lao động và nghĩa vụ doanh nghiệp Nội dung trọng tâm gồm việc hiểu rõ bản chất của Bảo hiểm xã hội, Bảo hiểm y tế, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 7, 8, '["Bảo hiểm xã hội", "Bảo hiểm y tế", "Kinh phí công đoàn", "Bảng thanh toán lương"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-nguyen-ly-ke-toan-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-08', 'sub-acc-principles', 'Kế Toán Tài Sản Cố Định & Khấu Hao Tài Sản', 'nguyen-ly-ke-toan-8', 'Bài học ''Kế Toán Tài Sản Cố Định & Khấu Hao Tài Sản'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Phân bổ chi phí đầu tư dài hạn Nội dung trọng tâm gồm việc hiểu rõ bản chất của Nguyên giá tài sản, Khấu hao đường thẳng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 11, '["Nguyên giá tài sản", "Khấu hao đường thẳng", "Khấu hao nhanh", "Thanh lý tài sản"]'::jsonb, 'NEEDS_REVIEW', 64, 'ses-top-nguyen-ly-ke-toan-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-09', 'sub-acc-principles', 'Các Bút Toán Điều Chỉnh Cuối Kỳ & Kế Toán Dồn Tích', 'nguyen-ly-ke-toan-9', 'Bài học ''Các Bút Toán Điều Chỉnh Cuối Kỳ & Kế Toán Dồn Tích'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Đảm bảo nguyên tắc phù hợp kế toán Nội dung trọng tâm gồm việc hiểu rõ bản chất của Doanh thu chưa thực hiện, Chi phí trả trước, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 9, 8, '["Doanh thu chưa thực hiện", "Chi phí trả trước", "Chi phí phải trả", "Doanh thu dồn tích"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-10', 'sub-acc-principles', 'Bảng Cân Đối Kế Toán (Báo Cáo Tình Hình Tài Chính)', 'nguyen-ly-ke-toan-10', 'Bài học ''Bảng Cân Đối Kế Toán (Báo Cáo Tình Hình Tài Chính)'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Bức tranh tài chính tại một thời điểm Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tài sản ngắn hạn/dài hạn, Nợ ngắn hạn/dài hạn, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 9, '["Tài sản ngắn hạn/dài hạn", "Nợ ngắn hạn/dài hạn", "Vốn chủ sở hữu", "Tính cân đối"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-nguyen-ly-ke-toan-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-11', 'sub-acc-principles', 'Báo Cáo Kết Quả Hoạt Động Kinh Doanh', 'nguyen-ly-ke-toan-11', 'Bài học ''Báo Cáo Kết Quả Hoạt Động Kinh Doanh'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Đo lường hiệu quả hoạt động trong kỳ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Doanh thu thuần, Lợi nhuận gộp, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 11, 11, '["Doanh thu thuần", "Lợi nhuận gộp", "Lợi nhuận thuần từ HĐKD", "Lợi nhuận sau thuế"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-12', 'sub-acc-principles', 'Báo Cáo Lưu Chuyển Tiền Tệ & Tầm Quan Trọng Của Dòng Tiền', 'nguyen-ly-ke-toan-12', 'Bài học ''Báo Cáo Lưu Chuyển Tiền Tệ & Tầm Quan Trọng Của Dòng Tiền'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Theo dõi nguồn tiền ra vào doanh nghiệp Nội dung trọng tâm gồm việc hiểu rõ bản chất của Dòng tiền từ HĐ kinh doanh, Dòng tiền từ HĐ đầu tư, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 12, 15, '["Dòng tiền từ HĐ kinh doanh", "Dòng tiền từ HĐ đầu tư", "Dòng tiền từ HĐ tài chính", "Khả năng thanh toán"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nguyen-ly-ke-toan-13', 'sub-acc-principles', 'Nguyên Lý Kế Toán Căn Bản - Chuyên Đề Nâng Cao #1', 'nguyen-ly-ke-toan-13', 'Bài học ''Nguyên Lý Kế Toán Căn Bản - Chuyên Đề Nâng Cao #1'' thuộc môn Nguyên Lý Kế Toán Căn Bản. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Nguyên Lý Kế Toán Căn Bản. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 13, 15, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-marketing-can-ban-01', 'sub-basic-marketing', 'Bản Chất Của Marketing & Triết Lý Hướng Về Khách Hàng', 'marketing-can-ban-1', 'Bài học ''Bản Chất Của Marketing & Triết Lý Hướng Về Khách Hàng'' thuộc môn Marketing Căn Bản & Hành Vi Tiêu Dùng. Tạo dựng giá trị và xây dựng mối quan hệ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Nhu cầu - Mong muốn - Yêu cầu, Giá trị khách hàng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 1, 9, '["Nhu cầu - Mong muốn - Yêu cầu", "Giá trị khách hàng", "Mô hình phễu Marketing", "Sự hài lòng"]'::jsonb, 'COMPLETED', 98, 'ses-top-marketing-can-ban-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-marketing-can-ban-02', 'sub-basic-marketing', 'Nghiên Cứu Thị Trường & Phân Tích Môi Trường Vĩ Mô (PESTEL)', 'marketing-can-ban-2', 'Bài học ''Nghiên Cứu Thị Trường & Phân Tích Môi Trường Vĩ Mô (PESTEL)'' thuộc môn Marketing Căn Bản & Hành Vi Tiêu Dùng. Thấu hiểu bối cảnh kinh doanh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Môi trường PESTEL, Nghiên cứu định tính/định lượng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 2, 15, '["Môi trường PESTEL", "Nghiên cứu định tính/định lượng", "Dữ liệu sơ cấp và thứ cấp"]'::jsonb, 'COMPLETED', 85, 'ses-top-marketing-can-ban-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-marketing-can-ban-03', 'sub-basic-marketing', 'Mô Hình Hành Vi Mua Của Khách Hàng Cá Nhân & Doanh Nghiệp (B2B)', 'marketing-can-ban-3', 'Bài học ''Mô Hình Hành Vi Mua Của Khách Hàng Cá Nhân & Doanh Nghiệp (B2B)'' thuộc môn Marketing Căn Bản & Hành Vi Tiêu Dùng. Giải mã tâm lý ra quyết định mua Nội dung trọng tâm gồm việc hiểu rõ bản chất của Các giai đoạn quyết định mua, Động cơ Maslow, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 3, 10, '["Các giai đoạn quyết định mua", "Động cơ Maslow", "Yếu tố xã hội", "Hành vi B2B vs B2C"]'::jsonb, 'COMPLETED', 93, 'ses-top-marketing-can-ban-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-marketing-can-ban-04', 'sub-basic-marketing', 'Chiến Lược Phân Khúc Thị Trường (Segmentation)', 'marketing-can-ban-4', 'Bài học ''Chiến Lược Phân Khúc Thị Trường (Segmentation)'' thuộc môn Marketing Căn Bản & Hành Vi Tiêu Dùng. Chia nhỏ thị trường theo đặc tính tương đồng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Nhân khẩu học, Địa lý, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 4, 11, '["Nhân khẩu học", "Địa lý", "Tâm lý học", "Hành vi mua sắm"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-marketing-can-ban-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-marketing-can-ban-05', 'sub-basic-marketing', 'Lựa Chọn Thị Trường Mục Tiêu (Targeting)', 'marketing-can-ban-5', 'Bài học ''Lựa Chọn Thị Trường Mục Tiêu (Targeting)'' thuộc môn Marketing Căn Bản & Hành Vi Tiêu Dùng. Tập trung nguồn lực vào nhóm khách hàng tiềm năng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Marketing không phân biệt, Marketing phân biệt, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 5, 8, '["Marketing không phân biệt", "Marketing phân biệt", "Marketing tập trung (Niche)"]'::jsonb, 'NEEDS_REVIEW', 49, 'ses-top-marketing-can-ban-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-marketing-can-ban-06', 'sub-basic-marketing', 'Định Vị Thương Hiệu (Positioning) & Bản Đồ Định Vị', 'marketing-can-ban-6', 'Bài học ''Định Vị Thương Hiệu (Positioning) & Bản Đồ Định Vị'' thuộc môn Marketing Căn Bản & Hành Vi Tiêu Dùng. Khắc sâu hình ảnh độc nhất trong tâm trí khách hàng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tuyên ngôn định vị, Điểm khác biệt POD, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 6, 11, '["Tuyên ngôn định vị", "Điểm khác biệt POD", "Điểm tương đồng POP", "Bản đồ định vị"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-marketing-can-ban-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-marketing-can-ban-07', 'sub-basic-marketing', 'Chiến Lược Sản Phẩm (Product) & Vòng Đời Sản Phẩm (PLC)', 'marketing-can-ban-7', 'Bài học ''Chiến Lược Sản Phẩm (Product) & Vòng Đời Sản Phẩm (PLC)'' thuộc môn Marketing Căn Bản & Hành Vi Tiêu Dùng. Phát triển và quản trị danh mục sản phẩm Nội dung trọng tâm gồm việc hiểu rõ bản chất của Cấu trúc 3 cấp độ sản phẩm, Vòng đời sản phẩm PLC, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 7, 9, '["Cấu trúc 3 cấp độ sản phẩm", "Vòng đời sản phẩm PLC", "Quản trị danh mục BCG"]'::jsonb, 'COMPLETED', 96, 'ses-top-marketing-can-ban-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-marketing-can-ban-08', 'sub-basic-marketing', 'Chiến Lược Giá (Pricing): Các Phương Pháp Định Giá Căn Bản', 'marketing-can-ban-8', 'Bài học ''Chiến Lược Giá (Pricing): Các Phương Pháp Định Giá Căn Bản'' thuộc môn Marketing Căn Bản & Hành Vi Tiêu Dùng. Cân bằng giữa chi phí, giá trị và cạnh tranh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Định giá cộng chi phí, Định giá hớt váng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 8, 9, '["Định giá cộng chi phí", "Định giá hớt váng", "Định giá thâm nhập", "Định giá theo giá trị"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-marketing-can-ban-09', 'sub-basic-marketing', 'Chiến Lược Kênh Phân Phối (Place) & Logistics Tiếp Thị', 'marketing-can-ban-9', 'Bài học ''Chiến Lược Kênh Phân Phối (Place) & Logistics Tiếp Thị'' thuộc môn Marketing Căn Bản & Hành Vi Tiêu Dùng. Đưa sản phẩm đến tay người dùng hiệu quả Nội dung trọng tâm gồm việc hiểu rõ bản chất của Kênh trực tiếp/gián tiếp, Xung đột kênh, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 9, 13, '["Kênh trực tiếp/gián tiếp", "Xung đột kênh", "Phân phối độc quyền vs rộng rãi", "Omnichannel"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-marketing-can-ban-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-marketing-can-ban-10', 'sub-basic-marketing', 'Chiến Lược Chiêu Thị & Truyền Thông Tích Hợp (IMC)', 'marketing-can-ban-10', 'Bài học ''Chiến Lược Chiêu Thị & Truyền Thông Tích Hợp (IMC)'' thuộc môn Marketing Căn Bản & Hành Vi Tiêu Dùng. Kết hợp đồng bộ các công cụ truyền thông Nội dung trọng tâm gồm việc hiểu rõ bản chất của Quảng cáo, Quan hệ công chúng PR, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 10, 9, '["Quảng cáo", "Quan hệ công chúng PR", "Khuyến mãi bán hàng", "Bán hàng cá nhân"]'::jsonb, 'COMPLETED', 85, 'ses-top-marketing-can-ban-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-marketing-can-ban-11', 'sub-basic-marketing', 'Quản Trị Thương Hiệu & Tài Sản Thương Hiệu (Brand Equity)', 'marketing-can-ban-11', 'Bài học ''Quản Trị Thương Hiệu & Tài Sản Thương Hiệu (Brand Equity)'' thuộc môn Marketing Căn Bản & Hành Vi Tiêu Dùng. Gia tăng giá trị vô hình cho doanh nghiệp Nội dung trọng tâm gồm việc hiểu rõ bản chất của Nhận biết thương hiệu, Liên tưởng thương hiệu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 11, 15, '["Nhận biết thương hiệu", "Liên tưởng thương hiệu", "Chất lượng cảm nhận", "Lòng trung thành"]'::jsonb, 'COMPLETED', 89, 'ses-top-marketing-can-ban-11');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-marketing-can-ban-12', 'sub-basic-marketing', 'Marketing Căn Bản & Hành Vi Tiêu Dùng - Chuyên Đề Nâng Cao #1', 'marketing-can-ban-12', 'Bài học ''Marketing Căn Bản & Hành Vi Tiêu Dùng - Chuyên Đề Nâng Cao #1'' thuộc môn Marketing Căn Bản & Hành Vi Tiêu Dùng. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Marketing Căn Bản & Hành Vi Tiêu Dùng. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 12, 7, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-marketing-can-ban-12');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-phap-luat-dai-cuong-kinh-te-01', 'sub-biz-law', 'Hệ Thống Pháp Luật Việt Nam & Các Nguồn Của Pháp Luật', 'phap-luat-dai-cuong-kinh-te-1', 'Bài học ''Hệ Thống Pháp Luật Việt Nam & Các Nguồn Của Pháp Luật'' thuộc môn Pháp Luật Đại Cương & Luật Kinh Tế. Kiến thức pháp lý nền tảng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Văn bản quy phạm pháp luật, Hiến pháp, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 1, 7, '["Văn bản quy phạm pháp luật", "Hiến pháp", "Luật và Nghị định", "Hiệu lực văn bản"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-phap-luat-dai-cuong-kinh-te-02', 'sub-biz-law', 'Địa Vị Pháp Lý Doanh Nghiệp: Công Ty TNHH & Công Ty Cổ Phần', 'phap-luat-dai-cuong-kinh-te-2', 'Bài học ''Địa Vị Pháp Lý Doanh Nghiệp: Công Ty TNHH & Công Ty Cổ Phần'' thuộc môn Pháp Luật Đại Cương & Luật Kinh Tế. Lựa chọn loại hình doanh nghiệp phù hợp Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tư cách pháp nhân, Trách nhiệm hữu hạn vs vô hạn, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 2, 8, '["Tư cách pháp nhân", "Trách nhiệm hữu hạn vs vô hạn", "Cổ đông và thành viên góp vốn"]'::jsonb, 'COMPLETED', 87, 'ses-top-phap-luat-dai-cuong-kinh-te-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-phap-luat-dai-cuong-kinh-te-03', 'sub-biz-law', 'Doanh Nghiệp Tư Nhân & Hộ Kinh Doanh Cá Thể', 'phap-luat-dai-cuong-kinh-te-3', 'Bài học ''Doanh Nghiệp Tư Nhân & Hộ Kinh Doanh Cá Thể'' thuộc môn Pháp Luật Đại Cương & Luật Kinh Tế. Mô hình kinh doanh cá thể Nội dung trọng tâm gồm việc hiểu rõ bản chất của Trách nhiệm vô hạn, Đăng ký kinh doanh, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 13, '["Trách nhiệm vô hạn", "Đăng ký kinh doanh", "Quyền và nghĩa vụ của chủ DNTN"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-phap-luat-dai-cuong-kinh-te-04', 'sub-biz-law', 'Pháp Luật Về Hợp Đồng Thương Mại: Giao Kết & Hiệu Lực', 'phap-luat-dai-cuong-kinh-te-4', 'Bài học ''Pháp Luật Về Hợp Đồng Thương Mại: Giao Kết & Hiệu Lực'' thuộc môn Pháp Luật Đại Cương & Luật Kinh Tế. Ràng buộc pháp lý trong giao dịch kinh doanh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Đề nghị giao kết, Chấp nhận đề nghị, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 4, 10, '["Đề nghị giao kết", "Chấp nhận đề nghị", "Điều kiện có hiệu lực", "Hợp đồng vô hiệu"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-phap-luat-dai-cuong-kinh-te-05', 'sub-biz-law', 'Các Biện Pháp Bảo Đảm Thực Hiện Hợp Đồng', 'phap-luat-dai-cuong-kinh-te-5', 'Bài học ''Các Biện Pháp Bảo Đảm Thực Hiện Hợp Đồng'' thuộc môn Pháp Luật Đại Cương & Luật Kinh Tế. Phòng ngừa rủi ro vi phạm nghĩa vụ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Cầm cố, Thế chấp, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 5, 9, '["Cầm cố", "Thế chấp", "Đặt cọc", "Bảo lãnh"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-phap-luat-dai-cuong-kinh-te-06', 'sub-biz-law', 'Trách Nhiệm Do Vi Phạm Hợp Đồng: Phạt Vi Phạm & Bồi Thường', 'phap-luat-dai-cuong-kinh-te-6', 'Bài học ''Trách Nhiệm Do Vi Phạm Hợp Đồng: Phạt Vi Phạm & Bồi Thường'' thuộc môn Pháp Luật Đại Cương & Luật Kinh Tế. Xử lý khi đối tác không thực hiện cam kết Nội dung trọng tâm gồm việc hiểu rõ bản chất của Lỗi vi phạm, Mức phạt vi phạm tối đa, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 6, 12, '["Lỗi vi phạm", "Mức phạt vi phạm tối đa", "Thiệt hại thực tế", "Miễn trừ trách nhiệm"]'::jsonb, 'COMPLETED', 95, 'ses-top-phap-luat-dai-cuong-kinh-te-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-phap-luat-dai-cuong-kinh-te-07', 'sub-biz-law', 'Pháp Luật Về Cạnh Tranh & Chống Độc Quyền', 'phap-luat-dai-cuong-kinh-te-7', 'Bài học ''Pháp Luật Về Cạnh Tranh & Chống Độc Quyền'' thuộc môn Pháp Luật Đại Cương & Luật Kinh Tế. Bảo vệ môi trường kinh doanh lành mạnh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Hành vi hạn chế cạnh tranh, Lạm dụng vị trí thống lĩnh, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 10, '["Hành vi hạn chế cạnh tranh", "Lạm dụng vị trí thống lĩnh", "Tập trung kinh tế", "Cạnh tranh không lành mạnh"]'::jsonb, 'NOT_STARTED', NULL, NULL);
