INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tam-ly-giao-tiep-dich-vu-01', 'sub-service-comm', 'Nguyên Lý Giao Tiếp Hiệu Quả & Mô Hình Truyền Thông', 'tam-ly-giao-tiep-dich-vu-1', 'Bài học ''Nguyên Lý Giao Tiếp Hiệu Quả & Mô Hình Truyền Thông'' thuộc môn Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng. Cơ chế trao đổi thông điệp chuẩn xác Nội dung trọng tâm gồm việc hiểu rõ bản chất của Người gửi - Thông điệp - Người nhận, Nhiễu truyền thông, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 1, 11, '["Người gửi - Thông điệp - Người nhận", "Nhiễu truyền thông", "Kênh phản hồi Feedback"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tam-ly-giao-tiep-dich-vu-02', 'sub-service-comm', 'Nghệ Thuật Lắng Nghe Thấu Cảm (Active Listening)', 'tam-ly-giao-tiep-dich-vu-2', 'Bài học ''Nghệ Thuật Lắng Nghe Thấu Cảm (Active Listening)'' thuộc môn Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng. Thấu hiểu mong muốn ẩn sâu của khách hàng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Lắng nghe tích cực, Đặt câu hỏi mở/đóng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 2, 13, '["Lắng nghe tích cực", "Đặt câu hỏi mở/đóng", "Paraphrasing", "Đồng cảm cảm xúc"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tam-ly-giao-tiep-dich-vu-03', 'sub-service-comm', 'Ngôn Ngữ Cơ Thể & Giao Tiếp Phi Ngôn Từ', 'tam-ly-giao-tiep-dich-vu-3', 'Bài học ''Ngôn Ngữ Cơ Thể & Giao Tiếp Phi Ngôn Từ'' thuộc môn Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng. Sức mạnh của cử chỉ và ánh mắt Nội dung trọng tâm gồm việc hiểu rõ bản chất của Ánh mắt Eye Contact, Nụ cười và tư thế đứng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 3, 15, '["Ánh mắt Eye Contact", "Nụ cười và tư thế đứng", "Khoảng cách không gian Proxemics", "Giọng điệu"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tam-ly-giao-tiep-dich-vu-04', 'sub-service-comm', 'Tâm Lý Học Khách Hàng: Các Kiểu Tính Cách Điển Hình (DISC)', 'tam-ly-giao-tiep-dich-vu-4', 'Bài học ''Tâm Lý Học Khách Hàng: Các Kiểu Tính Cách Điển Hình (DISC)'' thuộc môn Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng. Thích ứng linh hoạt với từng đối tượng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Kiểu Thống trị D, Kiểu Ảnh hưởng I, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 4, 8, '["Kiểu Thống trị D", "Kiểu Ảnh hưởng I", "Kiểu Kiên định S", "Kiểu Tuân thủ C"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tam-ly-giao-tiep-dich-vu-05', 'sub-service-comm', 'Quy Trình Xử Lý Phàn Nàn Của Khách Hàng (Mô Hình LAST/HEAR)', 'tam-ly-giao-tiep-dich-vu-5', 'Bài học ''Quy Trình Xử Lý Phàn Nàn Của Khách Hàng (Mô Hình LAST/HEAR)'' thuộc môn Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng. Biến khách hàng giận dữ thành người ủng hộ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Lắng nghe Listen, Xin lỗi Apologize, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 5, 7, '["Lắng nghe Listen", "Xin lỗi Apologize", "Giải quyết Solve", "Cảm ơn Thank"]'::jsonb, 'COMPLETED', 88, 'ses-top-tam-ly-giao-tiep-dich-vu-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tam-ly-giao-tiep-dich-vu-06', 'sub-service-comm', 'Kỹ Năng Đàm Phán & Thuyết Phục Trong Kinh Doanh', 'tam-ly-giao-tiep-dich-vu-6', 'Bài học ''Kỹ Năng Đàm Phán & Thuyết Phục Trong Kinh Doanh'' thuộc môn Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng. Đạt thỏa thuận đôi bên cùng có lợi (Win-Win) Nội dung trọng tâm gồm việc hiểu rõ bản chất của BATNA, Điểm thỏa hiệp, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 6, 12, '["BATNA", "Điểm thỏa hiệp", "Nguyên tắc tương hỗ Cialdini", "Kỹ thuật mỏ neo"]'::jsonb, 'NEEDS_REVIEW', 59, 'ses-top-tam-ly-giao-tiep-dich-vu-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tam-ly-giao-tiep-dich-vu-07', 'sub-service-comm', 'Quản Trị Kỳ Vọng & Kiến Tạo Trải Nghiệm Khách Hàng (CX)', 'tam-ly-giao-tiep-dich-vu-7', 'Bài học ''Quản Trị Kỳ Vọng & Kiến Tạo Trải Nghiệm Khách Hàng (CX)'' thuộc môn Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng. Vượt trên cả sự mong đợi Nội dung trọng tâm gồm việc hiểu rõ bản chất của Customer Journey Map, Điểm chạm Touchpoints, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 15, '["Customer Journey Map", "Điểm chạm Touchpoints", "Moment of Truth", "Net Promoter Score NPS"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tam-ly-giao-tiep-dich-vu-08', 'sub-service-comm', 'Giao Tiếp Ứng Xử Đa Văn Hóa Trong Môi Trường Toàn Cầu', 'tam-ly-giao-tiep-dich-vu-8', 'Bài học ''Giao Tiếp Ứng Xử Đa Văn Hóa Trong Môi Trường Toàn Cầu'' thuộc môn Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng. Tôn trọng khác biệt văn hóa Nội dung trọng tâm gồm việc hiểu rõ bản chất của Văn hóa ngữ cảnh cao/thấp, Khoảng cách quyền lực, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 10, '["Văn hóa ngữ cảnh cao/thấp", "Khoảng cách quyền lực", "Kiêng kỵ văn hóa quốc tế"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-tam-ly-giao-tiep-dich-vu-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tam-ly-giao-tiep-dich-vu-09', 'sub-service-comm', 'Quản Lý Căng Thẳng & Kiểm Soát Cảm Xúc Của Nhân Viên Dịch Vụ', 'tam-ly-giao-tiep-dich-vu-9', 'Bài học ''Quản Lý Căng Thẳng & Kiểm Soát Cảm Xúc Của Nhân Viên Dịch Vụ'' thuộc môn Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng. Bảo vệ năng lượng tích cực khi làm việc Nội dung trọng tâm gồm việc hiểu rõ bản chất của Emotional Labor, Burnout, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 9, 7, '["Emotional Labor", "Burnout", "Tự điều chỉnh cảm xúc", "Chữa lành tâm lý"]'::jsonb, 'COMPLETED', 90, 'ses-top-tam-ly-giao-tiep-dich-vu-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tam-ly-giao-tiep-dich-vu-10', 'sub-service-comm', 'Xây Dựng Văn Hóa Dịch Vụ Tận Tâm (Customer-Centric)', 'tam-ly-giao-tiep-dich-vu-10', 'Bài học ''Xây Dựng Văn Hóa Dịch Vụ Tận Tâm (Customer-Centric)'' thuộc môn Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng. Biến dịch vụ khách hàng thành lợi thế cạnh tranh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tôn chỉ phụng sự, Trao quyền cho nhân viên, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 10, 15, '["Tôn chỉ phụng sự", "Trao quyền cho nhân viên", "Đo lường sự hài lòng CSAT"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tam-ly-giao-tiep-dich-vu-11', 'sub-service-comm', 'Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng - Chuyên Đề Nâng Cao #1', 'tam-ly-giao-tiep-dich-vu-11', 'Bài học ''Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng - Chuyên Đề Nâng Cao #1'' thuộc môn Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Tâm Lý Học Giao Tiếp & Dịch Vụ Khách Hàng. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 11, 10, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
