INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dien-toan-dam-may-cloud-01', 'sub-it-cloud', 'Tổng Quan Về Điện Toán Đám Mây: IaaS, PaaS và SaaS', 'dien-toan-dam-may-cloud-1', 'Bài học ''Tổng Quan Về Điện Toán Đám Mây: IaaS, PaaS và SaaS'' thuộc môn Quản Trị Hệ Thống & Điện Toán Đám Mây. Mô hình dịch vụ đám mây Nội dung trọng tâm gồm việc hiểu rõ bản chất của IaaS, PaaS, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 1, 8, '["IaaS", "PaaS", "SaaS", "Public vs Private Cloud"]'::jsonb, 'NOT_STARTED', NULL, NULL);
