INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dien-toan-dam-may-cloud-04', 'sub-it-cloud', 'Hạ Tầng Dưới Dạng Mã Nguồn (IaC) Với Terraform', 'dien-toan-dam-may-cloud-4', 'Bài học ''Hạ Tầng Dưới Dạng Mã Nguồn (IaC) Với Terraform'' thuộc môn Quản Trị Hệ Thống & Điện Toán Đám Mây. Tự động hóa triển khai đám mây Nội dung trọng tâm gồm việc hiểu rõ bản chất của Terraform Provider, State File, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 4, 15, '["Terraform Provider", "State File", "Plan & Apply", "Declarative Code"]'::jsonb, 'NOT_STARTED', NULL, NULL);
