INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dien-toan-dam-may-cloud-07', 'sub-it-cloud', 'Cân Bằng Tải (Load Balancing) & Tự Động Co Giãn (Auto Scaling)', 'dien-toan-dam-may-cloud-7', 'Bài học ''Cân Bằng Tải (Load Balancing) & Tự Động Co Giãn (Auto Scaling)'' thuộc môn Quản Trị Hệ Thống & Điện Toán Đám Mây. Đảm bảo tính sẵn sàng cao High Availability Nội dung trọng tâm gồm việc hiểu rõ bản chất của ALB, Target Group, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 7, 15, '["ALB", "Target Group", "Auto Scaling Group", "Health Check"]'::jsonb, 'NEEDS_REVIEW', 60, 'ses-top-dien-toan-dam-may-cloud-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dien-toan-dam-may-cloud-08', 'sub-it-cloud', 'Giám Sát Hạ Tầng Đám Mây Với CloudWatch & Prometheus', 'dien-toan-dam-may-cloud-8', 'Bài học ''Giám Sát Hạ Tầng Đám Mây Với CloudWatch & Prometheus'' thuộc môn Quản Trị Hệ Thống & Điện Toán Đám Mây. Quan sát toàn diện hệ thống Nội dung trọng tâm gồm việc hiểu rõ bản chất của Metrics, Log Stream, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 13, '["Metrics", "Log Stream", "Alarm Notification", "Dashboard"]'::jsonb, 'COMPLETED', 87, 'ses-top-dien-toan-dam-may-cloud-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dien-toan-dam-may-cloud-09', 'sub-it-cloud', 'Sao Lưu Phục Hồi Dữ Liệu & Disaster Recovery (DR)', 'dien-toan-dam-may-cloud-9', 'Bài học ''Sao Lưu Phục Hồi Dữ Liệu & Disaster Recovery (DR)'' thuộc môn Quản Trị Hệ Thống & Điện Toán Đám Mây. Bảo vệ dữ liệu trước thảm họa Nội dung trọng tâm gồm việc hiểu rõ bản chất của RPO, RTO, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 9, 12, '["RPO", "RTO", "Multi-region Replication", "Snapshot Backup"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dien-toan-dam-may-cloud-10', 'sub-it-cloud', 'Bảo Mật Đám Mây & Mô Hình Trách Nhiệm Chung', 'dien-toan-dam-may-cloud-10', 'Bài học ''Bảo Mật Đám Mây & Mô Hình Trách Nhiệm Chung'' thuộc môn Quản Trị Hệ Thống & Điện Toán Đám Mây. An toàn an ninh trên hạ tầng Cloud Nội dung trọng tâm gồm việc hiểu rõ bản chất của Shared Responsibility, KMS Encryption, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 10, 10, '["Shared Responsibility", "KMS Encryption", "Security Group", "WAF"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-dien-toan-dam-may-cloud-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dien-toan-dam-may-cloud-11', 'sub-it-cloud', 'Quản Trị Hệ Thống & Điện Toán Đám Mây - Chuyên Đề Nâng Cao #1', 'dien-toan-dam-may-cloud-11', 'Bài học ''Quản Trị Hệ Thống & Điện Toán Đám Mây - Chuyên Đề Nâng Cao #1'' thuộc môn Quản Trị Hệ Thống & Điện Toán Đám Mây. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Quản Trị Hệ Thống & Điện Toán Đám Mây. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 11, 8, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NEEDS_REVIEW', 53, 'ses-top-dien-toan-dam-may-cloud-11');
