INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-an-toan-thong-tin-cybersecurity-01', 'sub-it-security', 'Mô Hình Tam Giác Bảo Mật CIA: Confidentiality, Integrity, Availability', 'an-toan-thong-tin-cybersecurity-1', 'Bài học ''Mô Hình Tam Giác Bảo Mật CIA: Confidentiality, Integrity, Availability'' thuộc môn An Toàn Thông Tin & An Ninh Mạng. Nền tảng của an toàn thông tin Nội dung trọng tâm gồm việc hiểu rõ bản chất của Bảo mật, Toàn vẹn, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 1, 8, '["Bảo mật", "Toàn vẹn", "Sẵn sàng", "Kiểm soát truy cập"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-an-toan-thong-tin-cybersecurity-02', 'sub-it-security', 'Mật Mã Học Bất Đối Xứng: Thuật Toán RSA & Trao Đổi Khóa Diffie-Hellman', 'an-toan-thong-tin-cybersecurity-2', 'Bài học ''Mật Mã Học Bất Đối Xứng: Thuật Toán RSA & Trao Đổi Khóa Diffie-Hellman'' thuộc môn An Toàn Thông Tin & An Ninh Mạng. Mã hóa khóa công khai hiện đại Nội dung trọng tâm gồm việc hiểu rõ bản chất của Public Key, Private Key, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 2, 10, '["Public Key", "Private Key", "Chữ ký số", "Số nguyên tố lớn"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-an-toan-thong-tin-cybersecurity-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-an-toan-thong-tin-cybersecurity-03', 'sub-it-security', 'Mật Mã Đối Xứng Chuẩn AES & Hàm Băm An Toàn SHA-256', 'an-toan-thong-tin-cybersecurity-3', 'Bài học ''Mật Mã Đối Xứng Chuẩn AES & Hàm Băm An Toàn SHA-256'' thuộc môn An Toàn Thông Tin & An Ninh Mạng. Mã hóa dữ liệu khối tốc độ cao Nội dung trọng tâm gồm việc hiểu rõ bản chất của Block Cipher, Khóa 256-bit, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 3, 14, '["Block Cipher", "Khóa 256-bit", "Tính kháng va chạm Collision Resistance", "HMAC"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-an-toan-thong-tin-cybersecurity-04', 'sub-it-security', 'Tấn Công Tiêm Mã SQL (SQL Injection) & Biện Pháp Phòng Chống', 'an-toan-thong-tin-cybersecurity-4', 'Bài học ''Tấn Công Tiêm Mã SQL (SQL Injection) & Biện Pháp Phòng Chống'' thuộc môn An Toàn Thông Tin & An Ninh Mạng. Lỗ hổng ứng dụng web kinh điển Nội dung trọng tâm gồm việc hiểu rõ bản chất của Parameterized Query, Prepared Statement, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 4, 7, '["Parameterized Query", "Prepared Statement", "Blind SQLi", "OR 1=1 Attack"]'::jsonb, 'COMPLETED', 94, 'ses-top-an-toan-thong-tin-cybersecurity-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-an-toan-thong-tin-cybersecurity-05', 'sub-it-security', 'Lỗ Hổng Kịch Bản Chéo Trang (Cross-Site Scripting - XSS)', 'an-toan-thong-tin-cybersecurity-5', 'Bài học ''Lỗ Hổng Kịch Bản Chéo Trang (Cross-Site Scripting - XSS)'' thuộc môn An Toàn Thông Tin & An Ninh Mạng. Đánh cắp phiên người dùng trên trình duyệt Nội dung trọng tâm gồm việc hiểu rõ bản chất của Stored XSS, Reflected XSS, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 5, 10, '["Stored XSS", "Reflected XSS", "DOM-based XSS", "Content Security Policy CSP"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-an-toan-thong-tin-cybersecurity-06', 'sub-it-security', 'Tấn Công Giả Mạo Yêu Cầu (CSRF) & Cơ Chế SameSite Cookie', 'an-toan-thong-tin-cybersecurity-6', 'Bài học ''Tấn Công Giả Mạo Yêu Cầu (CSRF) & Cơ Chế SameSite Cookie'' thuộc môn An Toàn Thông Tin & An Ninh Mạng. Bảo vệ các tác vụ quan trọng Nội dung trọng tâm gồm việc hiểu rõ bản chất của CSRF Token, SameSite Cookie, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 6, 15, '["CSRF Token", "SameSite Cookie", "Referer Header", "Re-authentication"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-an-toan-thong-tin-cybersecurity-07', 'sub-it-security', 'Tấn Công Từ Chối Dịch Vụ Phân Tán (DDoS) & Giải Pháp Giảm Thiểu', 'an-toan-thong-tin-cybersecurity-7', 'Bài học ''Tấn Công Từ Chối Dịch Vụ Phân Tán (DDoS) & Giải Pháp Giảm Thiểu'' thuộc môn An Toàn Thông Tin & An Ninh Mạng. Bảo vệ tính sẵn sàng của hệ thống Nội dung trọng tâm gồm việc hiểu rõ bản chất của Botnet, SYN Flood, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 8, '["Botnet", "SYN Flood", "Amplification Attack", "Cloudflare WAF"]'::jsonb, 'COMPLETED', 87, 'ses-top-an-toan-thong-tin-cybersecurity-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-an-toan-thong-tin-cybersecurity-08', 'sub-it-security', 'Quản Lý Danh Tính & Kiểm Soát Quyền Truy Cập (IAM & OAuth2 / JWT)', 'an-toan-thong-tin-cybersecurity-8', 'Bài học ''Quản Lý Danh Tính & Kiểm Soát Quyền Truy Cập (IAM & OAuth2 / JWT)'' thuộc môn An Toàn Thông Tin & An Ninh Mạng. Ủy quyền an toàn cho người dùng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Authentication vs Authorization, Access Token, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 8, 15, '["Authentication vs Authorization", "Access Token", "Refresh Token", "RBAC"]'::jsonb, 'COMPLETED', 91, 'ses-top-an-toan-thong-tin-cybersecurity-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-an-toan-thong-tin-cybersecurity-09', 'sub-it-security', 'Kỹ Thuật Tấn Công Xã Hội (Social Engineering) & Lừa Đảo Phishing', 'an-toan-thong-tin-cybersecurity-9', 'Bài học ''Kỹ Thuật Tấn Công Xã Hội (Social Engineering) & Lừa Đảo Phishing'' thuộc môn An Toàn Thông Tin & An Ninh Mạng. Điểm yếu con người trong chuỗi an ninh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Phishing Email, Spear Phishing, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 9, 15, '["Phishing Email", "Spear Phishing", "Quản lý mật khẩu", "2FA / MFA"]'::jsonb, 'NEEDS_REVIEW', 62, 'ses-top-an-toan-thong-tin-cybersecurity-09');
