INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tri-tue-nhan-tao-machine-learning-02', 'sub-cs-ai-ml', 'Mô Hình Hồi Quy Tuyến Tính (Linear Regression)', 'tri-tue-nhan-tao-machine-learning-2', 'Bài học ''Mô Hình Hồi Quy Tuyến Tính (Linear Regression)'' thuộc môn Trí Tuệ Nhân Tạo & Học Máy. Dự đoán giá trị liên tục Nội dung trọng tâm gồm việc hiểu rõ bản chất của Hàm giả thuyết Hypothesis, Hàm mất mát MSE, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 7, '["Hàm giả thuyết Hypothesis", "Hàm mất mát MSE", "Hệ số góc và điểm cắt", "R-squared"]'::jsonb, 'NEEDS_REVIEW', 60, 'ses-top-tri-tue-nhan-tao-machine-learning-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tri-tue-nhan-tao-machine-learning-03', 'sub-cs-ai-ml', 'Thuật Toán Hạ Độ Dốc (Gradient Descent Optimization)', 'tri-tue-nhan-tao-machine-learning-3', 'Bài học ''Thuật Toán Hạ Độ Dốc (Gradient Descent Optimization)'' thuộc môn Trí Tuệ Nhân Tạo & Học Máy. Tìm cực tiểu hàm chi phí Nội dung trọng tâm gồm việc hiểu rõ bản chất của Learning Rate, Đạo hàm riêng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 3, 9, '["Learning Rate", "Đạo hàm riêng", "Stochastic GD", "Batch vs Mini-batch"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tri-tue-nhan-tao-machine-learning-04', 'sub-cs-ai-ml', 'Hồi Quy Logistic & Bài Toán Phân Lớp Nhị Phân', 'tri-tue-nhan-tao-machine-learning-4', 'Bài học ''Hồi Quy Logistic & Bài Toán Phân Lớp Nhị Phân'' thuộc môn Trí Tuệ Nhân Tạo & Học Máy. Dự đoán xác suất phân loại Nội dung trọng tâm gồm việc hiểu rõ bản chất của Hàm Sigmoid, Log Loss, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 4, 13, '["Hàm Sigmoid", "Log Loss", "Decision Boundary", "Odds Ratio"]'::jsonb, 'COMPLETED', 88, 'ses-top-tri-tue-nhan-tao-machine-learning-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tri-tue-nhan-tao-machine-learning-05', 'sub-cs-ai-ml', 'Đánh Giá Mô Hình Phân Lớp: Confusion Matrix & ROC-AUC', 'tri-tue-nhan-tao-machine-learning-5', 'Bài học ''Đánh Giá Mô Hình Phân Lớp: Confusion Matrix & ROC-AUC'' thuộc môn Trí Tuệ Nhân Tạo & Học Máy. Đo lường độ chính xác thực chất Nội dung trọng tâm gồm việc hiểu rõ bản chất của Accuracy, Precision, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 5, 12, '["Accuracy", "Precision", "Recall", "F1-Score", "Đường cong ROC"]'::jsonb, 'COMPLETED', 89, 'ses-top-tri-tue-nhan-tao-machine-learning-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tri-tue-nhan-tao-machine-learning-06', 'sub-cs-ai-ml', 'Cây Quyết Định (Decision Tree) & Thuật Toán Rừng Ngẫu Nhiên', 'tri-tue-nhan-tao-machine-learning-6', 'Bài học ''Cây Quyết Định (Decision Tree) & Thuật Toán Rừng Ngẫu Nhiên'' thuộc môn Trí Tuệ Nhân Tạo & Học Máy. Mô hình cây phân loại mạnh mẽ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Entropy, Information Gain, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 6, 13, '["Entropy", "Information Gain", "Ensemble Learning", "Bagging"]'::jsonb, 'COMPLETED', 97, 'ses-top-tri-tue-nhan-tao-machine-learning-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tri-tue-nhan-tao-machine-learning-07', 'sub-cs-ai-ml', 'Thuật Toán Phân Cụm K-Means (K-Means Clustering)', 'tri-tue-nhan-tao-machine-learning-7', 'Bài học ''Thuật Toán Phân Cụm K-Means (K-Means Clustering)'' thuộc môn Trí Tuệ Nhân Tạo & Học Máy. Khám phá cấu trúc ẩn trong dữ liệu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Centroid, Khoảng cách Euclidean, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 14, '["Centroid", "Khoảng cách Euclidean", "Elbow Method", "WSS"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tri-tue-nhan-tao-machine-learning-08', 'sub-cs-ai-ml', 'Giảm Chiều Dữ Liệu Bằng Phân Tích Thành Phần Chính (PCA)', 'tri-tue-nhan-tao-machine-learning-8', 'Bài học ''Giảm Chiều Dữ Liệu Bằng Phân Tích Thành Phần Chính (PCA)'' thuộc môn Trí Tuệ Nhân Tạo & Học Máy. Nén dữ liệu giữ lại tối đa phương sai Nội dung trọng tâm gồm việc hiểu rõ bản chất của Eigenvalues, Eigenvectors, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 7, '["Eigenvalues", "Eigenvectors", "Covariance Matrix", "Projection"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tri-tue-nhan-tao-machine-learning-09', 'sub-cs-ai-ml', 'Mạng Nơ-ron Nhân Tạo Căn Bản (Multilayer Perceptron)', 'tri-tue-nhan-tao-machine-learning-9', 'Bài học ''Mạng Nơ-ron Nhân Tạo Căn Bản (Multilayer Perceptron)'' thuộc môn Trí Tuệ Nhân Tạo & Học Máy. Mô phỏng tế bào thần kinh sinh học Nội dung trọng tâm gồm việc hiểu rõ bản chất của Perceptron, Hàm kích hoạt ReLU/Softmax, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 9, 7, '["Perceptron", "Hàm kích hoạt ReLU/Softmax", "Lan truyền tiến Feedforward", "Lan truyền ngược Backprop"]'::jsonb, 'COMPLETED', 85, 'ses-top-tri-tue-nhan-tao-machine-learning-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tri-tue-nhan-tao-machine-learning-10', 'sub-cs-ai-ml', 'Hiện Tượng Học Quá Tốt (Overfitting) & Kỹ Thuật Điều Chuẩn', 'tri-tue-nhan-tao-machine-learning-10', 'Bài học ''Hiện Tượng Học Quá Tốt (Overfitting) & Kỹ Thuật Điều Chuẩn'' thuộc môn Trí Tuệ Nhân Tạo & Học Máy. Giúp mô hình khái quát hóa tốt Nội dung trọng tâm gồm việc hiểu rõ bản chất của Overfitting vs Underfitting, L1 Lasso, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 10, '["Overfitting vs Underfitting", "L1 Lasso", "L2 Ridge", "Dropout", "Early Stopping"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tri-tue-nhan-tao-machine-learning-11', 'sub-cs-ai-ml', 'Trí Tuệ Nhân Tạo & Học Máy - Chuyên Đề Nâng Cao #1', 'tri-tue-nhan-tao-machine-learning-11', 'Bài học ''Trí Tuệ Nhân Tạo & Học Máy - Chuyên Đề Nâng Cao #1'' thuộc môn Trí Tuệ Nhân Tạo & Học Máy. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Trí Tuệ Nhân Tạo & Học Máy. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 11, 10, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
