INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ly-thuyet-tinh-toan-automata-01', 'sub-cs-automata', 'Ngôn Ngữ Hình Thức & Bảng Chữ Cái Toán Học', 'ly-thuyet-tinh-toan-automata-1', 'Bài học ''Ngôn Ngữ Hình Thức & Bảng Chữ Cái Toán Học'' thuộc môn Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức. Khái niệm nền tảng về tính toán Nội dung trọng tâm gồm việc hiểu rõ bản chất của Bảng chữ cái Alphabet, Chuỗi String, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 1, 13, '["Bảng chữ cái Alphabet", "Chuỗi String", "Ngôn ngữ Language", "Phép sao Kleene"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ly-thuyet-tinh-toan-automata-02', 'sub-cs-automata', 'Ôtômat Hữu Hạn Đơn Định (DFA)', 'ly-thuyet-tinh-toan-automata-2', 'Bài học ''Ôtômat Hữu Hạn Đơn Định (DFA)'' thuộc môn Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức. Mô hình nhận dạng ngôn ngữ chính quy Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tập trạng thái, Hàm chuyển trạng thái, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 2, 10, '["Tập trạng thái", "Hàm chuyển trạng thái", "Trạng thái bắt đầu", "Trạng thái chấp nhận"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ly-thuyet-tinh-toan-automata-03', 'sub-cs-automata', 'Ôtômat Hữu Hạn Không Đơn Định (NFA) & Chuyển Đổi DFA', 'ly-thuyet-tinh-toan-automata-3', 'Bài học ''Ôtômat Hữu Hạn Không Đơn Định (NFA) & Chuyển Đổi DFA'' thuộc môn Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức. Sức mạnh tương đương của NFA và DFA Nội dung trọng tâm gồm việc hiểu rõ bản chất của Chuyển trạng thái Epsilon, Phương pháp tập con Subset Construction, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 3, 8, '["Chuyển trạng thái Epsilon", "Phương pháp tập con Subset Construction", "Ngôn ngữ chính quy"]'::jsonb, 'NEEDS_REVIEW', 55, 'ses-top-ly-thuyet-tinh-toan-automata-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ly-thuyet-tinh-toan-automata-04', 'sub-cs-automata', 'Biểu Thức Chính Quy (Regex) & Định Lý Kleene', 'ly-thuyet-tinh-toan-automata-4', 'Bài học ''Biểu Thức Chính Quy (Regex) & Định Lý Kleene'' thuộc môn Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức. Đặc tả mẫu chuỗi hình thức Nội dung trọng tâm gồm việc hiểu rõ bản chất của Toán tử ghép nối, Toán tử tuyển, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 4, 8, '["Toán tử ghép nối", "Toán tử tuyển", "Định lý Kleene", "Ứng dụng Parser"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ly-thuyet-tinh-toan-automata-05', 'sub-cs-automata', 'Bổ Đề Bơm Cho Ngôn Ngữ Chính Quy (Pumping Lemma)', 'ly-thuyet-tinh-toan-automata-5', 'Bài học ''Bổ Đề Bơm Cho Ngôn Ngữ Chính Quy (Pumping Lemma)'' thuộc môn Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức. Chứng minh một ngôn ngữ không chính quy Nội dung trọng tâm gồm việc hiểu rõ bản chất của Độ dài bơm, Phép chia chuỗi xyz, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 5, 12, '["Độ dài bơm", "Phép chia chuỗi xyz", "Chứng minh bằng phản chứng"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ly-thuyet-tinh-toan-automata-06', 'sub-cs-automata', 'Ngữ Pháp Phi Ngữ Cảnh (CFG) & Cây Dẫn Xuất', 'ly-thuyet-tinh-toan-automata-6', 'Bài học ''Ngữ Pháp Phi Ngữ Cảnh (CFG) & Cây Dẫn Xuất'' thuộc môn Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức. Cấu trúc cú pháp ngôn ngữ lập trình Nội dung trọng tâm gồm việc hiểu rõ bản chất của Biến sinh, Ký hiệu kết thúc, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 6, 12, '["Biến sinh", "Ký hiệu kết thúc", "Quy tắc sinh", "Nhập nhằng cú pháp Ambiguity"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-ly-thuyet-tinh-toan-automata-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ly-thuyet-tinh-toan-automata-07', 'sub-cs-automata', 'Ôtômat Đẩy Xuống (Pushdown Automata - PDA)', 'ly-thuyet-tinh-toan-automata-7', 'Bài học ''Ôtômat Đẩy Xuống (Pushdown Automata - PDA)'' thuộc môn Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức. Ôtômat có bộ nhớ ngăn xếp Nội dung trọng tâm gồm việc hiểu rõ bản chất của Stack PDA, Nhận dạng ngôn ngữ phi ngữ cảnh, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 7, 7, '["Stack PDA", "Nhận dạng ngôn ngữ phi ngữ cảnh", "Deterministic PDA"]'::jsonb, 'NEEDS_REVIEW', 58, 'ses-top-ly-thuyet-tinh-toan-automata-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ly-thuyet-tinh-toan-automata-08', 'sub-cs-automata', 'Máy Turing (Turing Machine) & Giả Thuyết Church-Turing', 'ly-thuyet-tinh-toan-automata-8', 'Bài học ''Máy Turing (Turing Machine) & Giả Thuyết Church-Turing'' thuộc môn Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức. Mô hình máy tính vạn năng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Băng từ Tape, Đầu đọc ghi, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 8, 8, '["Băng từ Tape", "Đầu đọc ghi", "Trạng thái Halt", "Turing-complete"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ly-thuyet-tinh-toan-automata-09', 'sub-cs-automata', 'Bài Toán Dừng (Halting Problem) & Tính Không Thể Giải Quyết', 'ly-thuyet-tinh-toan-automata-9', 'Bài học ''Bài Toán Dừng (Halting Problem) & Tính Không Thể Giải Quyết'' thuộc môn Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức. Giới hạn tuyệt đối của máy tính Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tính khả quyết Decidability, Phương pháp đường chéo Cantor, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 9, 14, '["Tính khả quyết Decidability", "Phương pháp đường chéo Cantor", "Nghịch lý tự tham chiếu"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ly-thuyet-tinh-toan-automata-10', 'sub-cs-automata', 'Lý Thuyết Độ Phức Tạp: Phân Lớp P, NP và NP-Đầy Đủ', 'ly-thuyet-tinh-toan-automata-10', 'Bài học ''Lý Thuyết Độ Phức Tạp: Phân Lớp P, NP và NP-Đầy Đủ'' thuộc môn Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức. Bài toán mở lớn nhất của khoa học máy tính Nội dung trọng tâm gồm việc hiểu rõ bản chất của Lớp P thời gian đa thức, Lớp NP kiểm chứng đa thức, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 10, 15, '["Lớp P thời gian đa thức", "Lớp NP kiểm chứng đa thức", "Quy dẫn đa thức", "NP-Complete"]'::jsonb, 'COMPLETED', 86, 'ses-top-ly-thuyet-tinh-toan-automata-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ly-thuyet-tinh-toan-automata-11', 'sub-cs-automata', 'Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức - Chuyên Đề Nâng Cao #1', 'ly-thuyet-tinh-toan-automata-11', 'Bài học ''Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức - Chuyên Đề Nâng Cao #1'' thuộc môn Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Lý Thuyết Tính Toán & Ngôn Ngữ Hình Thức. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 11, 15, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'COMPLETED', 96, 'ses-top-ly-thuyet-tinh-toan-automata-11');
