INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-may-tinh-he-dieu-hanh-01', 'sub-cs-os', 'Kiến Trúc Von Neumann & Chu Kỳ Lệnh CPU', 'kien-truc-may-tinh-he-dieu-hanh-1', 'Bài học ''Kiến Trúc Von Neumann & Chu Kỳ Lệnh CPU'' thuộc môn Kiến Trúc Máy Tính & Hệ Điều Hành. Cách máy tính thực thi mã máy Nội dung trọng tâm gồm việc hiểu rõ bản chất của ALU, Thanh ghi Register, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 1, 13, '["ALU", "Thanh ghi Register", "Bộ đếm chương trình PC", "Fetch-Decode-Execute"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-may-tinh-he-dieu-hanh-02', 'sub-cs-os', 'Hệ Thống Phân Cấp Bộ Nhớ: Cache L1/L2/L3 & RAM', 'kien-truc-may-tinh-he-dieu-hanh-2', 'Bài học ''Hệ Thống Phân Cấp Bộ Nhớ: Cache L1/L2/L3 & RAM'' thuộc môn Kiến Trúc Máy Tính & Hệ Điều Hành. Tối ưu hóa độ trễ truy xuất Nội dung trọng tâm gồm việc hiểu rõ bản chất của Locality of Reference, Cache Hit/Miss, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 2, 12, '["Locality of Reference", "Cache Hit/Miss", "Cache Line", "Latency Numbers"]'::jsonb, 'COMPLETED', 97, 'ses-top-kien-truc-may-tinh-he-dieu-hanh-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-may-tinh-he-dieu-hanh-03', 'sub-cs-os', 'Quản Lý Tiến Trình (Process) & Khối Điều Khiển PCB', 'kien-truc-may-tinh-he-dieu-hanh-3', 'Bài học ''Quản Lý Tiến Trình (Process) & Khối Điều Khiển PCB'' thuộc môn Kiến Trúc Máy Tính & Hệ Điều Hành. Đơn vị tài nguyên của hệ điều hành Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tiến trình vs Luồng, Process Control Block, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 3, 11, '["Tiến trình vs Luồng", "Process Control Block", "Chuyển ngữ cảnh Context Switch"]'::jsonb, 'NEEDS_REVIEW', 59, 'ses-top-kien-truc-may-tinh-he-dieu-hanh-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-may-tinh-he-dieu-hanh-04', 'sub-cs-os', 'Các Giải Thuật Lập Lịch CPU (Scheduling)', 'kien-truc-may-tinh-he-dieu-hanh-4', 'Bài học ''Các Giải Thuật Lập Lịch CPU (Scheduling)'' thuộc môn Kiến Trúc Máy Tính & Hệ Điều Hành. Tối đa hóa hiệu năng xử lý của CPU Nội dung trọng tâm gồm việc hiểu rõ bản chất của First-Come First-Served, Shortest Job First, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 4, 11, '["First-Come First-Served", "Shortest Job First", "Round Robin", "Priority Scheduling"]'::jsonb, 'COMPLETED', 93, 'ses-top-kien-truc-may-tinh-he-dieu-hanh-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-may-tinh-he-dieu-hanh-05', 'sub-cs-os', 'Cơ Chế Đồng Bộ Hóa: Mutex, Semaphore & Điều Kiện Tranh Chấp', 'kien-truc-may-tinh-he-dieu-hanh-5', 'Bài học ''Cơ Chế Đồng Bộ Hóa: Mutex, Semaphore & Điều Kiện Tranh Chấp'' thuộc môn Kiến Trúc Máy Tính & Hệ Điều Hành. Bảo vệ tài nguyên dùng chung Nội dung trọng tâm gồm việc hiểu rõ bản chất của Race Condition, Critical Section, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 5, 8, '["Race Condition", "Critical Section", "Semaphore", "Spinlock"]'::jsonb, 'COMPLETED', 87, 'ses-top-kien-truc-may-tinh-he-dieu-hanh-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-may-tinh-he-dieu-hanh-06', 'sub-cs-os', 'Bế Tắc Tài Nguyên (Deadlock) & 4 Điều Kiện Coffman', 'kien-truc-may-tinh-he-dieu-hanh-6', 'Bài học ''Bế Tắc Tài Nguyên (Deadlock) & 4 Điều Kiện Coffman'' thuộc môn Kiến Trúc Máy Tính & Hệ Điều Hành. Ngăn chặn kẹt cứng hệ thống Nội dung trọng tâm gồm việc hiểu rõ bản chất của Mutual Exclusion, Hold and Wait, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 6, 14, '["Mutual Exclusion", "Hold and Wait", "No Preemption", "Circular Wait", "Banker''s Algorithm"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-may-tinh-he-dieu-hanh-07', 'sub-cs-os', 'Bộ Nhớ Ảo & Cơ Chế Phân Trang (Virtual Memory & Paging)', 'kien-truc-may-tinh-he-dieu-hanh-7', 'Bài học ''Bộ Nhớ Ảo & Cơ Chế Phân Trang (Virtual Memory & Paging)'' thuộc môn Kiến Trúc Máy Tính & Hệ Điều Hành. Mở rộng không gian địa chỉ cho tiến trình Nội dung trọng tâm gồm việc hiểu rõ bản chất của Bảng trang Page Table, Bộ nhớ chuyển đổi TLB, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 7, 14, '["Bảng trang Page Table", "Bộ nhớ chuyển đổi TLB", "Lỗi trang Page Fault"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-may-tinh-he-dieu-hanh-08', 'sub-cs-os', 'Các Thuật Toán Thay Thế Trang Bộ Nhớ (Page Replacement)', 'kien-truc-may-tinh-he-dieu-hanh-8', 'Bài học ''Các Thuật Toán Thay Thế Trang Bộ Nhớ (Page Replacement)'' thuộc môn Kiến Trúc Máy Tính & Hệ Điều Hành. Tối ưu hóa bộ nhớ RAM hữu hạn Nội dung trọng tâm gồm việc hiểu rõ bản chất của FIFO, Optimal, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 8, 14, '["FIFO", "Optimal", "Least Recently Used LRU", "Clock Algorithm"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-may-tinh-he-dieu-hanh-09', 'sub-cs-os', 'Hệ Thống Tệp Tin (File System) & Cấu Trúc Inode', 'kien-truc-may-tinh-he-dieu-hanh-9', 'Bài học ''Hệ Thống Tệp Tin (File System) & Cấu Trúc Inode'' thuộc môn Kiến Trúc Máy Tính & Hệ Điều Hành. Lưu trữ dữ liệu bền vững trên đĩa Nội dung trọng tâm gồm việc hiểu rõ bản chất của Inode, Superblock, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 9, 13, '["Inode", "Superblock", "Directory Entry", "Journaling File System"]'::jsonb, 'COMPLETED', 87, 'ses-top-kien-truc-may-tinh-he-dieu-hanh-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-may-tinh-he-dieu-hanh-10', 'sub-cs-os', 'Cơ Chế Ngắt Phần Cứng & Xử Lý Ngoại Lệ (Interrupt & Trap)', 'kien-truc-may-tinh-he-dieu-hanh-10', 'Bài học ''Cơ Chế Ngắt Phần Cứng & Xử Lý Ngoại Lệ (Interrupt & Trap)'' thuộc môn Kiến Trúc Máy Tính & Hệ Điều Hành. Giao tiếp giữa phần cứng và phần mềm Nội dung trọng tâm gồm việc hiểu rõ bản chất của Interrupt Vector, ISR, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 10, 12, '["Interrupt Vector", "ISR", "System Call", "User Mode vs Kernel Mode"]'::jsonb, 'COMPLETED', 94, 'ses-top-kien-truc-may-tinh-he-dieu-hanh-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-may-tinh-he-dieu-hanh-11', 'sub-cs-os', 'Kiến Trúc Máy Tính & Hệ Điều Hành - Chuyên Đề Nâng Cao #1', 'kien-truc-may-tinh-he-dieu-hanh-11', 'Bài học ''Kiến Trúc Máy Tính & Hệ Điều Hành - Chuyên Đề Nâng Cao #1'' thuộc môn Kiến Trúc Máy Tính & Hệ Điều Hành. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Kiến Trúc Máy Tính & Hệ Điều Hành. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 11, 13, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NEEDS_REVIEW', 59, 'ses-top-kien-truc-may-tinh-he-dieu-hanh-11');
