INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-may-tinh-he-dieu-hanh-13', 'sub-cs-os', 'Kiến Trúc Máy Tính & Hệ Điều Hành - Chuyên Đề Nâng Cao #3', 'kien-truc-may-tinh-he-dieu-hanh-13', 'Bài học ''Kiến Trúc Máy Tính & Hệ Điều Hành - Chuyên Đề Nâng Cao #3'' thuộc môn Kiến Trúc Máy Tính & Hệ Điều Hành. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Kiến Trúc Máy Tính & Hệ Điều Hành. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #3A, Kỹ thuật tối ưu #3B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 13, 8, '["Khái niệm nâng cao #3A", "Kỹ thuật tối ưu #3B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'COMPLETED', 87, 'ses-top-kien-truc-may-tinh-he-dieu-hanh-13');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-thu-chat-luong-phan-mem-01', 'sub-se-testing', 'Quy Trình Kiểm Thử Phần Mềm V-Model & Mô Hình Kim Tự Tháp', 'kiem-thu-chat-luong-phan-mem-1', 'Bài học ''Quy Trình Kiểm Thử Phần Mềm V-Model & Mô Hình Kim Tự Tháp'' thuộc môn Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng. Tổng quan về chiến lược kiểm thử Nội dung trọng tâm gồm việc hiểu rõ bản chất của Unit Test, Integration Test, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 1, 15, '["Unit Test", "Integration Test", "E2E Test", "V-Model"]'::jsonb, 'COMPLETED', 95, 'ses-top-kiem-thu-chat-luong-phan-mem-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-thu-chat-luong-phan-mem-02', 'sub-se-testing', 'Kỹ Thuật Kiểm Thử Hộp Đen (Black-box Testing)', 'kiem-thu-chat-luong-phan-mem-2', 'Bài học ''Kỹ Thuật Kiểm Thử Hộp Đen (Black-box Testing)'' thuộc môn Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng. Kiểm thử dựa trên yêu cầu chức năng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Phân vùng tương đương, Phân tích giá trị biên BVA, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 14, '["Phân vùng tương đương", "Phân tích giá trị biên BVA", "Bảng quyết định", "Chuyển trạng thái"]'::jsonb, 'COMPLETED', 87, 'ses-top-kiem-thu-chat-luong-phan-mem-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-thu-chat-luong-phan-mem-03', 'sub-se-testing', 'Kỹ Thuật Kiểm Thử Hộp Trắng (White-box Testing)', 'kiem-thu-chat-luong-phan-mem-3', 'Bài học ''Kỹ Thuật Kiểm Thử Hộp Trắng (White-box Testing)'' thuộc môn Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng. Kiểm thử cấu trúc mã nguồn bên trong Nội dung trọng tâm gồm việc hiểu rõ bản chất của Độ bao phủ câu lệnh Statement Coverage, Độ bao phủ nhánh Branch Coverage, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 15, '["Độ bao phủ câu lệnh Statement Coverage", "Độ bao phủ nhánh Branch Coverage", "Cyclomatic Complexity"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-thu-chat-luong-phan-mem-04', 'sub-se-testing', 'Kiểm Thử Đơn Vị (Unit Testing) Với Thư Viện Mock & Stub', 'kiem-thu-chat-luong-phan-mem-4', 'Bài học ''Kiểm Thử Đơn Vị (Unit Testing) Với Thư Viện Mock & Stub'' thuộc môn Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng. Đảm bảo chất lượng từng hàm chức năng Nội dung trọng tâm gồm việc hiểu rõ bản chất của AAA Pattern (Arrange-Act-Assert), Test Runner, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 4, 10, '["AAA Pattern (Arrange-Act-Assert)", "Test Runner", "Mock Object", "Stub"]'::jsonb, 'COMPLETED', 85, 'ses-top-kiem-thu-chat-luong-phan-mem-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-thu-chat-luong-phan-mem-05', 'sub-se-testing', 'Phát Triển Hướng Kiểm Thử (Test-Driven Development - TDD)', 'kiem-thu-chat-luong-phan-mem-5', 'Bài học ''Phát Triển Hướng Kiểm Thử (Test-Driven Development - TDD)'' thuộc môn Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng. Viết test trước khi viết mã nguồn Nội dung trọng tâm gồm việc hiểu rõ bản chất của Red-Green-Refactor, Thiết kế mô-đun hóa, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 5, 11, '["Red-Green-Refactor", "Thiết kế mô-đun hóa", "Tự tin tái cấu trúc"]'::jsonb, 'COMPLETED', 86, 'ses-top-kiem-thu-chat-luong-phan-mem-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-thu-chat-luong-phan-mem-06', 'sub-se-testing', 'Kiểm Thử Tích Hợp (Integration Testing) & API Testing', 'kiem-thu-chat-luong-phan-mem-6', 'Bài học ''Kiểm Thử Tích Hợp (Integration Testing) & API Testing'' thuộc môn Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng. Kiểm tra sự ăn khớp giữa các hệ thống Nội dung trọng tâm gồm việc hiểu rõ bản chất của Top-down vs Bottom-up, Contract Testing, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 6, 9, '["Top-down vs Bottom-up", "Contract Testing", "Postman / Newman", "Stubbing Network"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-thu-chat-luong-phan-mem-07', 'sub-se-testing', 'Kiểm Thử Hồi Quy (Regression Testing) & Chiến Lược Chọn Test Case', 'kiem-thu-chat-luong-phan-mem-7', 'Bài học ''Kiểm Thử Hồi Quy (Regression Testing) & Chiến Lược Chọn Test Case'' thuộc môn Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng. Bảo vệ hệ thống không bị lỗi cũ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Smoke Test, Sanity Test, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 15, '["Smoke Test", "Sanity Test", "Automated Regression Suite"]'::jsonb, 'COMPLETED', 84, 'ses-top-kiem-thu-chat-luong-phan-mem-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-thu-chat-luong-phan-mem-08', 'sub-se-testing', 'Kiểm Thử Tự Động Giao Diện E2E Với Playwright / Cypress', 'kiem-thu-chat-luong-phan-mem-8', 'Bài học ''Kiểm Thử Tự Động Giao Diện E2E Với Playwright / Cypress'' thuộc môn Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng. Mô phỏng trải nghiệm người dùng thực Nội dung trọng tâm gồm việc hiểu rõ bản chất của DOM Selector, Headless Browser, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 8, 9, '["DOM Selector", "Headless Browser", "Asynchronous Waiting", "Visual Regression"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-thu-chat-luong-phan-mem-09', 'sub-se-testing', 'Kiểm Thử Hiệu Năng (Performance & Load Testing)', 'kiem-thu-chat-luong-phan-mem-9', 'Bài học ''Kiểm Thử Hiệu Năng (Performance & Load Testing)'' thuộc môn Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng. Đo lường độ chịu tải của hệ thống Nội dung trọng tâm gồm việc hiểu rõ bản chất của Throughput, Response Time, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 9, 14, '["Throughput", "Response Time", "JMeter / k6", "Stress Testing"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-thu-chat-luong-phan-mem-10', 'sub-se-testing', 'Quy Trình Quản Lý Lỗi (Defect Life Cycle) & Báo Cáo Chất Lượng', 'kiem-thu-chat-luong-phan-mem-10', 'Bài học ''Quy Trình Quản Lý Lỗi (Defect Life Cycle) & Báo Cáo Chất Lượng'' thuộc môn Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng. Theo dõi và đóng lỗi chuyên nghiệp Nội dung trọng tâm gồm việc hiểu rõ bản chất của Mức độ nghiêm trọng Severity, Mức độ ưu tiên Priority, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 11, '["Mức độ nghiêm trọng Severity", "Mức độ ưu tiên Priority", "Jira Bug Workflow"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-thu-chat-luong-phan-mem-11', 'sub-se-testing', 'Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng - Chuyên Đề Nâng Cao #1', 'kiem-thu-chat-luong-phan-mem-11', 'Bài học ''Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng - Chuyên Đề Nâng Cao #1'' thuộc môn Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Kiểm Thử Phần Mềm & Đảm Bảo Chất Lượng. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 11, 9, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NEEDS_REVIEW', 58, 'ses-top-kiem-thu-chat-luong-phan-mem-11');
