INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-mau-thiet-ke-software-01', 'sub-se-patterns', 'Nguyên Lý Thiết Kế Hướng Đối Tượng SOLID', 'kien-truc-mau-thiet-ke-software-1', 'Bài học ''Nguyên Lý Thiết Kế Hướng Đối Tượng SOLID'' thuộc môn Kiến Trúc Phần Mềm & Mẫu Thiết Kế (Design Patterns). Bộ 5 nguyên tắc vàng của lập trình viên Nội dung trọng tâm gồm việc hiểu rõ bản chất của Single Responsibility, Open-Closed, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 1, 13, '["Single Responsibility", "Open-Closed", "Liskov Substitution", "Interface Segregation", "Dependency Inversion"]'::jsonb, 'COMPLETED', 96, 'ses-top-kien-truc-mau-thiet-ke-software-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-mau-thiet-ke-software-02', 'sub-se-patterns', 'Nhóm Mẫu Khởi Tạo: Singleton & Factory Method', 'kien-truc-mau-thiet-ke-software-2', 'Bài học ''Nhóm Mẫu Khởi Tạo: Singleton & Factory Method'' thuộc môn Kiến Trúc Phần Mềm & Mẫu Thiết Kế (Design Patterns). Kiểm soát quá trình tạo lập đối tượng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thread-safe Singleton, Factory Method, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 15, '["Thread-safe Singleton", "Factory Method", "Encapsulation of Object Creation"]'::jsonb, 'NEEDS_REVIEW', 55, 'ses-top-kien-truc-mau-thiet-ke-software-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-mau-thiet-ke-software-03', 'sub-se-patterns', 'Nhóm Mẫu Khởi Tạo: Builder & Abstract Factory', 'kien-truc-mau-thiet-ke-software-3', 'Bài học ''Nhóm Mẫu Khởi Tạo: Builder & Abstract Factory'' thuộc môn Kiến Trúc Phần Mềm & Mẫu Thiết Kế (Design Patterns). Xây dựng các đối tượng phức tạp Nội dung trọng tâm gồm việc hiểu rõ bản chất của Builder Pattern, Fluent Interface, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 14, '["Builder Pattern", "Fluent Interface", "Abstract Factory Family"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-kien-truc-mau-thiet-ke-software-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-mau-thiet-ke-software-04', 'sub-se-patterns', 'Nhóm Mẫu Cấu Trúc: Adapter & Decorator', 'kien-truc-mau-thiet-ke-software-4', 'Bài học ''Nhóm Mẫu Cấu Trúc: Adapter & Decorator'' thuộc môn Kiến Trúc Phần Mềm & Mẫu Thiết Kế (Design Patterns). Liên kết các giao diện không tương thích Nội dung trọng tâm gồm việc hiểu rõ bản chất của Adapter Wrapper, Decorator Pattern, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 4, 13, '["Adapter Wrapper", "Decorator Pattern", "Kế thừa vs Bao đóng Composition"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-mau-thiet-ke-software-05', 'sub-se-patterns', 'Nhóm Mẫu Cấu Trúc: Facade & Proxy', 'kien-truc-mau-thiet-ke-software-5', 'Bài học ''Nhóm Mẫu Cấu Trúc: Facade & Proxy'' thuộc môn Kiến Trúc Phần Mềm & Mẫu Thiết Kế (Design Patterns). Đơn giản hóa giao diện và kiểm soát truy cập Nội dung trọng tâm gồm việc hiểu rõ bản chất của Facade Interface, Virtual Proxy, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 5, 8, '["Facade Interface", "Virtual Proxy", "Protection Proxy", "Caching Proxy"]'::jsonb, 'NEEDS_REVIEW', 49, 'ses-top-kien-truc-mau-thiet-ke-software-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-mau-thiet-ke-software-06', 'sub-se-patterns', 'Nhóm Mẫu Hành Vi: Observer & Publish-Subscribe', 'kien-truc-mau-thiet-ke-software-6', 'Bài học ''Nhóm Mẫu Hành Vi: Observer & Publish-Subscribe'' thuộc môn Kiến Trúc Phần Mềm & Mẫu Thiết Kế (Design Patterns). Phản ứng tự động khi trạng thái thay đổi Nội dung trọng tâm gồm việc hiểu rõ bản chất của Subject-Observer, Event-driven, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 6, 11, '["Subject-Observer", "Event-driven", "Decoupling", "Pub-Sub Broker"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-mau-thiet-ke-software-07', 'sub-se-patterns', 'Nhóm Mẫu Hành Vi: Strategy & State', 'kien-truc-mau-thiet-ke-software-7', 'Bài học ''Nhóm Mẫu Hành Vi: Strategy & State'' thuộc môn Kiến Trúc Phần Mềm & Mẫu Thiết Kế (Design Patterns). Thay đổi thuật toán và hành vi linh hoạt Nội dung trọng tâm gồm việc hiểu rõ bản chất của Strategy Pattern, State Pattern, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 7, 9, '["Strategy Pattern", "State Pattern", "Loại bỏ khối If-Else lồng nhau"]'::jsonb, 'COMPLETED', 87, 'ses-top-kien-truc-mau-thiet-ke-software-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-mau-thiet-ke-software-08', 'sub-se-patterns', 'Kiến Trúc Phân Lớp (Layered / N-Tier Architecture)', 'kien-truc-mau-thiet-ke-software-8', 'Bài học ''Kiến Trúc Phân Lớp (Layered / N-Tier Architecture)'' thuộc môn Kiến Trúc Phần Mềm & Mẫu Thiết Kế (Design Patterns). Tổ chức mã nguồn theo trách nhiệm Nội dung trọng tâm gồm việc hiểu rõ bản chất của Presentation Layer, Business Logic Layer, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 8, 13, '["Presentation Layer", "Business Logic Layer", "Data Access Layer"]'::jsonb, 'COMPLETED', 84, 'ses-top-kien-truc-mau-thiet-ke-software-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-mau-thiet-ke-software-09', 'sub-se-patterns', 'Kiến Trúc Sạch (Clean Architecture & Hexagonal)', 'kien-truc-mau-thiet-ke-software-9', 'Bài học ''Kiến Trúc Sạch (Clean Architecture & Hexagonal)'' thuộc môn Kiến Trúc Phần Mềm & Mẫu Thiết Kế (Design Patterns). Độc lập với framework và cơ sở dữ liệu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Entities Core, Use Cases, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 9, 14, '["Entities Core", "Use Cases", "Interface Adapters", "Dependency Rule"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kien-truc-mau-thiet-ke-software-10', 'sub-se-patterns', 'Kiến Trúc Vi Dịch Vụ (Microservices Architecture)', 'kien-truc-mau-thiet-ke-software-10', 'Bài học ''Kiến Trúc Vi Dịch Vụ (Microservices Architecture)'' thuộc môn Kiến Trúc Phần Mềm & Mẫu Thiết Kế (Design Patterns). Chia nhỏ hệ thống thành các dịch vụ độc lập Nội dung trọng tâm gồm việc hiểu rõ bản chất của API Gateway, Service Registry, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 10, 11, '["API Gateway", "Service Registry", "Event Bus", "Database per Service"]'::jsonb, 'COMPLETED', 88, 'ses-top-kien-truc-mau-thiet-ke-software-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-agile-devops-quy-trinh-phan-mem-01', 'sub-se-devops', 'Tuyên Ngôn Agile & So Sánh Mô Hình Thác Nước (Waterfall)', 'agile-devops-quy-trinh-phan-mem-1', 'Bài học ''Tuyên Ngôn Agile & So Sánh Mô Hình Thác Nước (Waterfall)'' thuộc môn Quy Trình Phát Triển Agile & Văn Hóa DevOps. Sự dịch chuyển phương pháp luận phát triển Nội dung trọng tâm gồm việc hiểu rõ bản chất của 4 giá trị cốt lõi, 12 nguyên tắc Agile, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 1, 11, '["4 giá trị cốt lõi", "12 nguyên tắc Agile", "Thích ứng thay đổi"]'::jsonb, 'COMPLETED', 87, 'ses-top-agile-devops-quy-trinh-phan-mem-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-agile-devops-quy-trinh-phan-mem-02', 'sub-se-devops', 'Khung Làm Việc Scrum: Vai Trò, Sự Kiện & Tạo Tác', 'agile-devops-quy-trinh-phan-mem-2', 'Bài học ''Khung Làm Việc Scrum: Vai Trò, Sự Kiện & Tạo Tác'' thuộc môn Quy Trình Phát Triển Agile & Văn Hóa DevOps. Vận hành nhóm phát triển linh hoạt Nội dung trọng tâm gồm việc hiểu rõ bản chất của Product Owner, Scrum Master, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 13, '["Product Owner", "Scrum Master", "Sprint Planning", "Daily Scrum", "Sprint Retrospective"]'::jsonb, 'NEEDS_REVIEW', 54, 'ses-top-agile-devops-quy-trinh-phan-mem-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-agile-devops-quy-trinh-phan-mem-03', 'sub-se-devops', 'Phương Pháp Kanban & Tối Ưu Hóa Dòng Chảy Công Việc', 'agile-devops-quy-trinh-phan-mem-3', 'Bài học ''Phương Pháp Kanban & Tối Ưu Hóa Dòng Chảy Công Việc'' thuộc môn Quy Trình Phát Triển Agile & Văn Hóa DevOps. Trực quan hóa và giới hạn công việc đang làm Nội dung trọng tâm gồm việc hiểu rõ bản chất của Kanban Board, Work in Progress (WIP) Limit, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 3, 11, '["Kanban Board", "Work in Progress (WIP) Limit", "Lead Time", "Cycle Time"]'::jsonb, 'NEEDS_REVIEW', 52, 'ses-top-agile-devops-quy-trinh-phan-mem-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-agile-devops-quy-trinh-phan-mem-04', 'sub-se-devops', 'Quản Lý Phiên Bản Mã Nguồn Với Git & Chiến Lược Nhánh (Gitflow)', 'agile-devops-quy-trinh-phan-mem-4', 'Bài học ''Quản Lý Phiên Bản Mã Nguồn Với Git & Chiến Lược Nhánh (Gitflow)'' thuộc môn Quy Trình Phát Triển Agile & Văn Hóa DevOps. Làm việc cộng tác an toàn trên source code Nội dung trọng tâm gồm việc hiểu rõ bản chất của Commit Atomic, Merge vs Rebase, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 4, 11, '["Commit Atomic", "Merge vs Rebase", "Pull Request", "Gitflow vs Trunk-based"]'::jsonb, 'COMPLETED', 86, 'ses-top-agile-devops-quy-trinh-phan-mem-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-agile-devops-quy-trinh-phan-mem-05', 'sub-se-devops', 'Tích Hợp Liên Tục (Continuous Integration - CI)', 'agile-devops-quy-trinh-phan-mem-5', 'Bài học ''Tích Hợp Liên Tục (Continuous Integration - CI)'' thuộc môn Quy Trình Phát Triển Agile & Văn Hóa DevOps. Tự động hóa build và chạy test Nội dung trọng tâm gồm việc hiểu rõ bản chất của GitHub Actions Workflow, Linting Code, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 5, 11, '["GitHub Actions Workflow", "Linting Code", "Automated Testing", "Build Artifact"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-agile-devops-quy-trinh-phan-mem-06', 'sub-se-devops', 'Phát Hành Liên Tục (Continuous Delivery / Deployment - CD)', 'agile-devops-quy-trinh-phan-mem-6', 'Bài học ''Phát Hành Liên Tục (Continuous Delivery / Deployment - CD)'' thuộc môn Quy Trình Phát Triển Agile & Văn Hóa DevOps. Đưa phần mềm tới tay người dùng tự động Nội dung trọng tâm gồm việc hiểu rõ bản chất của Deployment Pipeline, Staging Environment, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 6, 11, '["Deployment Pipeline", "Staging Environment", "Production Release"]'::jsonb, 'COMPLETED', 95, 'ses-top-agile-devops-quy-trinh-phan-mem-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-agile-devops-quy-trinh-phan-mem-07', 'sub-se-devops', 'Chiến Lược Triển Khai Không Gián Đoạn (Blue-Green & Canary)', 'agile-devops-quy-trinh-phan-mem-7', 'Bài học ''Chiến Lược Triển Khai Không Gián Đoạn (Blue-Green & Canary)'' thuộc môn Quy Trình Phát Triển Agile & Văn Hóa DevOps. Giảm thiểu rủi ro khi cập nhật ứng dụng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Zero-downtime, Blue-Green Switching, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 7, 11, '["Zero-downtime", "Blue-Green Switching", "Canary Deployment", "Rollback Plan"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-agile-devops-quy-trinh-phan-mem-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-agile-devops-quy-trinh-phan-mem-08', 'sub-se-devops', 'Hạ Tầng Dưới Dạng Mã Nguồn (IaC) & Quản Lý Cấu Hình', 'agile-devops-quy-trinh-phan-mem-8', 'Bài học ''Hạ Tầng Dưới Dạng Mã Nguồn (IaC) & Quản Lý Cấu Hình'' thuộc môn Quy Trình Phát Triển Agile & Văn Hóa DevOps. Kiểm soát môi trường máy chủ nhất quán Nội dung trọng tâm gồm việc hiểu rõ bản chất của Declarative Infrastructure, Ansible, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 8, 8, '["Declarative Infrastructure", "Ansible", "Idempotence"]'::jsonb, 'NEEDS_REVIEW', 62, 'ses-top-agile-devops-quy-trinh-phan-mem-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-agile-devops-quy-trinh-phan-mem-09', 'sub-se-devops', 'Quan Sát Hệ Thống (Observability): Logging, Metrics, Tracing', 'agile-devops-quy-trinh-phan-mem-9', 'Bài học ''Quan Sát Hệ Thống (Observability): Logging, Metrics, Tracing'' thuộc môn Quy Trình Phát Triển Agile & Văn Hóa DevOps. Hiểu rõ trạng thái bên trong của phần mềm Nội dung trọng tâm gồm việc hiểu rõ bản chất của Structured Logging, Prometheus Metrics, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 9, 12, '["Structured Logging", "Prometheus Metrics", "Distributed Tracing Jaeger"]'::jsonb, 'COMPLETED', 90, 'ses-top-agile-devops-quy-trinh-phan-mem-09');
