INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thanh-toan-dien-tu-fintech-02', 'sub-ecom-payments', 'Kiến Trúc Cổng Thanh Toán & Giao Thức Tích Hợp API', 'thanh-toan-dien-tu-fintech-2', 'Bài học ''Kiến Trúc Cổng Thanh Toán & Giao Thức Tích Hợp API'' thuộc môn Hệ Thống Thanh Toán Điện Tử & FinTech. Kết nối website với tổ chức tài chính Nội dung trọng tâm gồm việc hiểu rõ bản chất của Payment Gateway, Merchant Account, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 12, '["Payment Gateway", "Merchant Account", "Webhook Callback", "Idempotency Key"]'::jsonb, 'COMPLETED', 86, 'ses-top-thanh-toan-dien-tu-fintech-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thanh-toan-dien-tu-fintech-03', 'sub-ecom-payments', 'Quy Trình Xử Lý Giao Dịch Thẻ Tín Dụng / Ghi Nợ (Visa/Mastercard)', 'thanh-toan-dien-tu-fintech-3', 'Bài học ''Quy Trình Xử Lý Giao Dịch Thẻ Tín Dụng / Ghi Nợ (Visa/Mastercard)'' thuộc môn Hệ Thống Thanh Toán Điện Tử & FinTech. Hành trình của một khoản thanh toán thẻ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Acquiring Bank, Issuing Bank, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 11, '["Acquiring Bank", "Issuing Bank", "Payment Processor", "Quy trình Authorization & Capture"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thanh-toan-dien-tu-fintech-04', 'sub-ecom-payments', 'Công Nghệ Mã Hóa Số Thẻ (Tokenization) & Bảo Mật PCI-DSS', 'thanh-toan-dien-tu-fintech-4', 'Bài học ''Công Nghệ Mã Hóa Số Thẻ (Tokenization) & Bảo Mật PCI-DSS'' thuộc môn Hệ Thống Thanh Toán Điện Tử & FinTech. Bảo vệ thông tin tài chính người dùng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Network Tokenization, Chuẩn bảo mật PCI-DSS, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 4, 15, '["Network Tokenization", "Chuẩn bảo mật PCI-DSS", "Point-to-Point Encryption"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thanh-toan-dien-tu-fintech-05', 'sub-ecom-payments', 'Công Nghệ Thanh Toán QR Code (VietQR / EMVCo)', 'thanh-toan-dien-tu-fintech-5', 'Bài học ''Công Nghệ Thanh Toán QR Code (VietQR / EMVCo)'' thuộc môn Hệ Thống Thanh Toán Điện Tử & FinTech. Chuẩn hóa thanh toán mã phản hồi nhanh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tĩnh vs Động QR, Cấu trúc dữ liệu EMVCo, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 5, 12, '["Tĩnh vs Động QR", "Cấu trúc dữ liệu EMVCo", "NAPAS 24/7 API"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-thanh-toan-dien-tu-fintech-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thanh-toan-dien-tu-fintech-06', 'sub-ecom-payments', 'Mô Hình Hoạt Động Của Ví Điện Tử (E-Wallet)', 'thanh-toan-dien-tu-fintech-6', 'Bài học ''Mô Hình Hoạt Động Của Ví Điện Tử (E-Wallet)'' thuộc môn Hệ Thống Thanh Toán Điện Tử & FinTech. Lưu trữ giá trị tiền tệ trên thiết bị Nội dung trọng tâm gồm việc hiểu rõ bản chất của Liên kết tài khoản ngân hàng, Ví trung gian, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 6, 13, '["Liên kết tài khoản ngân hàng", "Ví trung gian", "Chuyển tiền P2P", "Thanh toán P2M"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-thanh-toan-dien-tu-fintech-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thanh-toan-dien-tu-fintech-07', 'sub-ecom-payments', 'Quản Trị Rủi Ro Gian Lận Giao Dịch (Fraud Detection)', 'thanh-toan-dien-tu-fintech-7', 'Bài học ''Quản Trị Rủi Ro Gian Lận Giao Dịch (Fraud Detection)'' thuộc môn Hệ Thống Thanh Toán Điện Tử & FinTech. Ngăn chặn gian lận thẻ và rửa tiền Nội dung trọng tâm gồm việc hiểu rõ bản chất của Chargeback, Quy tắc phát hiện bất thường, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 7, 7, '["Chargeback", "Quy tắc phát hiện bất thường", "Machine Learning Fraud Scoring", "3D-Secure 2.0"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thanh-toan-dien-tu-fintech-08', 'sub-ecom-payments', 'Mô Hình Mua Trước Trả Sau (Buy Now Pay Later - BNPL)', 'thanh-toan-dien-tu-fintech-8', 'Bài học ''Mô Hình Mua Trước Trả Sau (Buy Now Pay Later - BNPL)'' thuộc môn Hệ Thống Thanh Toán Điện Tử & FinTech. Đổi mới tài chính thúc đẩy tiêu dùng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Quy trình phê duyệt tức thì, Kỳ hạn trả góp, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 8, 14, '["Quy trình phê duyệt tức thì", "Kỳ hạn trả góp", "Lợi ích cho người bán và người mua", "Quản lý nợ xấu"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thanh-toan-dien-tu-fintech-09', 'sub-ecom-payments', 'Công Nghệ Blockchain & Tiền Điện Tử Trong Thương Mại', 'thanh-toan-dien-tu-fintech-9', 'Bài học ''Công Nghệ Blockchain & Tiền Điện Tử Trong Thương Mại'' thuộc môn Hệ Thống Thanh Toán Điện Tử & FinTech. Thanh toán phi tập trung Nội dung trọng tâm gồm việc hiểu rõ bản chất của Sổ cái phân tán DLT, Hợp đồng thông minh Smart Contract, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 9, 12, '["Sổ cái phân tán DLT", "Hợp đồng thông minh Smart Contract", "Stablecoin", "Rủi ro biến động"]'::jsonb, 'COMPLETED', 92, 'ses-top-thanh-toan-dien-tu-fintech-09');
