INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-san-tmdt-supply-chain-07', 'sub-ecom-logistics', 'Quản Trị Hoàn Trả Hàng (Reverse Logistics) & Xử Lý Đổi Trả', 'quan-tri-san-tmdt-supply-chain-7', 'Bài học ''Quản Trị Hoàn Trả Hàng (Reverse Logistics) & Xử Lý Đổi Trả'' thuộc môn Quản Trị Sàn TMĐT & Chuỗi Cung Ứng Số. Tối ưu chi phí cho dòng hàng hóa quay ngược Nội dung trọng tâm gồm việc hiểu rõ bản chất của Chính sách đổi trả, Chi phí xử lý đơn trả về, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 7, 14, '["Chính sách đổi trả", "Chi phí xử lý đơn trả về", "Phục hồi giá trị sản phẩm"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-san-tmdt-supply-chain-08', 'sub-ecom-logistics', 'Ứng Dụng Dữ Liệu Lớn & AI Trong Dự Báo Nhu Cầu Chuỗi Cung Ứng', 'quan-tri-san-tmdt-supply-chain-8', 'Bài học ''Ứng Dụng Dữ Liệu Lớn & AI Trong Dự Báo Nhu Cầu Chuỗi Cung Ứng'' thuộc môn Quản Trị Sàn TMĐT & Chuỗi Cung Ứng Số. Chủ động nhập hàng theo mùa vụ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Dự báo nhu cầu Demand Forecasting, Phân tích xu hướng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 7, '["Dự báo nhu cầu Demand Forecasting", "Phân tích xu hướng", "Tối ưu tồn kho tự động"]'::jsonb, 'NEEDS_REVIEW', 62, 'ses-top-quan-tri-san-tmdt-supply-chain-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-san-tmdt-supply-chain-09', 'sub-ecom-logistics', 'Dịch Vụ Khách Hàng & Quản Trị Trải Nghiệm Mua Sắm Trên Sàn', 'quan-tri-san-tmdt-supply-chain-9', 'Bài học ''Dịch Vụ Khách Hàng & Quản Trị Trải Nghiệm Mua Sắm Trên Sàn'' thuộc môn Quản Trị Sàn TMĐT & Chuỗi Cung Ứng Số. Duy trì tỷ lệ đánh giá 5 sao Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tỷ lệ phản hồi chat, Xử lý khiếu nại đánh giá xấu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 9, 9, '["Tỷ lệ phản hồi chat", "Xử lý khiếu nại đánh giá xấu", "Tỷ lệ hủy đơn hàng"]'::jsonb, 'COMPLETED', 97, 'ses-top-quan-tri-san-tmdt-supply-chain-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-san-tmdt-supply-chain-10', 'sub-ecom-logistics', 'Chuyển Đổi Số Chuỗi Cung Ứng Xanh (Green Logistics)', 'quan-tri-san-tmdt-supply-chain-10', 'Bài học ''Chuyển Đổi Số Chuỗi Cung Ứng Xanh (Green Logistics)'' thuộc môn Quản Trị Sàn TMĐT & Chuỗi Cung Ứng Số. Xu hướng phát triển bền vững trong TMĐT Nội dung trọng tâm gồm việc hiểu rõ bản chất của Đóng gói thân thiện môi trường, Phương tiện giao hàng điện, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 12, '["Đóng gói thân thiện môi trường", "Phương tiện giao hàng điện", "Tối ưu dấu chân carbon"]'::jsonb, 'NEEDS_REVIEW', 56, 'ses-top-quan-tri-san-tmdt-supply-chain-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-san-tmdt-supply-chain-11', 'sub-ecom-logistics', 'Quản Trị Sàn TMĐT & Chuỗi Cung Ứng Số - Chuyên Đề Nâng Cao #1', 'quan-tri-san-tmdt-supply-chain-11', 'Bài học ''Quản Trị Sàn TMĐT & Chuỗi Cung Ứng Số - Chuyên Đề Nâng Cao #1'' thuộc môn Quản Trị Sàn TMĐT & Chuỗi Cung Ứng Số. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Quản Trị Sàn TMĐT & Chuỗi Cung Ứng Số. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 11, 8, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-tai-chinh-doanh-nghiep-01', 'sub-acc-financial', 'Khuôn Khổ Chuẩn Mực Kế Toán Quốc Tế IFRS & Chuyển Đổi VAS Sang IFRS', 'ke-toan-tai-chinh-doanh-nghiep-1', 'Bài học ''Khuôn Khổ Chuẩn Mực Kế Toán Quốc Tế IFRS & Chuyển Đổi VAS Sang IFRS'' thuộc môn Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Hội nhập ngôn ngữ tài chính toàn cầu Nội dung trọng tâm gồm việc hiểu rõ bản chất của IFRS Framework, Nguyên tắc giá trị hợp lý Fair Value, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 1, 13, '["IFRS Framework", "Nguyên tắc giá trị hợp lý Fair Value", "Khác biệt cơ bản VAS vs IFRS"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-tai-chinh-doanh-nghiep-02', 'sub-acc-financial', 'Kế Toán Các Công Cụ Tài Chính: Cổ Phiếu, Trái Phiếu & Phái Sinh', 'ke-toan-tai-chinh-doanh-nghiep-2', 'Bài học ''Kế Toán Các Công Cụ Tài Chính: Cổ Phiếu, Trái Phiếu & Phái Sinh'' thuộc môn Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Hạch toán tài sản và nợ tài chính Nội dung trọng tâm gồm việc hiểu rõ bản chất của FVTPL, FVOCI, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 2, 14, '["FVTPL", "FVOCI", "Amortized Cost", "Giao dịch phòng ngừa rủi ro Hedging"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-tai-chinh-doanh-nghiep-03', 'sub-acc-financial', 'Kế Toán Thuê Tài Sản Theo Chuẩn Mực IFRS 16', 'ke-toan-tai-chinh-doanh-nghiep-3', 'Bài học ''Kế Toán Thuê Tài Sản Theo Chuẩn Mực IFRS 16'' thuộc môn Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Ghi nhận quyền sử dụng tài sản trên bảng cân đối Nội dung trọng tâm gồm việc hiểu rõ bản chất của Quyền sử dụng tài sản ROU, Nợ thuê tài chính, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 3, 10, '["Quyền sử dụng tài sản ROU", "Nợ thuê tài chính", "Chi phí khấu hao và lãi vay"]'::jsonb, 'COMPLETED', 85, 'ses-top-ke-toan-tai-chinh-doanh-nghiep-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-tai-chinh-doanh-nghiep-04', 'sub-acc-financial', 'Kế Toán Giao Dịch Ngoại Tệ & Xử Lý Chênh Lệch Tỷ Giá', 'ke-toan-tai-chinh-doanh-nghiep-4', 'Bài học ''Kế Toán Giao Dịch Ngoại Tệ & Xử Lý Chênh Lệch Tỷ Giá'' thuộc môn Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Phản ánh biến động tỷ giá hối đoái Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tỷ giá giao dịch thực tế, Đánh giá lại số dư cuối kỳ, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 4, 11, '["Tỷ giá giao dịch thực tế", "Đánh giá lại số dư cuối kỳ", "Lãi/lỗ chênh lệch tỷ giá"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-tai-chinh-doanh-nghiep-05', 'sub-acc-financial', 'Kế Toán Hợp Nhất Doanh Nghiệp & Lợi Thế Thương Mại (Goodwill)', 'ke-toan-tai-chinh-doanh-nghiep-5', 'Bài học ''Kế Toán Hợp Nhất Doanh Nghiệp & Lợi Thế Thương Mại (Goodwill)'' thuộc môn Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Mua bán và sáp nhập M&A Nội dung trọng tâm gồm việc hiểu rõ bản chất của Phương pháp mua Acquisition Method, Xác định giá phí hợp nhất, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 5, 13, '["Phương pháp mua Acquisition Method", "Xác định giá phí hợp nhất", "Đo lường lợi thế thương mại", "Đánh giá giảm giá trị"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-tai-chinh-doanh-nghiep-06', 'sub-acc-financial', 'Phương Pháp Lập Báo Cáo Tài Chính Hợp Nhất Cho Tập Đoàn', 'ke-toan-tai-chinh-doanh-nghiep-6', 'Bài học ''Phương Pháp Lập Báo Cáo Tài Chính Hợp Nhất Cho Tập Đoàn'' thuộc môn Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Hợp nhất số liệu công ty mẹ và công ty con Nội dung trọng tâm gồm việc hiểu rõ bản chất của Loại trừ giao dịch nội bộ, Lợi ích cổ đông không kiểm soát NCI, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 6, 8, '["Loại trừ giao dịch nội bộ", "Lợi ích cổ đông không kiểm soát NCI", "Chênh lệch giá trị hợp lý"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-tai-chinh-doanh-nghiep-07', 'sub-acc-financial', 'Kế Toán Đầu Tư Vào Công Ty Liên Doanh, Liên Kết (Phương Pháp Vốn Chủ)', 'ke-toan-tai-chinh-doanh-nghiep-7', 'Bài học ''Kế Toán Đầu Tư Vào Công Ty Liên Doanh, Liên Kết (Phương Pháp Vốn Chủ)'' thuộc môn Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Phản ánh tỷ lệ sở hữu đáng kể Nội dung trọng tâm gồm việc hiểu rõ bản chất của Phương pháp vốn chủ sở hữu Equity Method, Ghi nhận phần chia lãi/lỗ, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 7, '["Phương pháp vốn chủ sở hữu Equity Method", "Ghi nhận phần chia lãi/lỗ", "Cổ tức nhận được"]'::jsonb, 'COMPLETED', 88, 'ses-top-ke-toan-tai-chinh-doanh-nghiep-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-tai-chinh-doanh-nghiep-08', 'sub-acc-financial', 'Kế Toán Thuế Thu Nhập Hoãn Lại (Deferred Tax)', 'ke-toan-tai-chinh-doanh-nghiep-8', 'Bài học ''Kế Toán Thuế Thu Nhập Hoãn Lại (Deferred Tax)'' thuộc môn Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Xử lý chênh lệch giữa kế toán và luật thuế Nội dung trọng tâm gồm việc hiểu rõ bản chất của Chênh lệch tạm thời, Tài sản thuế hoãn lại, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 7, '["Chênh lệch tạm thời", "Tài sản thuế hoãn lại", "Thuế thu nhập hoãn lại phải trả"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-ke-toan-tai-chinh-doanh-nghiep-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-tai-chinh-doanh-nghiep-09', 'sub-acc-financial', 'Kế Toán Các Khoản Dự Phòng & Nợ Tiềm Tàng (IAS 37)', 'ke-toan-tai-chinh-doanh-nghiep-9', 'Bài học ''Kế Toán Các Khoản Dự Phòng & Nợ Tiềm Tàng (IAS 37)'' thuộc môn Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Ghi nhận thận trọng nghĩa vụ hiện tại Nội dung trọng tâm gồm việc hiểu rõ bản chất của Điều kiện trích lập dự phòng, Nợ tiềm tàng Contingent Liability, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 9, 13, '["Điều kiện trích lập dự phòng", "Nợ tiềm tàng Contingent Liability", "Ước tính giá trị tốt nhất"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-ke-toan-tai-chinh-doanh-nghiep-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-tai-chinh-doanh-nghiep-10', 'sub-acc-financial', 'Trình Bày & Thuyết Minh Báo Cáo Tài Chính Minh Bạch', 'ke-toan-tai-chinh-doanh-nghiep-10', 'Bài học ''Trình Bày & Thuyết Minh Báo Cáo Tài Chính Minh Bạch'' thuộc môn Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Cung cấp đầy đủ thông tin cho nhà đầu tư Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thuyết minh chính sách kế toán, Sự kiện phát sinh sau ngày kết thúc kỳ kế toán, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 9, '["Thuyết minh chính sách kế toán", "Sự kiện phát sinh sau ngày kết thúc kỳ kế toán", "Giao dịch với các bên liên quan"]'::jsonb, 'COMPLETED', 90, 'ses-top-ke-toan-tai-chinh-doanh-nghiep-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-tai-chinh-doanh-nghiep-11', 'sub-acc-financial', 'Kế Toán Tài Chính Doanh Nghiệp Nâng Cao - Chuyên Đề Nâng Cao #1', 'ke-toan-tai-chinh-doanh-nghiep-11', 'Bài học ''Kế Toán Tài Chính Doanh Nghiệp Nâng Cao - Chuyên Đề Nâng Cao #1'' thuộc môn Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 11, 13, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'COMPLETED', 93, 'ses-top-ke-toan-tai-chinh-doanh-nghiep-11');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-tai-chinh-doanh-nghiep-12', 'sub-acc-financial', 'Kế Toán Tài Chính Doanh Nghiệp Nâng Cao - Chuyên Đề Nâng Cao #2', 'ke-toan-tai-chinh-doanh-nghiep-12', 'Bài học ''Kế Toán Tài Chính Doanh Nghiệp Nâng Cao - Chuyên Đề Nâng Cao #2'' thuộc môn Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Kế Toán Tài Chính Doanh Nghiệp Nâng Cao. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #2A, Kỹ thuật tối ưu #2B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 12, 14, '["Khái niệm nâng cao #2A", "Kỹ thuật tối ưu #2B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-quan-tri-chi-phi-01', 'sub-acc-managerial', 'Bản Chất Của Kế Toán Quản Trị & So Sánh Với Kế Toán Tài Chính', 'ke-toan-quan-tri-chi-phi-1', 'Bài học ''Bản Chất Của Kế Toán Quản Trị & So Sánh Với Kế Toán Tài Chính'' thuộc môn Kế Toán Quản Trị & Phân Tích Chi Phí. Phục vụ quyết định nội bộ của nhà quản lý Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thông tin định hướng tương lai, Đối tượng sử dụng nội bộ, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 1, 11, '["Thông tin định hướng tương lai", "Đối tượng sử dụng nội bộ", "Tính linh hoạt"]'::jsonb, 'COMPLETED', 94, 'ses-top-ke-toan-quan-tri-chi-phi-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-quan-tri-chi-phi-02', 'sub-acc-managerial', 'Phân Loại Chi Phí: Biến Phí, Định Phí & Chi Phí Hỗn Hợp', 'ke-toan-quan-tri-chi-phi-2', 'Bài học ''Phân Loại Chi Phí: Biến Phí, Định Phí & Chi Phí Hỗn Hợp'' thuộc môn Kế Toán Quản Trị & Phân Tích Chi Phí. Thấu hiểu hành vi của chi phí Nội dung trọng tâm gồm việc hiểu rõ bản chất của Biến phí Variable Cost, Định phí Fixed Cost, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 2, 14, '["Biến phí Variable Cost", "Định phí Fixed Cost", "Phương pháp cực đại - cực tiểu High-Low"]'::jsonb, 'COMPLETED', 84, 'ses-top-ke-toan-quan-tri-chi-phi-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-quan-tri-chi-phi-03', 'sub-acc-managerial', 'Phân Tích Mối Quan Hệ Chi Phí - Khối Lượng - Lợi Nhuận (CVP)', 'ke-toan-quan-tri-chi-phi-3', 'Bài học ''Phân Tích Mối Quan Hệ Chi Phí - Khối Lượng - Lợi Nhuận (CVP)'' thuộc môn Kế Toán Quản Trị & Phân Tích Chi Phí. Xác định ngưỡng an toàn kinh doanh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Số dư đảm phí Contribution Margin, Điểm hòa vốn Break-even Point, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 9, '["Số dư đảm phí Contribution Margin", "Điểm hòa vốn Break-even Point", "Biên độ an toàn Margin of Safety"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-quan-tri-chi-phi-04', 'sub-acc-managerial', 'Phương Pháp Xác Định Chi Phí Dựa Trên Hoạt Động (Activity-Based Costing - ABC)', 'ke-toan-quan-tri-chi-phi-4', 'Bài học ''Phương Pháp Xác Định Chi Phí Dựa Trên Hoạt Động (Activity-Based Costing - ABC)'' thuộc môn Kế Toán Quản Trị & Phân Tích Chi Phí. Phân bổ chi phí chung chính xác Nội dung trọng tâm gồm việc hiểu rõ bản chất của Cost Driver, Activity Pool, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 4, 12, '["Cost Driver", "Activity Pool", "Loại bỏ méo mó chi phí"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-ke-toan-quan-tri-chi-phi-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-quan-tri-chi-phi-05', 'sub-acc-managerial', 'Hệ Thống Chi Phí Định Mức & Phân Tích Biến Động (Standard Costing & Variance)', 'ke-toan-quan-tri-chi-phi-5', 'Bài học ''Hệ Thống Chi Phí Định Mức & Phân Tích Biến Động (Standard Costing & Variance)'' thuộc môn Kế Toán Quản Trị & Phân Tích Chi Phí. Kiểm soát chi phí sản xuất Nội dung trọng tâm gồm việc hiểu rõ bản chất của Biến động giá nguyên vật liệu, Biến động lượng sử dụng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 5, 11, '["Biến động giá nguyên vật liệu", "Biến động lượng sử dụng", "Biến động nhân công trực tiếp"]'::jsonb, 'COMPLETED', 90, 'ses-top-ke-toan-quan-tri-chi-phi-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-quan-tri-chi-phi-06', 'sub-acc-managerial', 'Lập Dự Toán Ngân Sách Hoạt Động Doanh Nghiệp (Master Budget)', 'ke-toan-quan-tri-chi-phi-6', 'Bài học ''Lập Dự Toán Ngân Sách Hoạt Động Doanh Nghiệp (Master Budget)'' thuộc môn Kế Toán Quản Trị & Phân Tích Chi Phí. Kế hoạch tài chính toàn diện cho năm tài chính Nội dung trọng tâm gồm việc hiểu rõ bản chất của Dự toán tiêu thụ, Dự toán sản xuất, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 6, 10, '["Dự toán tiêu thụ", "Dự toán sản xuất", "Dự toán dòng tiền Cash Budget"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-quan-tri-chi-phi-07', 'sub-acc-managerial', 'Kế Toán Trách Nhiệm & Đánh Giá Hiệu Quả Bộ Phận (Responsibility Accounting)', 'ke-toan-quan-tri-chi-phi-7', 'Bài học ''Kế Toán Trách Nhiệm & Đánh Giá Hiệu Quả Bộ Phận (Responsibility Accounting)'' thuộc môn Kế Toán Quản Trị & Phân Tích Chi Phí. Đo lường thành tích quản lý Nội dung trọng tâm gồm việc hiểu rõ bản chất của Trung tâm chi phí, Trung tâm doanh thu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 8, '["Trung tâm chi phí", "Trung tâm doanh thu", "Trung tâm lợi nhuận", "Trung tâm đầu tư ROI/RI"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-quan-tri-chi-phi-08', 'sub-acc-managerial', 'Định Giá Chuyển Nhượng Nội Bộ (Transfer Pricing)', 'ke-toan-quan-tri-chi-phi-8', 'Bài học ''Định Giá Chuyển Nhượng Nội Bộ (Transfer Pricing)'' thuộc môn Kế Toán Quản Trị & Phân Tích Chi Phí. Phân bổ lợi nhuận giữa các chi nhánh tập đoàn Nội dung trọng tâm gồm việc hiểu rõ bản chất của Giá chuyển nhượng thị trường, Giá dựa trên chi phí, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 12, '["Giá chuyển nhượng thị trường", "Giá dựa trên chi phí", "Tối ưu hóa thuế hợp pháp"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-ke-toan-quan-tri-chi-phi-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-quan-tri-chi-phi-09', 'sub-acc-managerial', 'Phân Tích Thông Tin Thích Hợp Cho Ra Quyết Định Ngắn Hạn', 'ke-toan-quan-tri-chi-phi-9', 'Bài học ''Phân Tích Thông Tin Thích Hợp Cho Ra Quyết Định Ngắn Hạn'' thuộc môn Kế Toán Quản Trị & Phân Tích Chi Phí. Lựa chọn phương án kinh doanh tối ưu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Đơn đặt hàng đặc biệt, Tự sản xuất hay mua ngoài Make or Buy, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 9, 11, '["Đơn đặt hàng đặc biệt", "Tự sản xuất hay mua ngoài Make or Buy", "Bỏ hay duy trì dòng sản phẩm"]'::jsonb, 'COMPLETED', 95, 'ses-top-ke-toan-quan-tri-chi-phi-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-quan-tri-chi-phi-10', 'sub-acc-managerial', 'Đo Lường Hiệu Suất Chiến Lược Bằng Thẻ Điểm Cân Bằng (Balanced Scorecard)', 'ke-toan-quan-tri-chi-phi-10', 'Bài học ''Đo Lường Hiệu Suất Chiến Lược Bằng Thẻ Điểm Cân Bằng (Balanced Scorecard)'' thuộc môn Kế Toán Quản Trị & Phân Tích Chi Phí. Kết nối chiến lược với hoạt động thực thi Nội dung trọng tâm gồm việc hiểu rõ bản chất của Viễn cảnh tài chính, Viễn cảnh khách hàng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 13, '["Viễn cảnh tài chính", "Viễn cảnh khách hàng", "Viễn cảnh quy trình nội bộ", "Học hỏi và phát triển"]'::jsonb, 'NOT_STARTED', NULL, NULL);
