INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-ke-toan-quan-tri-chi-phi-14', 'sub-acc-managerial', 'Kế Toán Quản Trị & Phân Tích Chi Phí - Chuyên Đề Nâng Cao #4', 'ke-toan-quan-tri-chi-phi-14', 'Bài học ''Kế Toán Quản Trị & Phân Tích Chi Phí - Chuyên Đề Nâng Cao #4'' thuộc môn Kế Toán Quản Trị & Phân Tích Chi Phí. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Kế Toán Quản Trị & Phân Tích Chi Phí. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #4A, Kỹ thuật tối ưu #4B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 14, 11, '["Khái niệm nâng cao #4A", "Kỹ thuật tối ưu #4B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-toan-can-ban-chuan-muc-01', 'sub-acc-audit', 'Bản Chất Của Kiểm Toán & Chuẩn Mực Kiểm Toán Quốc Tế (ISA / VSA)', 'kiem-toan-can-ban-chuan-muc-1', 'Bài học ''Bản Chất Của Kiểm Toán & Chuẩn Mực Kiểm Toán Quốc Tế (ISA / VSA)'' thuộc môn Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán. Đảm bảo tính trung thực và hợp lý của số liệu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Kiểm toán độc lập, Kiểm toán nội bộ, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 1, 9, '["Kiểm toán độc lập", "Kiểm toán nội bộ", "Tính độc lập nghề nghiệp", "Mục tiêu kiểm toán"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-toan-can-ban-chuan-muc-02', 'sub-acc-audit', 'Đạo Đức Nghề Nghiệp Của Kiểm Toán Viên & Trách Nhiệm Pháp Lý', 'kiem-toan-can-ban-chuan-muc-2', 'Bài học ''Đạo Đức Nghề Nghiệp Của Kiểm Toán Viên & Trách Nhiệm Pháp Lý'' thuộc môn Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán. Giữ gìn niềm tin công chúng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tính chính trực, Tính khách quan, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 7, '["Tính chính trực", "Tính khách quan", "Bảo mật thông tin", "Xung đột lợi ích"]'::jsonb, 'COMPLETED', 94, 'ses-top-kiem-toan-can-ban-chuan-muc-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-toan-can-ban-chuan-muc-03', 'sub-acc-audit', 'Mô Hình Rủi Ro Kiểm Toán & Mức Trọng Yếu (Materiality)', 'kiem-toan-can-ban-chuan-muc-3', 'Bài học ''Mô Hình Rủi Ro Kiểm Toán & Mức Trọng Yếu (Materiality)'' thuộc môn Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán. Định hướng phạm vi công việc kiểm toán Nội dung trọng tâm gồm việc hiểu rõ bản chất của Rủi ro tiềm tàng Inherent Risk, Rủi ro kiểm soát Control Risk, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 7, '["Rủi ro tiềm tàng Inherent Risk", "Rủi ro kiểm soát Control Risk", "Rủi ro phát hiện Detection Risk"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-toan-can-ban-chuan-muc-04', 'sub-acc-audit', 'Đánh Giá Hệ Thống Kiểm Soát Nội Bộ Của Khách Hàng (Khung COSO)', 'kiem-toan-can-ban-chuan-muc-4', 'Bài học ''Đánh Giá Hệ Thống Kiểm Soát Nội Bộ Của Khách Hàng (Khung COSO)'' thuộc môn Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán. Thấu hiểu môi trường kiểm soát doanh nghiệp Nội dung trọng tâm gồm việc hiểu rõ bản chất của Môi trường kiểm soát, Đánh giá rủi ro, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 4, 9, '["Môi trường kiểm soát", "Đánh giá rủi ro", "Hoạt động kiểm soát", "Giám sát"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-kiem-toan-can-ban-chuan-muc-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-toan-can-ban-chuan-muc-05', 'sub-acc-audit', 'Thu Thập Bằng Chứng Kiểm Toán & Thử Nghiệm Kiểm Soát', 'kiem-toan-can-ban-chuan-muc-5', 'Bài học ''Thu Thập Bằng Chứng Kiểm Toán & Thử Nghiệm Kiểm Soát'' thuộc môn Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán. Tìm kiếm chứng cứ đầy đủ và thích hợp Nội dung trọng tâm gồm việc hiểu rõ bản chất của Quan sát, Phỏng vấn, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 5, 12, '["Quan sát", "Phỏng vấn", "Gửi thư xác nhận bên thứ ba", "Kiểm tra tài liệu"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-toan-can-ban-chuan-muc-06', 'sub-acc-audit', 'Thủ Tục Phân Tích Trong Kiểm Toán (Analytical Procedures)', 'kiem-toan-can-ban-chuan-muc-6', 'Bài học ''Thủ Tục Phân Tích Trong Kiểm Toán (Analytical Procedures)'' thuộc môn Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán. Phát hiện các bất thường về tỷ lệ và xu hướng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Phân tích tỷ số tài chính, So sánh xu hướng qua các năm, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 6, 10, '["Phân tích tỷ số tài chính", "So sánh xu hướng qua các năm", "Thủ tục phân tích cơ bản"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-kiem-toan-can-ban-chuan-muc-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-toan-can-ban-chuan-muc-07', 'sub-acc-audit', 'Kỹ Thuật Lấy Mẫu Kiểm Toán (Audit Sampling)', 'kiem-toan-can-ban-chuan-muc-7', 'Bài học ''Kỹ Thuật Lấy Mẫu Kiểm Toán (Audit Sampling)'' thuộc môn Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán. Kiểm toán mẫu đại diện cho tổng thể Nội dung trọng tâm gồm việc hiểu rõ bản chất của Lấy mẫu thống kê vs phi thống kê, Cỡ mẫu Sample Size, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 7, 12, '["Lấy mẫu thống kê vs phi thống kê", "Cỡ mẫu Sample Size", "Rủi ro lấy mẫu"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-toan-can-ban-chuan-muc-08', 'sub-acc-audit', 'Kiểm Toán Chu Trình Bán Hàng - Thu Tiền & Nợ Phải Thu', 'kiem-toan-can-ban-chuan-muc-8', 'Bài học ''Kiểm Toán Chu Trình Bán Hàng - Thu Tiền & Nợ Phải Thu'' thuộc môn Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán. Thực hiện kiểm tra thực tế khoản mục trọng yếu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thư xác nhận nợ phải thu, Cắt ngót doanh thu Cut-off, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 8, 9, '["Thư xác nhận nợ phải thu", "Cắt ngót doanh thu Cut-off", "Dự phòng nợ khó đòi"]'::jsonb, 'NEEDS_REVIEW', 56, 'ses-top-kiem-toan-can-ban-chuan-muc-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-toan-can-ban-chuan-muc-09', 'sub-acc-audit', 'Kiểm Toán Chu Trình Mua Hàng - Hàng Tồn Kho & Giá Vốn', 'kiem-toan-can-ban-chuan-muc-9', 'Bài học ''Kiểm Toán Chu Trình Mua Hàng - Hàng Tồn Kho & Giá Vốn'' thuộc môn Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán. Kiểm tra thực tế kho và chi phí Nội dung trọng tâm gồm việc hiểu rõ bản chất của Chứng kiến kiểm kê hàng tồn kho, Định giá hàng tồn kho thấp hơn giá trị thuần, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 9, 14, '["Chứng kiến kiểm kê hàng tồn kho", "Định giá hàng tồn kho thấp hơn giá trị thuần", "Kiểm tra nợ phải trả chưa ghi nhận"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-toan-can-ban-chuan-muc-10', 'sub-acc-audit', 'Báo Cáo Kiểm Toán: Các Dạng Ý Kiến Kiểm Toán Viên', 'kiem-toan-can-ban-chuan-muc-10', 'Bài học ''Báo Cáo Kiểm Toán: Các Dạng Ý Kiến Kiểm Toán Viên'' thuộc môn Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán. Sản phẩm cuối cùng của cuộc kiểm toán Nội dung trọng tâm gồm việc hiểu rõ bản chất của Ý kiến chấp nhận toàn phần, Ý kiến ngoại trừ Qualified, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 10, 12, '["Ý kiến chấp nhận toàn phần", "Ý kiến ngoại trừ Qualified", "Ý kiến trái ngược Adverse", "Từ chối đưa ra ý kiến Disclaimer"]'::jsonb, 'NOT_STARTED', NULL, NULL);
