INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-kiem-toan-can-ban-chuan-muc-15', 'sub-acc-audit', 'Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán - Chuyên Đề Nâng Cao #5', 'kiem-toan-can-ban-chuan-muc-15', 'Bài học ''Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán - Chuyên Đề Nâng Cao #5'' thuộc môn Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Kiểm Toán Căn Bản & Chuẩn Mực Kiểm Toán. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #5A, Kỹ thuật tối ưu #5B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 15, 11, '["Khái niệm nâng cao #5A", "Kỹ thuật tối ưu #5B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thue-bao-cao-thue-doanh-nghiep-01', 'sub-acc-tax', 'Tổng Quan Hệ Thống Thuế Việt Nam & Trách Nhiệm Người Nộp Thuế', 'thue-bao-cao-thue-doanh-nghiep-1', 'Bài học ''Tổng Quan Hệ Thống Thuế Việt Nam & Trách Nhiệm Người Nộp Thuế'' thuộc môn Thuế & Báo Cáo Thuế Doanh Nghiệp. Khung pháp lý về nghĩa vụ thuế Nội dung trọng tâm gồm việc hiểu rõ bản chất của Các sắc thuế chính, Quyền và nghĩa vụ của người nộp thuế, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 1, 12, '["Các sắc thuế chính", "Quyền và nghĩa vụ của người nộp thuế", "Cơ quan thuế"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thue-bao-cao-thue-doanh-nghiep-02', 'sub-acc-tax', 'Thuế Giá Trị Gia Tăng (GTGT): Phương Pháp Khấu Trừ & Trực Tiếp', 'thue-bao-cao-thue-doanh-nghiep-2', 'Bài học ''Thuế Giá Trị Gia Tăng (GTGT): Phương Pháp Khấu Trừ & Trực Tiếp'' thuộc môn Thuế & Báo Cáo Thuế Doanh Nghiệp. Sắc thuế gián thu cốt lõi Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thuế suất 0%, 5%, 10%, Điều kiện khấu trừ thuế đầu vào, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 2, 14, '["Thuế suất 0%, 5%, 10%", "Điều kiện khấu trừ thuế đầu vào", "Đối tượng không chịu thuế"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thue-bao-cao-thue-doanh-nghiep-03', 'sub-acc-tax', 'Hóa Đơn Điện Tử: Quy Định Phát Hành & Xử Lý Sai Sót', 'thue-bao-cao-thue-doanh-nghiep-3', 'Bài học ''Hóa Đơn Điện Tử: Quy Định Phát Hành & Xử Lý Sai Sót'' thuộc môn Thuế & Báo Cáo Thuế Doanh Nghiệp. Bằng chứng pháp lý bắt buộc Nội dung trọng tâm gồm việc hiểu rõ bản chất của Hóa đơn có mã / không mã, Điều chỉnh hóa đơn sai, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 3, 15, '["Hóa đơn có mã / không mã", "Điều chỉnh hóa đơn sai", "Hủy hóa đơn", "Biên bản điều chỉnh"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thue-bao-cao-thue-doanh-nghiep-04', 'sub-acc-tax', 'Thuế Thu Nhập Doanh Nghiệp (TNDN): Xác Định Doanh Thu Tính Thuế', 'thue-bao-cao-thue-doanh-nghiep-4', 'Bài học ''Thuế Thu Nhập Doanh Nghiệp (TNDN): Xác Định Doanh Thu Tính Thuế'' thuộc môn Thuế & Báo Cáo Thuế Doanh Nghiệp. Nghĩa vụ thuế trên lợi nhuận kinh doanh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Doanh thu tính thuế, Thời điểm xác định doanh thu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 4, 10, '["Doanh thu tính thuế", "Thời điểm xác định doanh thu", "Doanh thu tài chính"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thue-bao-cao-thue-doanh-nghiep-05', 'sub-acc-tax', 'Chi Phí Được Trừ & Không Được Trừ Khi Tính Thuế TNDN', 'thue-bao-cao-thue-doanh-nghiep-5', 'Bài học ''Chi Phí Được Trừ & Không Được Trừ Khi Tính Thuế TNDN'' thuộc môn Thuế & Báo Cáo Thuế Doanh Nghiệp. Tối ưu hóa chi phí hợp lệ theo luật thuế Nội dung trọng tâm gồm việc hiểu rõ bản chất của Điều kiện 3 nguyên tắc của chi phí được trừ, Các khoản chi bị khống chế, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 5, 14, '["Điều kiện 3 nguyên tắc của chi phí được trừ", "Các khoản chi bị khống chế", "Hóa đơn thanh toán không dùng tiền mặt"]'::jsonb, 'COMPLETED', 97, 'ses-top-thue-bao-cao-thue-doanh-nghiep-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thue-bao-cao-thue-doanh-nghiep-06', 'sub-acc-tax', 'Chuyển Lỗ & Ưu Đãi Thuế Thu Nhập Doanh Nghiệp', 'thue-bao-cao-thue-doanh-nghiep-6', 'Bài học ''Chuyển Lỗ & Ưu Đãi Thuế Thu Nhập Doanh Nghiệp'' thuộc môn Thuế & Báo Cáo Thuế Doanh Nghiệp. Chính sách khuyến khích đầu tư Nội dung trọng tâm gồm việc hiểu rõ bản chất của Kế hoạch chuyển lỗ 5 năm, Thuế suất ưu đãi 10%, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 6, 8, '["Kế hoạch chuyển lỗ 5 năm", "Thuế suất ưu đãi 10%", "Miễn giảm thuế theo địa bàn và ngành nghề"]'::jsonb, 'COMPLETED', 90, 'ses-top-thue-bao-cao-thue-doanh-nghiep-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thue-bao-cao-thue-doanh-nghiep-07', 'sub-acc-tax', 'Thuế Thu Nhập Cá Nhân (TNCN): Thu Nhập Từ Tiền Lương, Tiền Công', 'thue-bao-cao-thue-doanh-nghiep-7', 'Bài học ''Thuế Thu Nhập Cá Nhân (TNCN): Thu Nhập Từ Tiền Lương, Tiền Công'' thuộc môn Thuế & Báo Cáo Thuế Doanh Nghiệp. Nghĩa vụ thuế của người lao động Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thu nhập chịu thuế vs Tính thuế, Biểu thuế lũy tiến từng phần, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 7, 11, '["Thu nhập chịu thuế vs Tính thuế", "Biểu thuế lũy tiến từng phần", "Giảm trừ gia cảnh bản thân và người phụ thuộc"]'::jsonb, 'COMPLETED', 84, 'ses-top-thue-bao-cao-thue-doanh-nghiep-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thue-bao-cao-thue-doanh-nghiep-08', 'sub-acc-tax', 'Quyết Toán Thuế TNCN & Ủy Quyền Quyết Toán', 'thue-bao-cao-thue-doanh-nghiep-8', 'Bài học ''Quyết Toán Thuế TNCN & Ủy Quyền Quyết Toán'' thuộc môn Thuế & Báo Cáo Thuế Doanh Nghiệp. Quy trình kết thúc năm thuế cá nhân Nội dung trọng tâm gồm việc hiểu rõ bản chất của Điều kiện ủy quyền quyết toán, Tự quyết toán thuế, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 8, 15, '["Điều kiện ủy quyền quyết toán", "Tự quyết toán thuế", "Hoàn thuế TNCN"]'::jsonb, 'COMPLETED', 87, 'ses-top-thue-bao-cao-thue-doanh-nghiep-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thue-bao-cao-thue-doanh-nghiep-09', 'sub-acc-tax', 'Thuế Nhà Thầu Nước Ngoài (FCT) Trong Giao Dịch Xuyên Biên Giới', 'thue-bao-cao-thue-doanh-nghiep-9', 'Bài học ''Thuế Nhà Thầu Nước Ngoài (FCT) Trong Giao Dịch Xuyên Biên Giới'' thuộc môn Thuế & Báo Cáo Thuế Doanh Nghiệp. Nghĩa vụ thuế của doanh nghiệp nước ngoài tại VN Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thuế GTGT nhà thầu, Thuế TNDN nhà thầu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 9, 12, '["Thuế GTGT nhà thầu", "Thuế TNDN nhà thầu", "Phương pháp nộp thuế trực tiếp"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-thue-bao-cao-thue-doanh-nghiep-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thue-bao-cao-thue-doanh-nghiep-10', 'sub-acc-tax', 'Lập Kế Hoạch Thuế Hợp Pháp (Tax Planning) & Phòng Tránh Rủi Ro', 'thue-bao-cao-thue-doanh-nghiep-10', 'Bài học ''Lập Kế Hoạch Thuế Hợp Pháp (Tax Planning) & Phòng Tránh Rủi Ro'' thuộc môn Thuế & Báo Cáo Thuế Doanh Nghiệp. Tối ưu hóa dòng tiền và tuân thủ pháp luật Nội dung trọng tâm gồm việc hiểu rõ bản chất của Trốn thuế vs Tránh thuế hợp pháp, Chuẩn bị hồ sơ thanh tra thuế, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 10, 15, '["Trốn thuế vs Tránh thuế hợp pháp", "Chuẩn bị hồ sơ thanh tra thuế", "Giải trình số liệu"]'::jsonb, 'NOT_STARTED', NULL, NULL);
