INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-thue-bao-cao-thue-doanh-nghiep-14', 'sub-acc-tax', 'Thuế & Báo Cáo Thuế Doanh Nghiệp - Chuyên Đề Nâng Cao #4', 'thue-bao-cao-thue-doanh-nghiep-14', 'Bài học ''Thuế & Báo Cáo Thuế Doanh Nghiệp - Chuyên Đề Nâng Cao #4'' thuộc môn Thuế & Báo Cáo Thuế Doanh Nghiệp. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Thuế & Báo Cáo Thuế Doanh Nghiệp. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #4A, Kỹ thuật tối ưu #4B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 14, 10, '["Khái niệm nâng cao #4A", "Kỹ thuật tối ưu #4B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-thue-bao-cao-thue-doanh-nghiep-14');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-chien-luoc-kinh-doanh-01', 'sub-biz-strategy', 'Bản Chất Của Chiến Lược & Tầm Nhìn - Sứ Mệnh Doanh Nghiệp', 'quan-tri-chien-luoc-kinh-doanh-1', 'Bài học ''Bản Chất Của Chiến Lược & Tầm Nhìn - Sứ Mệnh Doanh Nghiệp'' thuộc môn Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Xác định kim chỉ nam cho sự phát triển Nội dung trọng tâm gồm việc hiểu rõ bản chất của Sứ mệnh Mission, Tầm nhìn Vision, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 1, 12, '["Sứ mệnh Mission", "Tầm nhìn Vision", "Giá trị cốt lõi Core Values", "Mục tiêu chiến lược"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-chien-luoc-kinh-doanh-02', 'sub-biz-strategy', 'Mô Hình 5 Lực Lượng Cạnh Tranh Của Michael Porter', 'quan-tri-chien-luoc-kinh-doanh-2', 'Bài học ''Mô Hình 5 Lực Lượng Cạnh Tranh Của Michael Porter'' thuộc môn Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Phân tích sức hấp dẫn của ngành Nội dung trọng tâm gồm việc hiểu rõ bản chất của Áp lực từ nhà cung cấp, Sức mạnh người mua, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 12, '["Áp lực từ nhà cung cấp", "Sức mạnh người mua", "Nguy cơ từ sản phẩm thay thế", "Rào cản gia nhập", "Cạnh tranh nội bộ ngành"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-chien-luoc-kinh-doanh-03', 'sub-biz-strategy', 'Phân Tích Nguồn Lực Nội Bộ Doanh Nghiệp Bằng Khung VRIO', 'quan-tri-chien-luoc-kinh-doanh-3', 'Bài học ''Phân Tích Nguồn Lực Nội Bộ Doanh Nghiệp Bằng Khung VRIO'' thuộc môn Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Xác định năng lực cốt lõi bền vững Nội dung trọng tâm gồm việc hiểu rõ bản chất của Giá trị Value, Độ hiếm Rarity, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 3, 10, '["Giá trị Value", "Độ hiếm Rarity", "Khó sao chép Inimitability", "Tổ chức khai thác Organization"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-quan-tri-chien-luoc-kinh-doanh-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-chien-luoc-kinh-doanh-04', 'sub-biz-strategy', 'Ma Trận SWOT & Xây Dựng Các Phương Án Chiến Lược', 'quan-tri-chien-luoc-kinh-doanh-4', 'Bài học ''Ma Trận SWOT & Xây Dựng Các Phương Án Chiến Lược'' thuộc môn Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Kết hợp điểm mạnh yếu với cơ hội thách thức Nội dung trọng tâm gồm việc hiểu rõ bản chất của Chiến lược SO, Chiến lược WO, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 4, 14, '["Chiến lược SO", "Chiến lược WO", "Chiến lược ST", "Chiến lược WT"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-chien-luoc-kinh-doanh-05', 'sub-biz-strategy', 'Các Chiến Lược Cạnh Tranh Tổng Quát Của Michael Porter', 'quan-tri-chien-luoc-kinh-doanh-5', 'Bài học ''Các Chiến Lược Cạnh Tranh Tổng Quát Của Michael Porter'' thuộc môn Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Xác lập vị thế trên thị trường Nội dung trọng tâm gồm việc hiểu rõ bản chất của Dẫn đầu về chi phí thấp Cost Leadership, Khác biệt hóa sản phẩm Differentiation, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 5, 7, '["Dẫn đầu về chi phí thấp Cost Leadership", "Khác biệt hóa sản phẩm Differentiation", "Chiến lược tập trung Focus"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-chien-luoc-kinh-doanh-06', 'sub-biz-strategy', 'Chiến Lược Tăng Trưởng Bằng Ma Trận Ansoff', 'quan-tri-chien-luoc-kinh-doanh-6', 'Bài học ''Chiến Lược Tăng Trưởng Bằng Ma Trận Ansoff'' thuộc môn Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Mở rộng hoạt động kinh doanh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thâm nhập thị trường, Phát triển thị trường, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 6, 10, '["Thâm nhập thị trường", "Phát triển thị trường", "Phát triển sản phẩm", "Đa dạng hóa kinh doanh"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-chien-luoc-kinh-doanh-07', 'sub-biz-strategy', 'Chiến Lược Đại Dương Xanh (Blue Ocean Strategy)', 'quan-tri-chien-luoc-kinh-doanh-7', 'Bài học ''Chiến Lược Đại Dương Xanh (Blue Ocean Strategy)'' thuộc môn Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Tạo lập không gian thị trường mới không có cạnh tranh Nội dung trọng tâm gồm việc hiểu rõ bản chất của Đại dương đỏ vs đại dương xanh, Khung 4 hành động (ERAC), vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 7, 10, '["Đại dương đỏ vs đại dương xanh", "Khung 4 hành động (ERAC)", "Đổi mới giá trị Value Innovation"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-chien-luoc-kinh-doanh-08', 'sub-biz-strategy', 'Chiến Lược Mua Bán - Sáp Nhập (M&A) & Liên Minh Chiến Lược', 'quan-tri-chien-luoc-kinh-doanh-8', 'Bài học ''Chiến Lược Mua Bán - Sáp Nhập (M&A) & Liên Minh Chiến Lược'' thuộc môn Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Tăng trưởng ngoại sinh nhanh chóng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Sáp nhập ngang/dọc, Hiệp lực Synergy, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 15, '["Sáp nhập ngang/dọc", "Hiệp lực Synergy", "Rủi ro hội nhập văn hóa", "Liên doanh Joint Venture"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-chien-luoc-kinh-doanh-09', 'sub-biz-strategy', 'Thực Thi Chiến Lược & Quản Trị Sự Thay Đổi Trong Tổ Chức', 'quan-tri-chien-luoc-kinh-doanh-9', 'Bài học ''Thực Thi Chiến Lược & Quản Trị Sự Thay Đổi Trong Tổ Chức'' thuộc môn Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Biến kế hoạch trên giấy thành kết quả thực tế Nội dung trọng tâm gồm việc hiểu rõ bản chất của Mô hình 7S của McKinsey, Quản trị thay đổi 8 bước Kotter, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 9, 12, '["Mô hình 7S của McKinsey", "Quản trị thay đổi 8 bước Kotter", "Giao tiếp chiến lược"]'::jsonb, 'NEEDS_REVIEW', 55, 'ses-top-quan-tri-chien-luoc-kinh-doanh-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-chien-luoc-kinh-doanh-10', 'sub-biz-strategy', 'Kiểm Soát & Đánh Giá Chiến Lược (Strategic Control)', 'quan-tri-chien-luoc-kinh-doanh-10', 'Bài học ''Kiểm Soát & Đánh Giá Chiến Lược (Strategic Control)'' thuộc môn Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Điều chỉnh lộ trình phù hợp với biến động thị trường Nội dung trọng tâm gồm việc hiểu rõ bản chất của KPIs chiến lược, Đánh giá lại giả định ban đầu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 7, '["KPIs chiến lược", "Đánh giá lại giả định ban đầu", "Linh hoạt chiến lược Agility"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-chien-luoc-kinh-doanh-11', 'sub-biz-strategy', 'Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh - Chuyên Đề Nâng Cao #1', 'quan-tri-chien-luoc-kinh-doanh-11', 'Bài học ''Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh - Chuyên Đề Nâng Cao #1'' thuộc môn Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 11, 9, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-chien-luoc-kinh-doanh-12', 'sub-biz-strategy', 'Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh - Chuyên Đề Nâng Cao #2', 'quan-tri-chien-luoc-kinh-doanh-12', 'Bài học ''Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh - Chuyên Đề Nâng Cao #2'' thuộc môn Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Quản Trị Chiến Lược & Lợi Thế Cạnh Tranh. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #2A, Kỹ thuật tối ưu #2B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 12, 8, '["Khái niệm nâng cao #2A", "Kỹ thuật tối ưu #2B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NEEDS_REVIEW', 53, 'ses-top-quan-tri-chien-luoc-kinh-doanh-12');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tai-chinh-doanh-nghiep-dau-tu-01', 'sub-biz-finance', 'Mục Tiêu Quản Trị Tài Chính: Tối Đa Hóa Giá Trị Cổ Đông', 'tai-chinh-doanh-nghiep-dau-tu-1', 'Bài học ''Mục Tiêu Quản Trị Tài Chính: Tối Đa Hóa Giá Trị Cổ Đông'' thuộc môn Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư. Nguyên lý dẫn dắt các quyết định tài chính Nội dung trọng tâm gồm việc hiểu rõ bản chất của Mâu thuẫn đại diện Agency Problem, Quản trị dòng tiền, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 1, 10, '["Mâu thuẫn đại diện Agency Problem", "Quản trị dòng tiền", "Đạo đức tài chính"]'::jsonb, 'COMPLETED', 89, 'ses-top-tai-chinh-doanh-nghiep-dau-tu-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tai-chinh-doanh-nghiep-dau-tu-02', 'sub-biz-finance', 'Giá Trị Thời Gian Của Tiền Tệ (Time Value of Money - TVM)', 'tai-chinh-doanh-nghiep-dau-tu-2', 'Bài học ''Giá Trị Thời Gian Của Tiền Tệ (Time Value of Money - TVM)'' thuộc môn Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư. Một đồng hôm nay giá trị hơn một đồng ngày mai Nội dung trọng tâm gồm việc hiểu rõ bản chất của Giá trị tương lai FV, Giá trị hiện tại PV, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 9, '["Giá trị tương lai FV", "Giá trị hiện tại PV", "Dòng tiền đều Annuity", "Chiết khấu dòng tiền DCF"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-tai-chinh-doanh-nghiep-dau-tu-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tai-chinh-doanh-nghiep-dau-tu-03', 'sub-biz-finance', 'Thẩm Định Dự Án Đầu Tư: Phương Pháp Giá Trị Hiện Tại Thuần (NPV)', 'tai-chinh-doanh-nghiep-dau-tu-3', 'Bài học ''Thẩm Định Dự Án Đầu Tư: Phương Pháp Giá Trị Hiện Tại Thuần (NPV)'' thuộc môn Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư. Thước đo số một trong quyết định đầu tư Nội dung trọng tâm gồm việc hiểu rõ bản chất của Dòng tiền tự do FCF, Tỷ suất chiết khấu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 13, '["Dòng tiền tự do FCF", "Tỷ suất chiết khấu", "Quy tắc chấp nhận dự án NPV > 0"]'::jsonb, 'COMPLETED', 95, 'ses-top-tai-chinh-doanh-nghiep-dau-tu-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tai-chinh-doanh-nghiep-dau-tu-04', 'sub-biz-finance', 'Thẩm Định Dự Án Bằng Tỷ Suất Hoàn Vốn Nội Bộ (IRR) & Thời Gian Hoàn Vốn', 'tai-chinh-doanh-nghiep-dau-tu-4', 'Bài học ''Thẩm Định Dự Án Bằng Tỷ Suất Hoàn Vốn Nội Bộ (IRR) & Thời Gian Hoàn Vốn'' thuộc môn Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư. Các tiêu chí hỗ trợ đánh giá Nội dung trọng tâm gồm việc hiểu rõ bản chất của IRR, Modified IRR (MIRR), vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 4, 14, '["IRR", "Modified IRR (MIRR)", "Thời gian hoàn vốn Payback Period"]'::jsonb, 'COMPLETED', 85, 'ses-top-tai-chinh-doanh-nghiep-dau-tu-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tai-chinh-doanh-nghiep-dau-tu-05', 'sub-biz-finance', 'Mô Hình Định Giá Tài Sản Vốn (CAPM) & Đo Lường Rủi Ro', 'tai-chinh-doanh-nghiep-dau-tu-5', 'Bài học ''Mô Hình Định Giá Tài Sản Vốn (CAPM) & Đo Lường Rủi Ro'' thuộc môn Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư. Định giá tỷ suất sinh lời kỳ vọng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Rủi ro hệ thống Beta, Lãi suất phi rủi ro Rf, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 5, 15, '["Rủi ro hệ thống Beta", "Lãi suất phi rủi ro Rf", "Phần bù rủi ro thị trường"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tai-chinh-doanh-nghiep-dau-tu-06', 'sub-biz-finance', 'Chi Phí Vốn Bình Quân (Weighted Average Cost of Capital - WACC)', 'tai-chinh-doanh-nghiep-dau-tu-6', 'Bài học ''Chi Phí Vốn Bình Quân (Weighted Average Cost of Capital - WACC)'' thuộc môn Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư. Chi phí sử dụng vốn của doanh nghiệp Nội dung trọng tâm gồm việc hiểu rõ bản chất của Chi phí vốn vay sau thuế, Chi phí vốn cổ phần, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 6, 10, '["Chi phí vốn vay sau thuế", "Chi phí vốn cổ phần", "Tỷ trọng cấu trúc vốn"]'::jsonb, 'COMPLETED', 92, 'ses-top-tai-chinh-doanh-nghiep-dau-tu-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tai-chinh-doanh-nghiep-dau-tu-07', 'sub-biz-finance', 'Cấu Trúc Vốn & Lý Thuyết Modigliani-Miller (M&M)', 'tai-chinh-doanh-nghiep-dau-tu-7', 'Bài học ''Cấu Trúc Vốn & Lý Thuyết Modigliani-Miller (M&M)'' thuộc môn Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư. Sự đánh đổi giữa nợ vay và lá chắn thuế Nội dung trọng tâm gồm việc hiểu rõ bản chất của Đòn bẩy tài chính, Lá chắn thuế lãi vay Tax Shield, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 7, 15, '["Đòn bẩy tài chính", "Lá chắn thuế lãi vay Tax Shield", "Chi phí kiệt quệ tài chính"]'::jsonb, 'COMPLETED', 96, 'ses-top-tai-chinh-doanh-nghiep-dau-tu-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tai-chinh-doanh-nghiep-dau-tu-08', 'sub-biz-finance', 'Chính Sách Cổ Tức Doanh Nghiệp: Tiền Mặt Hay Cổ Phiếu?', 'tai-chinh-doanh-nghiep-dau-tu-8', 'Bài học ''Chính Sách Cổ Tức Doanh Nghiệp: Tiền Mặt Hay Cổ Phiếu?'' thuộc môn Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư. Phân phối lợi nhuận cho nhà đầu tư Nội dung trọng tâm gồm việc hiểu rõ bản chất của Cổ tức tiền mặt, Cổ tức cổ phiếu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 8, 7, '["Cổ tức tiền mặt", "Cổ tức cổ phiếu", "Mua lại cổ phiếu Treasury Shares", "Hiệu ứng tín hiệu"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-tai-chinh-doanh-nghiep-dau-tu-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tai-chinh-doanh-nghiep-dau-tu-09', 'sub-biz-finance', 'Quản Trị Vốn Lưu Động & Vòng Chu Chuyển Tiền Mặt (CCC)', 'tai-chinh-doanh-nghiep-dau-tu-9', 'Bài học ''Quản Trị Vốn Lưu Động & Vòng Chu Chuyển Tiền Mặt (CCC)'' thuộc môn Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư. Đảm bảo khả năng thanh toán tức thời Nội dung trọng tâm gồm việc hiểu rõ bản chất của Kỳ thu tiền bình quan DSO, Vòng quay hàng tồn kho DIO, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 9, 13, '["Kỳ thu tiền bình quan DSO", "Vòng quay hàng tồn kho DIO", "Kỳ trả tiền bình quân DPO", "Tối ưu hóa CCC"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tai-chinh-doanh-nghiep-dau-tu-10', 'sub-biz-finance', 'Định Giá Doanh Nghiệp: Phương Pháp Chiết Khấu Dòng Tiền (DCF) & Bội Số (P/E, EV/EBITDA)', 'tai-chinh-doanh-nghiep-dau-tu-10', 'Bài học ''Định Giá Doanh Nghiệp: Phương Pháp Chiết Khấu Dòng Tiền (DCF) & Bội Số (P/E, EV/EBITDA)'' thuộc môn Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư. Xác định giá trị thực của công ty Nội dung trọng tâm gồm việc hiểu rõ bản chất của Enterprise Value EV, Bội số P/E, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 10, 14, '["Enterprise Value EV", "Bội số P/E", "Bội số EV/EBITDA", "Định giá trong M&A"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-tai-chinh-doanh-nghiep-dau-tu-11', 'sub-biz-finance', 'Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư - Chuyên Đề Nâng Cao #1', 'tai-chinh-doanh-nghiep-dau-tu-11', 'Bài học ''Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư - Chuyên Đề Nâng Cao #1'' thuộc môn Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Quản Trị Tài Chính Doanh Nghiệp & Đầu Tư. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 11, 8, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
