INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-nhan-su-to-chuc-01', 'sub-biz-hrm', 'Vai Trò Của Quản Trị Nhân Lực Hiện Đại: Từ Hành Chính Đến Đối Tác Chiến Lược (HRBP)', 'quan-tri-nhan-su-to-chuc-1', 'Bài học ''Vai Trò Của Quản Trị Nhân Lực Hiện Đại: Từ Hành Chính Đến Đối Tác Chiến Lược (HRBP)'' thuộc môn Quản Trị Nguồn Nhân Lực & Văn Hóa Tổ Chức. Nhân sự là tài sản quan trọng nhất Nội dung trọng tâm gồm việc hiểu rõ bản chất của Mô hình Dave Ulrich, HR Business Partner, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 1, 15, '["Mô hình Dave Ulrich", "HR Business Partner", "Chiến lược nhân tài"]'::jsonb, 'COMPLETED', 94, 'ses-top-quan-tri-nhan-su-to-chuc-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-nhan-su-to-chuc-02', 'sub-biz-hrm', 'Hoạch Định Nguồn Nhân Lực & Phân Tích Công Việc (Job Analysis)', 'quan-tri-nhan-su-to-chuc-2', 'Bài học ''Hoạch Định Nguồn Nhân Lực & Phân Tích Công Việc (Job Analysis)'' thuộc môn Quản Trị Nguồn Nhân Lực & Văn Hóa Tổ Chức. Định biên nhân sự chuẩn xác Nội dung trọng tâm gồm việc hiểu rõ bản chất của Bản mô tả công việc JD, Bản tiêu chuẩn công việc JS, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 13, '["Bản mô tả công việc JD", "Bản tiêu chuẩn công việc JS", "Dự báo thừa thiếu nhân lực"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-nhan-su-to-chuc-03', 'sub-biz-hrm', 'Quy Trình Tuyển Dụng & Phỏng Vấn Dựa Trên Năng Lực (Mô Hình STAR)', 'quan-tri-nhan-su-to-chuc-3', 'Bài học ''Quy Trình Tuyển Dụng & Phỏng Vấn Dựa Trên Năng Lực (Mô Hình STAR)'' thuộc môn Quản Trị Nguồn Nhân Lực & Văn Hóa Tổ Chức. Tìm đúng người cho đúng việc Nội dung trọng tâm gồm việc hiểu rõ bản chất của Kênh tuyển dụng, Phỏng vấn tình huống STAR, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 13, '["Kênh tuyển dụng", "Phỏng vấn tình huống STAR", "Thương lượng thư mời nhận việc Offer Letter"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-nhan-su-to-chuc-04', 'sub-biz-hrm', 'Đào Tạo & Phát Triển Nguồn Nhân Lực (Mô Hình 70-20-10)', 'quan-tri-nhan-su-to-chuc-4', 'Bài học ''Đào Tạo & Phát Triển Nguồn Nhân Lực (Mô Hình 70-20-10)'' thuộc môn Quản Trị Nguồn Nhân Lực & Văn Hóa Tổ Chức. Nâng cao năng lực cạnh tranh cho nhân sự Nội dung trọng tâm gồm việc hiểu rõ bản chất của Đào tạo tại chỗ OJT, Khung năng lực Competency Framework, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 4, 13, '["Đào tạo tại chỗ OJT", "Khung năng lực Competency Framework", "Lộ trình thăng tiến Career Path"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-nhan-su-to-chuc-05', 'sub-biz-hrm', 'Quản Trị Hiệu Suất: Phân Biệt Giữa KPI (Chỉ Số Hiệu Suất) và OKR (Mục Tiêu & Kết Quả Then Chốt)', 'quan-tri-nhan-su-to-chuc-5', 'Bài học ''Quản Trị Hiệu Suất: Phân Biệt Giữa KPI (Chỉ Số Hiệu Suất) và OKR (Mục Tiêu & Kết Quả Then Chốt)'' thuộc môn Quản Trị Nguồn Nhân Lực & Văn Hóa Tổ Chức. Định hướng hành động nhân viên Nội dung trọng tâm gồm việc hiểu rõ bản chất của Nguyên tắc SMART, Hệ thống KPI, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 5, 12, '["Nguyên tắc SMART", "Hệ thống KPI", "Khung OKR linh hoạt", "Đánh giá 360 độ"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-nhan-su-to-chuc-06', 'sub-biz-hrm', 'Hệ Thống Đãi Ngộ Toàn Diện (Total Rewards) & Cơ Cấu Lương 3P', 'quan-tri-nhan-su-to-chuc-6', 'Bài học ''Hệ Thống Đãi Ngộ Toàn Diện (Total Rewards) & Cơ Cấu Lương 3P'' thuộc môn Quản Trị Nguồn Nhân Lực & Văn Hóa Tổ Chức. Thu hút và giữ chân nhân tài Nội dung trọng tâm gồm việc hiểu rõ bản chất của Lương theo vị trí P1, Lương theo năng lực P2, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 6, 12, '["Lương theo vị trí P1", "Lương theo năng lực P2", "Lương theo hiệu quả P3", "Phúc lợi nhân viên"]'::jsonb, 'COMPLETED', 88, 'ses-top-quan-tri-nhan-su-to-chuc-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-nhan-su-to-chuc-07', 'sub-biz-hrm', 'Các Lý Thuyết Động Viên Nhân Viên: Maslow, Herzberg & Thuyết Tự Quyết', 'quan-tri-nhan-su-to-chuc-7', 'Bài học ''Các Lý Thuyết Động Viên Nhân Viên: Maslow, Herzberg & Thuyết Tự Quyết'' thuộc môn Quản Trị Nguồn Nhân Lực & Văn Hóa Tổ Chức. Thúc đẩy nhiệt huyết làm việc Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tháp nhu cầu Maslow, Thuyết 2 nhân tố Herzberg, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 7, 14, '["Tháp nhu cầu Maslow", "Thuyết 2 nhân tố Herzberg", "Động lực nội tại vs ngoại tại"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-nhan-su-to-chuc-08', 'sub-biz-hrm', 'Xây Dựng Văn Hóa Doanh Nghiệp & Gắn Kết Nhân Viên (Employee Engagement)', 'quan-tri-nhan-su-to-chuc-8', 'Bài học ''Xây Dựng Văn Hóa Doanh Nghiệp & Gắn Kết Nhân Viên (Employee Engagement)'' thuộc môn Quản Trị Nguồn Nhân Lực & Văn Hóa Tổ Chức. Linh hồn của tổ chức Nội dung trọng tâm gồm việc hiểu rõ bản chất của Các cấp độ văn hóa Schein, Khảo sát mức độ gắn kết eNPS, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 8, '["Các cấp độ văn hóa Schein", "Khảo sát mức độ gắn kết eNPS", "Môi trường làm việc hạnh phúc"]'::jsonb, 'COMPLETED', 85, 'ses-top-quan-tri-nhan-su-to-chuc-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-nhan-su-to-chuc-09', 'sub-biz-hrm', 'Quan Hệ Lao Động & Giải Quyết Tranh Chấp Lao Động', 'quan-tri-nhan-su-to-chuc-9', 'Bài học ''Quan Hệ Lao Động & Giải Quyết Tranh Chấp Lao Động'' thuộc môn Quản Trị Nguồn Nhân Lực & Văn Hóa Tổ Chức. Tuân thủ pháp luật và giữ gìn hòa khí Nội dung trọng tâm gồm việc hiểu rõ bản chất của Hợp đồng lao động, Kỷ luật sa thải, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 9, 12, '["Hợp đồng lao động", "Kỷ luật sa thải", "Thỏa ước lao động tập thể", "Công đoàn"]'::jsonb, 'COMPLETED', 95, 'ses-top-quan-tri-nhan-su-to-chuc-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-nhan-su-to-chuc-10', 'sub-biz-hrm', 'Quy Hoạch Kế Thừa (Succession Planning) & Giữ Chân Nhân Sự Trọng Yếu', 'quan-tri-nhan-su-to-chuc-10', 'Bài học ''Quy Hoạch Kế Thừa (Succession Planning) & Giữ Chân Nhân Sự Trọng Yếu'' thuộc môn Quản Trị Nguồn Nhân Lực & Văn Hóa Tổ Chức. Đảm bảo sự liên tục trong ban lãnh đạo Nội dung trọng tâm gồm việc hiểu rõ bản chất của Nhân sự chủ chốt Key Talent, Ma trận 9 ô 9-Box Grid, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 15, '["Nhân sự chủ chốt Key Talent", "Ma trận 9 ô 9-Box Grid", "Kế hoạch chuyển giao"]'::jsonb, 'NEEDS_REVIEW', 65, 'ses-top-quan-tri-nhan-su-to-chuc-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-khoi-nghiep-doi-moi-sang-tao-01', 'sub-biz-startup', 'Tư Duy Khởi Nghiệp Tinh Gọn (Lean Startup Methodology)', 'khoi-nghiep-doi-moi-sang-tao-1', 'Bài học ''Tư Duy Khởi Nghiệp Tinh Gọn (Lean Startup Methodology)'' thuộc môn Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Thử nghiệm nhanh, thất bại sớm, học hỏi liên tục Nội dung trọng tâm gồm việc hiểu rõ bản chất của Vòng lặp Xây dựng - Đo lường - Học hỏi, Sản phẩm khả thi tối thiểu MVP, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 1, 13, '["Vòng lặp Xây dựng - Đo lường - Học hỏi", "Sản phẩm khả thi tối thiểu MVP", "Xoay trục Pivot"]'::jsonb, 'COMPLETED', 89, 'ses-top-khoi-nghiep-doi-moi-sang-tao-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-khoi-nghiep-doi-moi-sang-tao-02', 'sub-biz-startup', 'Thiết Kế Mô Hình Kinh Doanh Bằng Bảng Canvas (Business Model Canvas - BMC)', 'khoi-nghiep-doi-moi-sang-tao-2', 'Bài học ''Thiết Kế Mô Hình Kinh Doanh Bằng Bảng Canvas (Business Model Canvas - BMC)'' thuộc môn Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Phác thảo toàn bộ doanh nghiệp trên một trang giấy Nội dung trọng tâm gồm việc hiểu rõ bản chất của 9 khối BMC, Phân khúc khách hàng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 11, '["9 khối BMC", "Phân khúc khách hàng", "Đề xuất giá trị", "Dòng doanh thu"]'::jsonb, 'COMPLETED', 88, 'ses-top-khoi-nghiep-doi-moi-sang-tao-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-khoi-nghiep-doi-moi-sang-tao-03', 'sub-biz-startup', 'Quy Trình Tư Duy Thiết Kế (Design Thinking) Giải Quyết Vấn Đề', 'khoi-nghiep-doi-moi-sang-tao-3', 'Bài học ''Quy Trình Tư Duy Thiết Kế (Design Thinking) Giải Quyết Vấn Đề'' thuộc môn Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Sáng tạo giải pháp lấy con người làm trung tâm Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thấu cảm Empathize, Xác định vấn đề Define, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 10, '["Thấu cảm Empathize", "Xác định vấn đề Define", "Lên ý tưởng Ideate", "Tạo mẫu Prototype", "Thử nghiệm Test"]'::jsonb, 'COMPLETED', 92, 'ses-top-khoi-nghiep-doi-moi-sang-tao-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-khoi-nghiep-doi-moi-sang-tao-04', 'sub-biz-startup', 'Tìm Kiếm Sự Phù Hợp Sản Phẩm - Thị Trường (Product-Market Fit - PMF)', 'khoi-nghiep-doi-moi-sang-tao-4', 'Bài học ''Tìm Kiếm Sự Phù Hợp Sản Phẩm - Thị Trường (Product-Market Fit - PMF)'' thuộc môn Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Cột mốc sống còn của mọi startup Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khảo sát Sean Ellis 40%, Tỷ lệ giữ chân người dùng Retention Curve, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 4, 10, '["Khảo sát Sean Ellis 40%", "Tỷ lệ giữ chân người dùng Retention Curve", "Chỉ số tăng trưởng tự nhiên"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-khoi-nghiep-doi-moi-sang-tao-05', 'sub-biz-startup', 'Nghiên Cứu Khách Hàng Bằng Phương Pháp Phỏng Vấn (The Mom Test)', 'khoi-nghiep-doi-moi-sang-tao-5', 'Bài học ''Nghiên Cứu Khách Hàng Bằng Phương Pháp Phỏng Vấn (The Mom Test)'' thuộc môn Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Hỏi đúng câu hỏi để không bị khen xã giao Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tránh hỏi về tương lai, Hỏi về hành vi trong quá khứ, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 5, 15, '["Tránh hỏi về tương lai", "Hỏi về hành vi trong quá khứ", "Lắng nghe nỗi đau thực sự"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-khoi-nghiep-doi-moi-sang-tao-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-khoi-nghiep-doi-moi-sang-tao-06', 'sub-biz-startup', 'Kinh Tế Học Đơn Vị (Unit Economics): CAC, LTV và Thời Gian Hoàn Vốn', 'khoi-nghiep-doi-moi-sang-tao-6', 'Bài học ''Kinh Tế Học Đơn Vị (Unit Economics): CAC, LTV và Thời Gian Hoàn Vốn'' thuộc môn Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Đảm bảo mô hình kinh doanh có lãi ở quy mô lớn Nội dung trọng tâm gồm việc hiểu rõ bản chất của Customer Acquisition Cost CAC, Lifetime Value LTV, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 6, 10, '["Customer Acquisition Cost CAC", "Lifetime Value LTV", "Tỷ lệ LTV/CAC > 3", "Payback Period"]'::jsonb, 'COMPLETED', 88, 'ses-top-khoi-nghiep-doi-moi-sang-tao-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-khoi-nghiep-doi-moi-sang-tao-07', 'sub-biz-startup', 'Nghệ Thuật Trình Bày Ý Tưởng Gọi Vốn (Pitch Deck)', 'khoi-nghiep-doi-moi-sang-tao-7', 'Bài học ''Nghệ Thuật Trình Bày Ý Tưởng Gọi Vốn (Pitch Deck)'' thuộc môn Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Thuyết phục nhà đầu tư trong 10 phút Nội dung trọng tâm gồm việc hiểu rõ bản chất của 10-12 slides chuẩn mực, Trình bày vấn đề và giải pháp, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 15, '["10-12 slides chuẩn mực", "Trình bày vấn đề và giải pháp", "Quy mô thị trường TAM-SAM-SOM", "Đội ngũ sáng lập"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-khoi-nghiep-doi-moi-sang-tao-08', 'sub-biz-startup', 'Các Vòng Gọi Vốn Khởi Nghiệp: Từ Thiên Thần Đến Series A/B/C', 'khoi-nghiep-doi-moi-sang-tao-8', 'Bài học ''Các Vòng Gọi Vốn Khởi Nghiệp: Từ Thiên Thần Đến Series A/B/C'' thuộc môn Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Hành trình huy động vốn mạo hiểm Nội dung trọng tâm gồm việc hiểu rõ bản chất của Pre-seed & Seed, Nhà đầu tư thiên thần Angel Investor, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 11, '["Pre-seed & Seed", "Nhà đầu tư thiên thần Angel Investor", "Quỹ đầu tư mạo hiểm Venture Capital", "Hợp đồng SAFE"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-khoi-nghiep-doi-moi-sang-tao-09', 'sub-biz-startup', 'Quản Lý Bảng Vốn Hóa (Cap Table) & Tránh Bị Pha Loãng Quá Mức', 'khoi-nghiep-doi-moi-sang-tao-9', 'Bài học ''Quản Lý Bảng Vốn Hóa (Cap Table) & Tránh Bị Pha Loãng Quá Mức'' thuộc môn Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Bảo vệ tỷ lệ sở hữu của nhà sáng lập Nội dung trọng tâm gồm việc hiểu rõ bản chất của Bảng sở hữu cổ phần, Cổ phiếu quyền chọn ESOP, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 9, 11, '["Bảng sở hữu cổ phần", "Cổ phiếu quyền chọn ESOP", "Pha loãng cổ phần Dilution", "Quyền biểu quyết"]'::jsonb, 'COMPLETED', 95, 'ses-top-khoi-nghiep-doi-moi-sang-tao-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-khoi-nghiep-doi-moi-sang-tao-10', 'sub-biz-startup', 'Xây Dựng Văn Hóa Khởi Nghiệp Đột Phá & Tốc Độ Thực Thi', 'khoi-nghiep-doi-moi-sang-tao-10', 'Bài học ''Xây Dựng Văn Hóa Khởi Nghiệp Đột Phá & Tốc Độ Thực Thi'' thuộc môn Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Vũ khí cạnh tranh lớn nhất của startup trước các tập đoàn Nội dung trọng tâm gồm việc hiểu rõ bản chất của Bias for Action, Thực thi tốc độ cao, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 10, 9, '["Bias for Action", "Thực thi tốc độ cao", "Thu hút đồng sáng lập Co-founder"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-khoi-nghiep-doi-moi-sang-tao-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-khoi-nghiep-doi-moi-sang-tao-11', 'sub-biz-startup', 'Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup) - Chuyên Đề Nâng Cao #1', 'khoi-nghiep-doi-moi-sang-tao-11', 'Bài học ''Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup) - Chuyên Đề Nâng Cao #1'' thuộc môn Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 11, 8, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NEEDS_REVIEW', 60, 'ses-top-khoi-nghiep-doi-moi-sang-tao-11');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-khoi-nghiep-doi-moi-sang-tao-12', 'sub-biz-startup', 'Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup) - Chuyên Đề Nâng Cao #2', 'khoi-nghiep-doi-moi-sang-tao-12', 'Bài học ''Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup) - Chuyên Đề Nâng Cao #2'' thuộc môn Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Khởi Sự Kinh Doanh & Đổi Mới Sáng Tạo (Startup). Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #2A, Kỹ thuật tối ưu #2B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 12, 7, '["Khái niệm nâng cao #2A", "Kỹ thuật tối ưu #2B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nghiep-vu-huong-dan-thiet-ke-tour-01', 'sub-tour-guiding', 'Quy Trình Nghiệp Vụ Hướng Dẫn Tour Du Lịch Toàn Diện', 'nghiep-vu-huong-dan-thiet-ke-tour-1', 'Bài học ''Quy Trình Nghiệp Vụ Hướng Dẫn Tour Du Lịch Toàn Diện'' thuộc môn Nghiệp Vụ Hướng Dẫn Viên & Thiết Kế Tour. Từ khâu chuẩn bị đến khi tiễn khách Nội dung trọng tâm gồm việc hiểu rõ bản chất của Nhận bàn giao tour, Kiểm tra dịch vụ nhà cung cấp, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 1, 13, '["Nhận bàn giao tour", "Kiểm tra dịch vụ nhà cung cấp", "Đón khách", "Tiễn khách"]'::jsonb, 'NEEDS_REVIEW', 60, 'ses-top-nghiep-vu-huong-dan-thiet-ke-tour-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nghiep-vu-huong-dan-thiet-ke-tour-02', 'sub-tour-guiding', 'Nghệ Thuật Thuyết Minh Du Lịch Trên Tuyến & Điểm', 'nghiep-vu-huong-dan-thiet-ke-tour-2', 'Bài học ''Nghệ Thuật Thuyết Minh Du Lịch Trên Tuyến & Điểm'' thuộc môn Nghiệp Vụ Hướng Dẫn Viên & Thiết Kế Tour. Truyền tải cảm xúc và kiến thức văn hóa Nội dung trọng tâm gồm việc hiểu rõ bản chất của Kỹ thuật kể chuyện Storytelling, Cấu trúc bài thuyết minh, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 2, 12, '["Kỹ thuật kể chuyện Storytelling", "Cấu trúc bài thuyết minh", "Tương tác với khách", "Sử dụng micro"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-nghiep-vu-huong-dan-thiet-ke-tour-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nghiep-vu-huong-dan-thiet-ke-tour-03', 'sub-tour-guiding', 'Quy Trình Thiết Kế Lịch Trình Tour Du Lịch (Tour Itinerary Planning)', 'nghiep-vu-huong-dan-thiet-ke-tour-3', 'Bài học ''Quy Trình Thiết Kế Lịch Trình Tour Du Lịch (Tour Itinerary Planning)'' thuộc môn Nghiệp Vụ Hướng Dẫn Viên & Thiết Kế Tour. Xây dựng hành trình hấp dẫn và khả thi Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khảo sát tuyến điểm, Khoảng cách và thời gian di chuyển, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 8, '["Khảo sát tuyến điểm", "Khoảng cách và thời gian di chuyển", "Phân bổ thời gian tham quan và nghỉ ngơi"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nghiep-vu-huong-dan-thiet-ke-tour-04', 'sub-tour-guiding', 'Phương Pháp Tính Giá Thành & Định Giá Bán Tour Du Lịch', 'nghiep-vu-huong-dan-thiet-ke-tour-4', 'Bài học ''Phương Pháp Tính Giá Thành & Định Giá Bán Tour Du Lịch'' thuộc môn Nghiệp Vụ Hướng Dẫn Viên & Thiết Kế Tour. Cân đối chi phí và lợi nhuận lữ hành Nội dung trọng tâm gồm việc hiểu rõ bản chất của Chi phí cố định xe cộ hướng dẫn, Chi phí biến đổi ăn ở vé tham quan, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 4, 7, '["Chi phí cố định xe cộ hướng dẫn", "Chi phí biến đổi ăn ở vé tham quan", "Tỷ lệ lợi nhuận kỳ vọng Mark-up"]'::jsonb, 'COMPLETED', 96, 'ses-top-nghiep-vu-huong-dan-thiet-ke-tour-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nghiep-vu-huong-dan-thiet-ke-tour-05', 'sub-tour-guiding', 'Xử Lý Tình Huống Khẩn Cấp & Khủng Hoảng Trong Chuyến Tour', 'nghiep-vu-huong-dan-thiet-ke-tour-5', 'Bài học ''Xử Lý Tình Huống Khẩn Cấp & Khủng Hoảng Trong Chuyến Tour'' thuộc môn Nghiệp Vụ Hướng Dẫn Viên & Thiết Kế Tour. Bảo đảm an toàn cao nhất cho du khách Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khách bị ốm đau tai nạn, Mất giấy tờ tùy thân hộ chiếu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 5, 13, '["Khách bị ốm đau tai nạn", "Mất giấy tờ tùy thân hộ chiếu", "Thiên tai thời tiết xấu", "Thất lạc hành lý"]'::jsonb, 'COMPLETED', 91, 'ses-top-nghiep-vu-huong-dan-thiet-ke-tour-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nghiep-vu-huong-dan-thiet-ke-tour-06', 'sub-tour-guiding', 'Kỹ Năng Hoạt Náo & Tổ Chức Trò Chơi Teambuilding Trên Xe / Bãi Biển', 'nghiep-vu-huong-dan-thiet-ke-tour-6', 'Bài học ''Kỹ Năng Hoạt Náo & Tổ Chức Trò Chơi Teambuilding Trên Xe / Bãi Biển'' thuộc môn Nghiệp Vụ Hướng Dẫn Viên & Thiết Kế Tour. Tạo bầu không khí vui vẻ gắn kết Nội dung trọng tâm gồm việc hiểu rõ bản chất của Trò chơi phá băng Ice-breaking, Quản trò hoạt náo, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 6, 13, '["Trò chơi phá băng Ice-breaking", "Quản trò hoạt náo", "An toàn trong trò chơi vận động"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nghiep-vu-huong-dan-thiet-ke-tour-07', 'sub-tour-guiding', 'Tâm Lý Học Khách Du Lịch Theo Thị Trường Mục Tiêu (Inbound & Outbound)', 'nghiep-vu-huong-dan-thiet-ke-tour-7', 'Bài học ''Tâm Lý Học Khách Du Lịch Theo Thị Trường Mục Tiêu (Inbound & Outbound)'' thuộc môn Nghiệp Vụ Hướng Dẫn Viên & Thiết Kế Tour. Phục vụ đúng gu văn hóa từng quốc tịch Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khách Âu - Mỹ, Khách Đông Bắc Á (Hàn, Nhật, Trung), vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 8, '["Khách Âu - Mỹ", "Khách Đông Bắc Á (Hàn, Nhật, Trung)", "Khách Đông Nam Á", "Khách nội địa"]'::jsonb, 'COMPLETED', 92, 'ses-top-nghiep-vu-huong-dan-thiet-ke-tour-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nghiep-vu-huong-dan-thiet-ke-tour-08', 'sub-tour-guiding', 'Quản Lý Quan Hệ Với Các Đối Tác Cung Ứng Lữ Hành (Vendors)', 'nghiep-vu-huong-dan-thiet-ke-tour-8', 'Bài học ''Quản Lý Quan Hệ Với Các Đối Tác Cung Ứng Lữ Hành (Vendors)'' thuộc môn Nghiệp Vụ Hướng Dẫn Viên & Thiết Kế Tour. Hợp tác win-win với chuỗi dịch vụ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Hợp đồng khách sạn, Đặt ăn nhà hàng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 8, 11, '["Hợp đồng khách sạn", "Đặt ăn nhà hàng", "Hãng vận chuyển xe du lịch", "Vé điểm tham quan"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-nghiep-vu-huong-dan-thiet-ke-tour-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nghiep-vu-huong-dan-thiet-ke-tour-09', 'sub-tour-guiding', 'Kỹ Năng Sơ Cứu Ban Đầu (First Aid) Cho Hướng Dẫn Viên', 'nghiep-vu-huong-dan-thiet-ke-tour-9', 'Bài học ''Kỹ Năng Sơ Cứu Ban Đầu (First Aid) Cho Hướng Dẫn Viên'' thuộc môn Nghiệp Vụ Hướng Dẫn Viên & Thiết Kế Tour. Kỹ năng sinh tồn cơ bản nơi hiện trường Nội dung trọng tâm gồm việc hiểu rõ bản chất của Sơ cứu say nắng sốc nhiệt, Băng bó vết thương gãy xương, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 9, 14, '["Sơ cứu say nắng sốc nhiệt", "Băng bó vết thương gãy xương", "Hô hấp nhân tạo CPR", "Xử lý ngộ độc thức ăn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-nghiep-vu-huong-dan-thiet-ke-tour-10', 'sub-tour-guiding', 'Đạo Đức Nghề Nghiệp & Trách Nhiệm Bảo Vệ Môi Trường Của Hướng Dẫn Viên', 'nghiep-vu-huong-dan-thiet-ke-tour-10', 'Bài học ''Đạo Đức Nghề Nghiệp & Trách Nhiệm Bảo Vệ Môi Trường Của Hướng Dẫn Viên'' thuộc môn Nghiệp Vụ Hướng Dẫn Viên & Thiết Kế Tour. Du lịch có trách nhiệm và bền vững Nội dung trọng tâm gồm việc hiểu rõ bản chất của Nói không với mua sắm ép buộc, Tôn trọng văn hóa bản địa, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 10, 7, '["Nói không với mua sắm ép buộc", "Tôn trọng văn hóa bản địa", "Bảo vệ môi trường sinh thái Không rác thải"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-khach-san-resort-01', 'sub-tour-hotel', 'Cơ Cấu Tổ Chức & Quy Trình Vận Hành Tiêu Chuẩn Của Khách Sạn Quốc Tế', 'quan-tri-khach-san-resort-1', 'Bài học ''Cơ Cấu Tổ Chức & Quy Trình Vận Hành Tiêu Chuẩn Của Khách Sạn Quốc Tế'' thuộc môn Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality). Bộ máy hoạt động của ngành khách sạn Nội dung trọng tâm gồm việc hiểu rõ bản chất của Sơ đồ tổ chức các bộ phận, Tiêu chuẩn sao khách sạn, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 1, 7, '["Sơ đồ tổ chức các bộ phận", "Tiêu chuẩn sao khách sạn", "SOP Standard Operating Procedures"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-khach-san-resort-02', 'sub-tour-hotel', 'Nghiệp Vụ Bộ Phận Tiền Sảnh (Front Office Operations)', 'quan-tri-khach-san-resort-2', 'Bài học ''Nghiệp Vụ Bộ Phận Tiền Sảnh (Front Office Operations)'' thuộc môn Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality). Bộ mặt đại diện của khách sạn Nội dung trọng tâm gồm việc hiểu rõ bản chất của Quy trình Check-in, Quy trình Check-out, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 2, 9, '["Quy trình Check-in", "Quy trình Check-out", "Quản lý đặt phòng Reservation", "Dịch vụ Concierge"]'::jsonb, 'COMPLETED', 87, 'ses-top-quan-tri-khach-san-resort-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-khach-san-resort-03', 'sub-tour-hotel', 'Hệ Thống Quản Lý Khách Sạn (Property Management System - PMS)', 'quan-tri-khach-san-resort-3', 'Bài học ''Hệ Thống Quản Lý Khách Sạn (Property Management System - PMS)'' thuộc môn Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality). Ứng dụng công nghệ trong vận hành lưu trú Nội dung trọng tâm gồm việc hiểu rõ bản chất của Phần mềm Opera PMS, Quản lý tình trạng phòng Room Status, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 7, '["Phần mềm Opera PMS", "Quản lý tình trạng phòng Room Status", "Quản lý hồ sơ khách Guest Profile"]'::jsonb, 'COMPLETED', 85, 'ses-top-quan-tri-khach-san-resort-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-khach-san-resort-04', 'sub-tour-hotel', 'Nghiệp Vụ Bộ Phận Buồng Phòng (Housekeeping Management)', 'quan-tri-khach-san-resort-4', 'Bài học ''Nghiệp Vụ Bộ Phận Buồng Phòng (Housekeeping Management)'' thuộc môn Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality). Đảm bảo vệ sinh và tiện nghi phòng nghỉ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Quy trình dọn phòng chuẩn, Kiểm tra phòng Inspection, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 4, 9, '["Quy trình dọn phòng chuẩn", "Kiểm tra phòng Inspection", "Quản lý đồ vải Linen", "Quy trình Lost & Found"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-khach-san-resort-05', 'sub-tour-hotel', 'Quản Trị Bộ Phận Ẩm Thực Khách Sạn (Food & Beverage - F&B)', 'quan-tri-khach-san-resort-5', 'Bài học ''Quản Trị Bộ Phận Ẩm Thực Khách Sạn (Food & Beverage - F&B)'' thuộc môn Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality). Vận hành nhà hàng và quầy bar trong khách sạn Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tiệc Buffet sáng, Dịch vụ Room Service, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 5, 10, '["Tiệc Buffet sáng", "Dịch vụ Room Service", "Tổ chức tiệc Banquet", "Quản lý chi phí F&B Cost"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-quan-tri-khach-san-resort-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-khach-san-resort-06', 'sub-tour-hotel', 'Quản Trị Doanh Thu Khách Sạn (Hotel Revenue Management)', 'quan-tri-khach-san-resort-6', 'Bài học ''Quản Trị Doanh Thu Khách Sạn (Hotel Revenue Management)'' thuộc môn Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality). Tối ưu hóa doanh thu từng đêm phòng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tỷ lệ lấp đầy Occupancy Rate (OCC), Giá bán trung bình ADR, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 6, 8, '["Tỷ lệ lấp đầy Occupancy Rate (OCC)", "Giá bán trung bình ADR", "Doanh thu trên mỗi phòng sẵn có RevPAR"]'::jsonb, 'NEEDS_REVIEW', 59, 'ses-top-quan-tri-khach-san-resort-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-khach-san-resort-07', 'sub-tour-hotel', 'Chiến Lược Phân Phối Phòng Qua Các Kênh Trực Tuyến (OTA Channel Management)', 'quan-tri-khach-san-resort-7', 'Bài học ''Chiến Lược Phân Phối Phòng Qua Các Kênh Trực Tuyến (OTA Channel Management)'' thuộc môn Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality). Bán phòng hiệu quả trên mạng toàn cầu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Booking.com / Agoda, Hệ thống quản lý kênh Channel Manager, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 7, '["Booking.com / Agoda", "Hệ thống quản lý kênh Channel Manager", "Bán phòng trực tiếp qua Website"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-khach-san-resort-08', 'sub-tour-hotel', 'Quản Trị An Ninh & An Toàn Trong Khách Sạn / Resort', 'quan-tri-khach-san-resort-8', 'Bài học ''Quản Trị An Ninh & An Toàn Trong Khách Sạn / Resort'' thuộc môn Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality). Bảo vệ tính mạng và tài sản của du khách Nội dung trọng tâm gồm việc hiểu rõ bản chất của Phòng cháy chữa cháy PCCC, Hệ thống camera an ninh, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 8, 8, '["Phòng cháy chữa cháy PCCC", "Hệ thống camera an ninh", "Xử lý khách say xỉn quấy rối", "Bảo mật két sắt"]'::jsonb, 'COMPLETED', 98, 'ses-top-quan-tri-khach-san-resort-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-khach-san-resort-09', 'sub-tour-hotel', 'Mô Hình Quản Trị Khu Nghỉ Dưỡng Sinh Thái & Wellness Resort', 'quan-tri-khach-san-resort-9', 'Bài học ''Mô Hình Quản Trị Khu Nghỉ Dưỡng Sinh Thái & Wellness Resort'' thuộc môn Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality). Kinh doanh dịch vụ nghỉ dưỡng cao cấp Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thiết kế cảnh quan sinh thái, Dịch vụ Spa & Trị liệu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 9, 13, '["Thiết kế cảnh quan sinh thái", "Dịch vụ Spa & Trị liệu", "Hoạt động trải nghiệm nội khu"]'::jsonb, 'NEEDS_REVIEW', 60, 'ses-top-quan-tri-khach-san-resort-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-khach-san-resort-10', 'sub-tour-hotel', 'Quản Trị Chất Lượng Dịch Vụ Khách Sạn & Đào Tạo Nhân Viên', 'quan-tri-khach-san-resort-10', 'Bài học ''Quản Trị Chất Lượng Dịch Vụ Khách Sạn & Đào Tạo Nhân Viên'' thuộc môn Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality). Duy trì tiêu chuẩn dịch vụ 5 sao Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tiêu chuẩn phục vụ tận tâm, Đánh giá chất lượng dịch vụ bí mật Mystery Shopper, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 10, 12, '["Tiêu chuẩn phục vụ tận tâm", "Đánh giá chất lượng dịch vụ bí mật Mystery Shopper", "Giải quyết khiếu nại khách hàng"]'::jsonb, 'COMPLETED', 84, 'ses-top-quan-tri-khach-san-resort-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-quan-tri-khach-san-resort-11', 'sub-tour-hotel', 'Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality) - Chuyên Đề Nâng Cao #1', 'quan-tri-khach-san-resort-11', 'Bài học ''Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality) - Chuyên Đề Nâng Cao #1'' thuộc môn Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality). Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Quản Trị Khách Sạn & Khu Nghỉ Dưỡng (Hospitality). Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 11, 14, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dia-ly-du-lich-tai-nguyen-van-hoa-01', 'sub-tour-geography', 'Tổng Quan Phân Vùng Du Lịch Việt Nam: 7 Vùng Du Lịch Trọng Điểm', 'dia-ly-du-lich-tai-nguyen-van-hoa-1', 'Bài học ''Tổng Quan Phân Vùng Du Lịch Việt Nam: 7 Vùng Du Lịch Trọng Điểm'' thuộc môn Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Bức tranh toàn cảnh tài nguyên du lịch đất nước Nội dung trọng tâm gồm việc hiểu rõ bản chất của Vùng Trung du và miền núi Bắc Bộ, Đồng bằng sông Hồng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 1, 8, '["Vùng Trung du và miền núi Bắc Bộ", "Đồng bằng sông Hồng", "Bắc Trung Bộ", "Duyên hải Nam Trung Bộ", "Tây Nguyên", "Đông Nam Bộ", "Đồng bằng sông Cửu Long"]'::jsonb, 'COMPLETED', 97, 'ses-top-dia-ly-du-lich-tai-nguyen-van-hoa-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dia-ly-du-lich-tai-nguyen-van-hoa-02', 'sub-tour-geography', 'Tài Nguyên Du Lịch Tự Nhiên: Địa Hình, Hang Động & Vườn Quốc Gia', 'dia-ly-du-lich-tai-nguyen-van-hoa-2', 'Bài học ''Tài Nguyên Du Lịch Tự Nhiên: Địa Hình, Hang Động & Vườn Quốc Gia'' thuộc môn Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Khai thác thế mạnh thiên nhiên Nội dung trọng tâm gồm việc hiểu rõ bản chất của Vịnh Hạ Long, Quần thể hang động Phong Nha - Kẻ Bàng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 2, 13, '["Vịnh Hạ Long", "Quần thể hang động Phong Nha - Kẻ Bàng", "Cao nguyên đá Đồng Văn", "Vườn quốc gia Cát Tiên"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-dia-ly-du-lich-tai-nguyen-van-hoa-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dia-ly-du-lich-tai-nguyen-van-hoa-03', 'sub-tour-geography', 'Tài Nguyên Du Lịch Biển Đảo: Tiềm Năng & Các Tuyến Điểm Nổi Bật', 'dia-ly-du-lich-tai-nguyen-van-hoa-3', 'Bài học ''Tài Nguyên Du Lịch Biển Đảo: Tiềm Năng & Các Tuyến Điểm Nổi Bật'' thuộc môn Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Thế mạnh biển đảo Việt Nam Nội dung trọng tâm gồm việc hiểu rõ bản chất của Phú Quốc, Nha Trang, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 3, 11, '["Phú Quốc", "Nha Trang", "Đà Nẵng", "Côn Đảo", "Quy Nhơn"]'::jsonb, 'COMPLETED', 97, 'ses-top-dia-ly-du-lich-tai-nguyen-van-hoa-03');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dia-ly-du-lich-tai-nguyen-van-hoa-04', 'sub-tour-geography', 'Hệ Thống Di Sản Thế Giới UNESCO Tại Việt Nam', 'dia-ly-du-lich-tai-nguyen-van-hoa-4', 'Bài học ''Hệ Thống Di Sản Thế Giới UNESCO Tại Việt Nam'' thuộc môn Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Các báu vật văn hóa và thiên nhiên toàn cầu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Quần thể di tích Cố đô Huế, Phố cổ Hội An, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 4, 12, '["Quần thể di tích Cố đô Huế", "Phố cổ Hội An", "Thánh địa Mỹ Sơn", "Hoàng thành Thăng Long", "Tràng An"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-dia-ly-du-lich-tai-nguyen-van-hoa-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dia-ly-du-lich-tai-nguyen-van-hoa-05', 'sub-tour-geography', 'Di Sản Văn Hóa Phi Vật Thể Đại Diện Của Nhân Loại', 'dia-ly-du-lich-tai-nguyen-van-hoa-5', 'Bài học ''Di Sản Văn Hóa Phi Vật Thể Đại Diện Của Nhân Loại'' thuộc môn Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Bảo tồn bản sắc văn hóa dân tộc Nội dung trọng tâm gồm việc hiểu rõ bản chất của Nhã nhạc cung đình Huế, Không gian văn hóa Cồng chiêng Tây Nguyên, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 5, 8, '["Nhã nhạc cung đình Huế", "Không gian văn hóa Cồng chiêng Tây Nguyên", "Dân ca Quan họ Bắc Ninh", "Đờn ca tài tử Nam Bộ"]'::jsonb, 'COMPLETED', 94, 'ses-top-dia-ly-du-lich-tai-nguyen-van-hoa-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dia-ly-du-lich-tai-nguyen-van-hoa-06', 'sub-tour-geography', 'Văn Hóa Lễ Hội Truyền Thống & Ứng Dụng Trong Khai Thác Du Lịch', 'dia-ly-du-lich-tai-nguyen-van-hoa-6', 'Bài học ''Văn Hóa Lễ Hội Truyền Thống & Ứng Dụng Trong Khai Thác Du Lịch'' thuộc môn Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Sức hút của các lễ hội dân gian Nội dung trọng tâm gồm việc hiểu rõ bản chất của Lễ hội Đền Hùng, Lễ hội Chùa Hương, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 6, 12, '["Lễ hội Đền Hùng", "Lễ hội Chùa Hương", "Lễ hội Katê của người Chăm", "Lễ hội Oóc Om Bóc"]'::jsonb, 'NEEDS_REVIEW', 59, 'ses-top-dia-ly-du-lich-tai-nguyen-van-hoa-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dia-ly-du-lich-tai-nguyen-van-hoa-07', 'sub-tour-geography', 'Bản Sắc Văn Hóa & Phong Tục Tập Quán Các Dân Tộc Thiểu Số', 'dia-ly-du-lich-tai-nguyen-van-hoa-7', 'Bài học ''Bản Sắc Văn Hóa & Phong Tục Tập Quán Các Dân Tộc Thiểu Số'' thuộc môn Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Du lịch cộng đồng và trải nghiệm văn hóa Nội dung trọng tâm gồm việc hiểu rõ bản chất của Văn hóa người H''Mông, Dao, Tày, Văn hóa người Thái, Mường, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 7, 9, '["Văn hóa người H''Mông, Dao, Tày", "Văn hóa người Thái, Mường", "Văn hóa mẫu hệ người Ê Đê, Ba Na"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dia-ly-du-lich-tai-nguyen-van-hoa-08', 'sub-tour-geography', 'Văn Hóa Ẩm Thực 3 Miền Việt Nam & Tiềm Năng Du Lịch Ẩm Thực (Culinary Tourism)', 'dia-ly-du-lich-tai-nguyen-van-hoa-8', 'Bài học ''Văn Hóa Ẩm Thực 3 Miền Việt Nam & Tiềm Năng Du Lịch Ẩm Thực (Culinary Tourism)'' thuộc môn Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Hành trình khám phá hương vị Việt Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tinh hoa ẩm thực đất Bắc, Đậm đà hương vị miền Trung, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 10, '["Tinh hoa ẩm thực đất Bắc", "Đậm đà hương vị miền Trung", "Phóng khoáng ẩm thực Nam Bộ", "Văn hóa cà phê Việt"]'::jsonb, 'COMPLETED', 88, 'ses-top-dia-ly-du-lich-tai-nguyen-van-hoa-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dia-ly-du-lich-tai-nguyen-van-hoa-09', 'sub-tour-geography', 'Phát Triển Du Lịch Sinh Thái Bền Vững & Bảo Tồn Đa Dạng Sinh Học', 'dia-ly-du-lich-tai-nguyen-van-hoa-9', 'Bài học ''Phát Triển Du Lịch Sinh Thái Bền Vững & Bảo Tồn Đa Dạng Sinh Học'' thuộc môn Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Du lịch gắn liền với trách nhiệm môi trường Nội dung trọng tâm gồm việc hiểu rõ bản chất của Nguyên tắc du lịch sinh thái, Cân bằng giữa khai thác và bảo tồn, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 9, 8, '["Nguyên tắc du lịch sinh thái", "Cân bằng giữa khai thác và bảo tồn", "Giáo dục ý thức du khách"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dia-ly-du-lich-tai-nguyen-van-hoa-10', 'sub-tour-geography', 'Du Lịch Nông Nghiệp & Mô Hình OCOP Gắn Với Nông Thôn Mới', 'dia-ly-du-lich-tai-nguyen-van-hoa-10', 'Bài học ''Du Lịch Nông Nghiệp & Mô Hình OCOP Gắn Với Nông Thôn Mới'' thuộc môn Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Trải nghiệm đồng quê và sản vật địa phương Nội dung trọng tâm gồm việc hiểu rõ bản chất của Miệt vườn sông nước miền Tây, Làng rau Trà Quế, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 14, '["Miệt vườn sông nước miền Tây", "Làng rau Trà Quế", "Farmstay nghỉ dưỡng nông nghiệp"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dia-ly-du-lich-tai-nguyen-van-hoa-11', 'sub-tour-geography', 'Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản - Chuyên Đề Nâng Cao #1', 'dia-ly-du-lich-tai-nguyen-van-hoa-11', 'Bài học ''Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản - Chuyên Đề Nâng Cao #1'' thuộc môn Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 11, 14, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
