INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-dia-ly-du-lich-tai-nguyen-van-hoa-15', 'sub-tour-geography', 'Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản - Chuyên Đề Nâng Cao #5', 'dia-ly-du-lich-tai-nguyen-van-hoa-15', 'Bài học ''Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản - Chuyên Đề Nâng Cao #5'' thuộc môn Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Địa Lý Du Lịch & Tài Nguyên Văn Hóa Di Sản. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #5A, Kỹ thuật tối ưu #5B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 15, 15, '["Khái niệm nâng cao #5A", "Kỹ thuật tối ưu #5B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NEEDS_REVIEW', 59, 'ses-top-dia-ly-du-lich-tai-nguyen-van-hoa-15');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-giai-phau-hoc-nguoi-anatomy-01', 'sub-med-anatomy', 'Thuật Ngữ Định Hướng Không Gian Trong Giải Phẫu Học', 'giai-phau-hoc-nguoi-anatomy-1', 'Bài học ''Thuật Ngữ Định Hướng Không Gian Trong Giải Phẫu Học'' thuộc môn Giải Phẫu Học Người (Human Anatomy). Ngôn ngữ mô tả vị trí chuẩn quốc tế Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tư thế giải phẫu chuẩn, Mặt phẳng đứng dọc Sagittal, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 1, 7, '["Tư thế giải phẫu chuẩn", "Mặt phẳng đứng dọc Sagittal", "Mặt phẳng ngang Transverse", "Gần/Xa, Trước/Sau, Nông/Sâu"]'::jsonb, 'NEEDS_REVIEW', 49, 'ses-top-giai-phau-hoc-nguoi-anatomy-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-giai-phau-hoc-nguoi-anatomy-02', 'sub-med-anatomy', 'Giải Phẫu Hệ Xương Khớp: Cấu Trúc Khung Xương Người', 'giai-phau-hoc-nguoi-anatomy-2', 'Bài học ''Giải Phẫu Hệ Xương Khớp: Cấu Trúc Khung Xương Người'' thuộc môn Giải Phẫu Học Người (Human Anatomy). Bộ khung nâng đỡ cơ thể Nội dung trọng tâm gồm việc hiểu rõ bản chất của Xương sọ, Cột sống và lồng ngực, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 2, 8, '["Xương sọ", "Cột sống và lồng ngực", "Xương chi trên và chi dưới", "Các loại khớp động, bán động, bất động"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-giai-phau-hoc-nguoi-anatomy-03', 'sub-med-anatomy', 'Giải Phẫu Hệ Cơ: Các Nhóm Cơ Vận Động Chính', 'giai-phau-hoc-nguoi-anatomy-3', 'Bài học ''Giải Phẫu Hệ Cơ: Các Nhóm Cơ Vận Động Chính'' thuộc môn Giải Phẫu Học Người (Human Anatomy). Hệ thống tạo lực chuyển động Nội dung trọng tâm gồm việc hiểu rõ bản chất của Cơ vân, Nguyên ủy và bám tận, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 3, 8, '["Cơ vân", "Nguyên ủy và bám tận", "Cơ vùng đầu mặt cổ", "Cơ thân mình và cơ tứ chi"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-giai-phau-hoc-nguoi-anatomy-04', 'sub-med-anatomy', 'Giải Phẫu Hệ Tim Mạch: Cấu Trúc Tim & Các Mạch Máu Lớn', 'giai-phau-hoc-nguoi-anatomy-4', 'Bài học ''Giải Phẫu Hệ Tim Mạch: Cấu Trúc Tim & Các Mạch Máu Lớn'' thuộc môn Giải Phẫu Học Người (Human Anatomy). Bơm tuần hoàn của cơ thể Nội dung trọng tâm gồm việc hiểu rõ bản chất của 4 ngăn tim, Hệ thống van tim, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 4, 14, '["4 ngăn tim", "Hệ thống van tim", "Động mạch chủ và tĩnh mạch chủ", "Động mạch vành nuôi tim"]'::jsonb, 'NEEDS_REVIEW', 60, 'ses-top-giai-phau-hoc-nguoi-anatomy-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-giai-phau-hoc-nguoi-anatomy-05', 'sub-med-anatomy', 'Giải Phẫu Hệ Hô Hấp: Từ Đường Dẫn Khí Đến Phế Nang Phổi', 'giai-phau-hoc-nguoi-anatomy-5', 'Bài học ''Giải Phẫu Hệ Hô Hấp: Từ Đường Dẫn Khí Đến Phế Nang Phổi'' thuộc môn Giải Phẫu Học Người (Human Anatomy). Đường trao đổi dưỡng khí Nội dung trọng tâm gồm việc hiểu rõ bản chất của Mũi và thanh quản, Khí quản và phế quản, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 5, 14, '["Mũi và thanh quản", "Khí quản và phế quản", "Cây phế quản", "Cấu trúc thùy phổi và màng phổi"]'::jsonb, 'NEEDS_REVIEW', 49, 'ses-top-giai-phau-hoc-nguoi-anatomy-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-giai-phau-hoc-nguoi-anatomy-06', 'sub-med-anatomy', 'Giải Phẫu Hệ Tiêu Hóa: Ống Tiêu Hóa & Các Tuyến Phụ Thuộc', 'giai-phau-hoc-nguoi-anatomy-6', 'Bài học ''Giải Phẫu Hệ Tiêu Hóa: Ống Tiêu Hóa & Các Tuyến Phụ Thuộc'' thuộc môn Giải Phẫu Học Người (Human Anatomy). Hệ thống xử lý và hấp thu dinh dưỡng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thực quản và dạ dày, Ruột non và ruột già, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 6, 12, '["Thực quản và dạ dày", "Ruột non và ruột già", "Giải phẫu gan và túi mật", "Tụy tạng"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-giai-phau-hoc-nguoi-anatomy-07', 'sub-med-anatomy', 'Giải Phẫu Hệ Tiết Niệu: Thận, Niệu Quản & Bàng Quang', 'giai-phau-hoc-nguoi-anatomy-7', 'Bài học ''Giải Phẫu Hệ Tiết Niệu: Thận, Niệu Quản & Bàng Quang'' thuộc môn Giải Phẫu Học Người (Human Anatomy). Hệ thống thanh lọc và bài tiết Nội dung trọng tâm gồm việc hiểu rõ bản chất của Vỏ và tủy thận, Đơn vị Nephron, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 7, 7, '["Vỏ và tủy thận", "Đơn vị Nephron", "Đài bể thận", "Niệu quản và niệu đạo"]'::jsonb, 'NEEDS_REVIEW', 52, 'ses-top-giai-phau-hoc-nguoi-anatomy-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-giai-phau-hoc-nguoi-anatomy-08', 'sub-med-anatomy', 'Giải Phẫu Hệ Thần Kinh Trung Ương: Não Bộ & Tủy Sống', 'giai-phau-hoc-nguoi-anatomy-8', 'Bài học ''Giải Phẫu Hệ Thần Kinh Trung Ương: Não Bộ & Tủy Sống'' thuộc môn Giải Phẫu Học Người (Human Anatomy). Trung tâm điều khiển cơ thể Nội dung trọng tâm gồm việc hiểu rõ bản chất của Bán cầu đại não, Tiểu não và thân não, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 8, 12, '["Bán cầu đại não", "Tiểu não và thân não", "Tủy sống", "Hệ thống não thất và màng não"]'::jsonb, 'COMPLETED', 98, 'ses-top-giai-phau-hoc-nguoi-anatomy-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-giai-phau-hoc-nguoi-anatomy-09', 'sub-med-anatomy', 'Giải Phẫu Hệ Thần Kinh Ngoại Biên & 12 Đôi Dây Thần Kinh Sọ', 'giai-phau-hoc-nguoi-anatomy-9', 'Bài học ''Giải Phẫu Hệ Thần Kinh Ngoại Biên & 12 Đôi Dây Thần Kinh Sọ'' thuộc môn Giải Phẫu Học Người (Human Anatomy). Mạng lưới truyền dẫn tín hiệu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Dây thần kinh sọ I-XII, Đám rối thần kinh cánh tay, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 9, 9, '["Dây thần kinh sọ I-XII", "Đám rối thần kinh cánh tay", "Dây thần kinh tọa", "Hệ thần kinh tự chủ giao cảm/đối giao cảm"]'::jsonb, 'COMPLETED', 94, 'ses-top-giai-phau-hoc-nguoi-anatomy-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-giai-phau-hoc-nguoi-anatomy-10', 'sub-med-anatomy', 'Giải Phẫu Hệ Nội Tiết: Tuyến Yên, Tuyến Giáp & Tuyến Thượng Thận', 'giai-phau-hoc-nguoi-anatomy-10', 'Bài học ''Giải Phẫu Hệ Nội Tiết: Tuyến Yên, Tuyến Giáp & Tuyến Thượng Thận'' thuộc môn Giải Phẫu Học Người (Human Anatomy). Hệ thống điều hòa bằng hormone Nội dung trọng tâm gồm việc hiểu rõ bản chất của Trục hạ đồi - tuyến yên, Tuyến giáp và cận giáp, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 14, '["Trục hạ đồi - tuyến yên", "Tuyến giáp và cận giáp", "Tuyến thượng thận", "Đảo tụy Langerhans"]'::jsonb, 'COMPLETED', 91, 'ses-top-giai-phau-hoc-nguoi-anatomy-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-sinh-ly-hoc-y-khoa-01', 'sub-med-physiology', 'Cơ Chế Cân Bằng Nội Môi (Homeostasis) & Cơ Chế Phản Hồi Âm Tính', 'sinh-ly-hoc-y-khoa-1', 'Bài học ''Cơ Chế Cân Bằng Nội Môi (Homeostasis) & Cơ Chế Phản Hồi Âm Tính'' thuộc môn Sinh Lý Học Y Khoa (Medical Physiology). Quy luật duy trì sự sống Nội dung trọng tâm gồm việc hiểu rõ bản chất của Dịch nội bào và ngoại bào, Phản hồi âm tính Negative Feedback, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 1, 12, '["Dịch nội bào và ngoại bào", "Phản hồi âm tính Negative Feedback", "Phản hồi dương tính", "Điểm đặt Set Point"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-sinh-ly-hoc-y-khoa-02', 'sub-med-physiology', 'Điện Thế Màng Tế Bào & Điện Thế Hoạt Động (Action Potential)', 'sinh-ly-hoc-y-khoa-2', 'Bài học ''Điện Thế Màng Tế Bào & Điện Thế Hoạt Động (Action Potential)'' thuộc môn Sinh Lý Học Y Khoa (Medical Physiology). Tín hiệu điện sinh học của tế bào Nội dung trọng tâm gồm việc hiểu rõ bản chất của Bơm Na+/K+-ATPase, Điện thế nghỉ Resting Potential, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 2, 13, '["Bơm Na+/K+-ATPase", "Điện thế nghỉ Resting Potential", "Khử cực và tái cực", "Kênh ion cổng điện thế"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-sinh-ly-hoc-y-khoa-03', 'sub-med-physiology', 'Sinh Lý Co Cơ: Cơ Chế Trượt Sợi Myosin & Actin', 'sinh-ly-hoc-y-khoa-3', 'Bài học ''Sinh Lý Co Cơ: Cơ Chế Trượt Sợi Myosin & Actin'' thuộc môn Sinh Lý Học Y Khoa (Medical Physiology). Cách thức cơ bắp sinh công Nội dung trọng tâm gồm việc hiểu rõ bản chất của Cầu nối chéo Cross-bridge, Vai trò của ion Canxi, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 3, 7, '["Cầu nối chéo Cross-bridge", "Vai trò của ion Canxi", "Phức hợp Troponin-Tropomyosin", "Năng lượng ATP"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-sinh-ly-hoc-y-khoa-04', 'sub-med-physiology', 'Sinh Lý Tuần Hoàn: Chu Kỳ Tim & Cơ Chế Điều Hòa Huyết Áp', 'sinh-ly-hoc-y-khoa-4', 'Bài học ''Sinh Lý Tuần Hoàn: Chu Kỳ Tim & Cơ Chế Điều Hòa Huyết Áp'' thuộc môn Sinh Lý Học Y Khoa (Medical Physiology). Dòng chảy của sự sống Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thời kỳ tâm thu và tâm trương, Cung lượng tim Cardiac Output, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 4, 8, '["Thời kỳ tâm thu và tâm trương", "Cung lượng tim Cardiac Output", "Thụ thể áp lực Baroreceptors", "Hệ RAA điều hòa huyết áp"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-sinh-ly-hoc-y-khoa-05', 'sub-med-physiology', 'Sinh Lý Hô Hấp: Cơ Học Thở & Sự Trao Đổi Khí Tại Phổi', 'sinh-ly-hoc-y-khoa-5', 'Bài học ''Sinh Lý Hô Hấp: Cơ Học Thở & Sự Trao Đổi Khí Tại Phổi'' thuộc môn Sinh Lý Học Y Khoa (Medical Physiology). Quá trình lấy oxy và thải CO2 Nội dung trọng tâm gồm việc hiểu rõ bản chất của Áp suất âm khoang màng phổi, Cơ hoành, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 5, 13, '["Áp suất âm khoang màng phổi", "Cơ hoành", "Khuếch tán khí qua màng phế nang - mao mạch", "Đường cong phân ly Oxy-Hemoglobin"]'::jsonb, 'COMPLETED', 94, 'ses-top-sinh-ly-hoc-y-khoa-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-sinh-ly-hoc-y-khoa-06', 'sub-med-physiology', 'Sinh Lý Thận: Cơ Chế Lọc Cầu Thận & Tái Hấp Thu Ống Thận', 'sinh-ly-hoc-y-khoa-6', 'Bài học ''Sinh Lý Thận: Cơ Chế Lọc Cầu Thận & Tái Hấp Thu Ống Thận'' thuộc môn Sinh Lý Học Y Khoa (Medical Physiology). Thanh lọc máu và cân bằng dịch Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tốc độ lọc cầu thận GFR, Tái hấp thu tại ống lượn gần, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 6, 9, '["Tốc độ lọc cầu thận GFR", "Tái hấp thu tại ống lượn gần", "Quai Henle và nhân nồng độ ngược dòng", "Tác dụng của hormone ADH và Aldosterone"]'::jsonb, 'COMPLETED', 97, 'ses-top-sinh-ly-hoc-y-khoa-06');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-sinh-ly-hoc-y-khoa-07', 'sub-med-physiology', 'Sinh Lý Tiêu Hóa: Tiết Dịch, Tiêu Hóa Hóa Học & Hấp Thu', 'sinh-ly-hoc-y-khoa-7', 'Bài học ''Sinh Lý Tiêu Hóa: Tiết Dịch, Tiêu Hóa Hóa Học & Hấp Thu'' thuộc môn Sinh Lý Học Y Khoa (Medical Physiology). Phân giải thức ăn thành dưỡng chất Nội dung trọng tâm gồm việc hiểu rõ bản chất của Acid dịch vị HCl và Pepsin, Dịch tụy và mật, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 7, 9, '["Acid dịch vị HCl và Pepsin", "Dịch tụy và mật", "Hấp thu glucose và acid amin", "Nhu động ruột Peristalsis"]'::jsonb, 'COMPLETED', 94, 'ses-top-sinh-ly-hoc-y-khoa-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-sinh-ly-hoc-y-khoa-08', 'sub-med-physiology', 'Sinh Lý Nội Tiết: Điều Hòa Chuyển Hóa Đường Của Insulin & Glucagon', 'sinh-ly-hoc-y-khoa-8', 'Bài học ''Sinh Lý Nội Tiết: Điều Hòa Chuyển Hóa Đường Của Insulin & Glucagon'' thuộc môn Sinh Lý Học Y Khoa (Medical Physiology). Kiểm soát đường huyết cơ thể Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tế bào beta tụy, Cơ chế tác dụng của Insulin, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 8, 13, '["Tế bào beta tụy", "Cơ chế tác dụng của Insulin", "Tế bào alpha và Glucagon", "Bệnh đái tháo đường"]'::jsonb, 'COMPLETED', 94, 'ses-top-sinh-ly-hoc-y-khoa-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-sinh-ly-hoc-y-khoa-09', 'sub-med-physiology', 'Sinh Lý Máu & Cơ Chế Đông Cầm Máu Tự Nhiên (Hemostasis)', 'sinh-ly-hoc-y-khoa-9', 'Bài học ''Sinh Lý Máu & Cơ Chế Đông Cầm Máu Tự Nhiên (Hemostasis)'' thuộc môn Sinh Lý Học Y Khoa (Medical Physiology). Bảo vệ thể tích tuần hoàn Nội dung trọng tâm gồm việc hiểu rõ bản chất của Các dòng tế bào máu, Giai đoạn co mạch, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 9, 11, '["Các dòng tế bào máu", "Giai đoạn co mạch", "Nút tiểu cầu", "Con đường đông máu nội sinh và ngoại sinh"]'::jsonb, 'NEEDS_REVIEW', 50, 'ses-top-sinh-ly-hoc-y-khoa-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-sinh-ly-hoc-y-khoa-10', 'sub-med-physiology', 'Sinh Lý Thần Kinh: Dẫn Truyền Qua Synapse & Chất Dẫn Truyền Thần Kinh', 'sinh-ly-hoc-y-khoa-10', 'Bài học ''Sinh Lý Thần Kinh: Dẫn Truyền Qua Synapse & Chất Dẫn Truyền Thần Kinh'' thuộc môn Sinh Lý Học Y Khoa (Medical Physiology). Liên lạc giữa các tế bào não Nội dung trọng tâm gồm việc hiểu rõ bản chất của Synapse hóa học, Chất dẫn truyền Acetylcholine, Dopamine, Serotonin, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 10, 12, '["Synapse hóa học", "Chất dẫn truyền Acetylcholine, Dopamine, Serotonin", "Tái hấp thu Reuptake", "Điện thế sau synapse"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-sinh-ly-hoc-y-khoa-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-sinh-ly-hoc-y-khoa-11', 'sub-med-physiology', 'Sinh Lý Học Y Khoa (Medical Physiology) - Chuyên Đề Nâng Cao #1', 'sinh-ly-hoc-y-khoa-11', 'Bài học ''Sinh Lý Học Y Khoa (Medical Physiology) - Chuyên Đề Nâng Cao #1'' thuộc môn Sinh Lý Học Y Khoa (Medical Physiology). Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Sinh Lý Học Y Khoa (Medical Physiology). Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 11, 15, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
