INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-sinh-ly-hoc-y-khoa-14', 'sub-med-physiology', 'Sinh Lý Học Y Khoa (Medical Physiology) - Chuyên Đề Nâng Cao #4', 'sinh-ly-hoc-y-khoa-14', 'Bài học ''Sinh Lý Học Y Khoa (Medical Physiology) - Chuyên Đề Nâng Cao #4'' thuộc môn Sinh Lý Học Y Khoa (Medical Physiology). Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Sinh Lý Học Y Khoa (Medical Physiology). Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #4A, Kỹ thuật tối ưu #4B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 14, 12, '["Khái niệm nâng cao #4A", "Kỹ thuật tối ưu #4B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'COMPLETED', 87, 'ses-top-sinh-ly-hoc-y-khoa-14');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-duoc-ly-hoc-lam-sang-01', 'sub-med-pharma', 'Dược Động Học: Quá Trình Hấp Thu, Phân Bố, Chuyển Hóa, Thải Trừ (ADME)', 'duoc-ly-hoc-lam-sang-1', 'Bài học ''Dược Động Học: Quá Trình Hấp Thu, Phân Bố, Chuyển Hóa, Thải Trừ (ADME)'' thuộc môn Dược Lý Học & Cơ Chế Tác Dụng Thuốc. Số phận của viên thuốc trong cơ thể Nội dung trọng tâm gồm việc hiểu rõ bản chất của Sinh khả dụng Bioavailability, Hàng rào máu não, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 1, 9, '["Sinh khả dụng Bioavailability", "Hàng rào máu não", "Chuyển hóa qua gan Cytochrome P450", "Đào thải qua thận"]'::jsonb, 'COMPLETED', 86, 'ses-top-duoc-ly-hoc-lam-sang-01');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-duoc-ly-hoc-lam-sang-02', 'sub-med-pharma', 'Dược Lực Học: Cơ Chế Tương Tác Giữa Thuốc & Thụ Thể (Receptor)', 'duoc-ly-hoc-lam-sang-2', 'Bài học ''Dược Lực Học: Cơ Chế Tương Tác Giữa Thuốc & Thụ Thể (Receptor)'' thuộc môn Dược Lý Học & Cơ Chế Tác Dụng Thuốc. Cách thuốc tạo ra tác dụng sinh học Nội dung trọng tâm gồm việc hiểu rõ bản chất của Chất chủ vận Agonist, Chất đối kháng Antagonist, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 2, 8, '["Chất chủ vận Agonist", "Chất đối kháng Antagonist", "Đường cong liều lượng - đáp ứng", "Chỉ số điều trị Therapeutic Index"]'::jsonb, 'COMPLETED', 96, 'ses-top-duoc-ly-hoc-lam-sang-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-duoc-ly-hoc-lam-sang-03', 'sub-med-pharma', 'Các Yếu Tố Ảnh Hưởng Đến Tác Dụng Của Thuốc & Tương Tác Thuốc', 'duoc-ly-hoc-lam-sang-3', 'Bài học ''Các Yếu Tố Ảnh Hưởng Đến Tác Dụng Của Thuốc & Tương Tác Thuốc'' thuộc môn Dược Lý Học & Cơ Chế Tác Dụng Thuốc. Cá thể hóa điều trị Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tuổi tác và suy gan/thận, Tương tác thuốc - thuốc, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 3, 15, '["Tuổi tác và suy gan/thận", "Tương tác thuốc - thuốc", "Tương tác thuốc - thức ăn", "Phản ứng có hại của thuốc ADR"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-duoc-ly-hoc-lam-sang-04', 'sub-med-pharma', 'Dược Lý Kháng Sinh: Các Nhóm Kháng Sinh Chính & Cơ Chế Diệt Khuẩn', 'duoc-ly-hoc-lam-sang-4', 'Bài học ''Dược Lý Kháng Sinh: Các Nhóm Kháng Sinh Chính & Cơ Chế Diệt Khuẩn'' thuộc môn Dược Lý Học & Cơ Chế Tác Dụng Thuốc. Vũ khí chống vi khuẩn Nội dung trọng tâm gồm việc hiểu rõ bản chất của Beta-lactam ức chế thành tế bào, Aminoglycoside ức chế tổng hợp protein, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 4, 9, '["Beta-lactam ức chế thành tế bào", "Aminoglycoside ức chế tổng hợp protein", "Quinolone ức chế sao chép ADN", "Macrolide"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-duoc-ly-hoc-lam-sang-05', 'sub-med-pharma', 'Cơ Chế Kháng Thuốc Kháng Sinh & Chiến Lược Sử Dụng Hợp Lý', 'duoc-ly-hoc-lam-sang-5', 'Bài học ''Cơ Chế Kháng Thuốc Kháng Sinh & Chiến Lược Sử Dụng Hợp Lý'' thuộc môn Dược Lý Học & Cơ Chế Tác Dụng Thuốc. Nguy cơ toàn cầu của vi khuẩn đa kháng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Beta-lactamase, Bơm tống thuốc Efflux pump, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 5, 9, '["Beta-lactamase", "Bơm tống thuốc Efflux pump", "Đột biến đích tác dụng", "Nguyên tắc sử dụng kháng sinh an toàn"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-duoc-ly-hoc-lam-sang-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-duoc-ly-hoc-lam-sang-06', 'sub-med-pharma', 'Dược Lý Thuốc Giảm Đau, Hạ Sốt, Kháng Viêm Không Steroid (NSAIDs)', 'duoc-ly-hoc-lam-sang-6', 'Bài học ''Dược Lý Thuốc Giảm Đau, Hạ Sốt, Kháng Viêm Không Steroid (NSAIDs)'' thuộc môn Dược Lý Học & Cơ Chế Tác Dụng Thuốc. Kiểm soát viêm và cơn đau Nội dung trọng tâm gồm việc hiểu rõ bản chất của Cơ chế ức chế enzym COX-1 và COX-2, Paracetamol, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 6, 9, '["Cơ chế ức chế enzym COX-1 và COX-2", "Paracetamol", "Ibuprofen và Aspirin", "Tác dụng phụ trên dạ dày và thận"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-duoc-ly-hoc-lam-sang-07', 'sub-med-pharma', 'Dược Lý Thuốc Tim Mạch: Thuốc Điều Trị Tăng Huyết Áp', 'duoc-ly-hoc-lam-sang-7', 'Bài học ''Dược Lý Thuốc Tim Mạch: Thuốc Điều Trị Tăng Huyết Áp'' thuộc môn Dược Lý Học & Cơ Chế Tác Dụng Thuốc. Bảo vệ hệ mạch vành Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thuốc ức chế men chuyển ACEi, Thuốc chẹn thụ thể ARB, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 7, 13, '["Thuốc ức chế men chuyển ACEi", "Thuốc chẹn thụ thể ARB", "Thuốc chẹn kênh Canxi CCB", "Thuốc chẹn beta"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-duoc-ly-hoc-lam-sang-07');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-duoc-ly-hoc-lam-sang-08', 'sub-med-pharma', 'Dược Lý Thuốc Hệ Hô Hấp: Điều Trị Hen Phế Quản & COPD', 'duoc-ly-hoc-lam-sang-8', 'Bài học ''Dược Lý Thuốc Hệ Hô Hấp: Điều Trị Hen Phế Quản & COPD'' thuộc môn Dược Lý Học & Cơ Chế Tác Dụng Thuốc. Làm thông thoáng đường thở Nội dung trọng tâm gồm việc hiểu rõ bản chất của Thuốc giãn phế quản đồng vận Beta-2 (Salbutamol), Corticoid hít (ICS), vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 8, 10, '["Thuốc giãn phế quản đồng vận Beta-2 (Salbutamol)", "Corticoid hít (ICS)", "Kháng Cholinergic"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-duoc-ly-hoc-lam-sang-09', 'sub-med-pharma', 'Dược Lý Thuốc Điều Trị Đái Tháo Đường: Insulin & Thuốc Uống Hạ Đường Huyết', 'duoc-ly-hoc-lam-sang-9', 'Bài học ''Dược Lý Thuốc Điều Trị Đái Tháo Đường: Insulin & Thuốc Uống Hạ Đường Huyết'' thuộc môn Dược Lý Học & Cơ Chế Tác Dụng Thuốc. Kiểm soát đường máu hiệu quả Nội dung trọng tâm gồm việc hiểu rõ bản chất của Các loại Insulin nhanh/chậm, Metformin ức chế tạo glucose tại gan, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 9, 14, '["Các loại Insulin nhanh/chậm", "Metformin ức chế tạo glucose tại gan", "Nhóm ức chế SGLT-2", "Nhóm GLP-1"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-duoc-ly-hoc-lam-sang-10', 'sub-med-pharma', 'Dược Lý Thuốc An Thần, Gây Ngủ & Thuốc Điều Trị Trầm Cảm', 'duoc-ly-hoc-lam-sang-10', 'Bài học ''Dược Lý Thuốc An Thần, Gây Ngủ & Thuốc Điều Trị Trầm Cảm'' thuộc môn Dược Lý Học & Cơ Chế Tác Dụng Thuốc. Tác động lên hệ thần kinh trung ương Nội dung trọng tâm gồm việc hiểu rõ bản chất của Benzodiazepine tác dụng lên GABA, Thuốc ức chế tái hấp thu chọn lọc Serotonin (SSRI), vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 14, '["Benzodiazepine tác dụng lên GABA", "Thuốc ức chế tái hấp thu chọn lọc Serotonin (SSRI)", "Hội chứng cai nghiện thuốc"]'::jsonb, 'NEEDS_REVIEW', 57, 'ses-top-duoc-ly-hoc-lam-sang-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-duoc-ly-hoc-lam-sang-11', 'sub-med-pharma', 'Dược Lý Học & Cơ Chế Tác Dụng Thuốc - Chuyên Đề Nâng Cao #1', 'duoc-ly-hoc-lam-sang-11', 'Bài học ''Dược Lý Học & Cơ Chế Tác Dụng Thuốc - Chuyên Đề Nâng Cao #1'' thuộc môn Dược Lý Học & Cơ Chế Tác Dụng Thuốc. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Dược Lý Học & Cơ Chế Tác Dụng Thuốc. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 11, 14, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-duoc-ly-hoc-lam-sang-11');
