INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-benh-hoc-noi-khoa-01', 'sub-med-internal', 'Bệnh Tăng Huyết Áp Vô Căn: Cơ Chế Bệnh Sinh & Biến Chứng', 'benh-hoc-noi-khoa-1', 'Bài học ''Bệnh Tăng Huyết Áp Vô Căn: Cơ Chế Bệnh Sinh & Biến Chứng'' thuộc môn Bệnh Học Nội Khoa Cơ Bản. Kẻ giết người thầm lặng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Huyết áp tâm thu/tâm trương, Tổn thương cơ quan đích, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 1, 7, '["Huyết áp tâm thu/tâm trương", "Tổn thương cơ quan đích", "Biến chứng đột quỵ và suy tim", "Phác đồ điều trị đa mô thức"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-benh-hoc-noi-khoa-02', 'sub-med-internal', 'Bệnh Động Mạch Vành & Hội Chứng Vành Cấp (Nhồi Máu Cơ Tim)', 'benh-hoc-noi-khoa-2', 'Bài học ''Bệnh Động Mạch Vành & Hội Chứng Vành Cấp (Nhồi Máu Cơ Tim)'' thuộc môn Bệnh Học Nội Khoa Cơ Bản. Cấp cứu tim mạch hàng đầu Nội dung trọng tâm gồm việc hiểu rõ bản chất của Xơ vữa động mạch, Đau thắt ngực ổn định vs không ổn định, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 2, 15, '["Xơ vữa động mạch", "Đau thắt ngực ổn định vs không ổn định", "Điện tâm đồ ECG đoạn ST chênh lên", "Men tim Troponin"]'::jsonb, 'NEEDS_REVIEW', 59, 'ses-top-benh-hoc-noi-khoa-02');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-benh-hoc-noi-khoa-03', 'sub-med-internal', 'Bệnh Đái Tháo Đường Type 1 và Type 2: Chẩn Đoán & Biến Chứng', 'benh-hoc-noi-khoa-3', 'Bài học ''Bệnh Đái Tháo Đường Type 1 và Type 2: Chẩn Đoán & Biến Chứng'' thuộc môn Bệnh Học Nội Khoa Cơ Bản. Rối loạn chuyển hóa phổ biến Nội dung trọng tâm gồm việc hiểu rõ bản chất của Kháng Insulin vs Thiếu hụt Insulin, Tiêu chuẩn chẩn đoán HbA1c, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 3, 15, '["Kháng Insulin vs Thiếu hụt Insulin", "Tiêu chuẩn chẩn đoán HbA1c", "Biến chứng mạch máu lớn và vi mạch", "Bàn chân đái tháo đường"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-benh-hoc-noi-khoa-04', 'sub-med-internal', 'Bệnh Viêm Phổi Mắc Phải Cộng Đồng (CAP)', 'benh-hoc-noi-khoa-4', 'Bài học ''Bệnh Viêm Phổi Mắc Phải Cộng Đồng (CAP)'' thuộc môn Bệnh Học Nội Khoa Cơ Bản. Nhiễm trùng đường hô hấp dưới cấp tính Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tác nhân vi khuẩn Streptococcus pneumoniae, Hội chứng đông đặc phổi, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 4, 9, '["Tác nhân vi khuẩn Streptococcus pneumoniae", "Hội chứng đông đặc phổi", "X-quang ngực thẳng", "Thang điểm CURB-65"]'::jsonb, 'COMPLETED', 96, 'ses-top-benh-hoc-noi-khoa-04');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-benh-hoc-noi-khoa-05', 'sub-med-internal', 'Bệnh Phổi Tắc Nghẽn Mạn Tính (COPD): Yếu Tố Nguy Cơ & Quản Lý', 'benh-hoc-noi-khoa-5', 'Bài học ''Bệnh Phổi Tắc Nghẽn Mạn Tính (COPD): Yếu Tố Nguy Cơ & Quản Lý'' thuộc môn Bệnh Học Nội Khoa Cơ Bản. Hậu quả của khói thuốc lá Nội dung trọng tâm gồm việc hiểu rõ bản chất của Viêm phế quản mạn và khí phế thủng, Đo chức năng hô hấp FEV1/FVC, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 5, 15, '["Viêm phế quản mạn và khí phế thủng", "Đo chức năng hô hấp FEV1/FVC", "Đợt cấp COPD", "Cai thuốc lá"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-benh-hoc-noi-khoa-05');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-benh-hoc-noi-khoa-06', 'sub-med-internal', 'Bệnh Loét Dạ Dày - Tá Tràng & Vai Trò Của Vi Khuẩn Helicobacter pylori', 'benh-hoc-noi-khoa-6', 'Bài học ''Bệnh Loét Dạ Dày - Tá Tràng & Vai Trò Của Vi Khuẩn Helicobacter pylori'' thuộc môn Bệnh Học Nội Khoa Cơ Bản. Tổn thương niêm mạc đường tiêu hóa Nội dung trọng tâm gồm việc hiểu rõ bản chất của Cân bằng giữa yếu tố tấn công và bảo vệ, Nhiễm khuẩn H. pylori, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 6, 8, '["Cân bằng giữa yếu tố tấn công và bảo vệ", "Nhiễm khuẩn H. pylori", "Nội soi tiêu hóa", "Phác đồ tiệt trừ H. pylori"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-benh-hoc-noi-khoa-07', 'sub-med-internal', 'Xơ Gan & Các Biến Chứng Của Tăng Áp Lực Tĩnh Mạch Cửa', 'benh-hoc-noi-khoa-7', 'Bài học ''Xơ Gan & Các Biến Chứng Của Tăng Áp Lực Tĩnh Mạch Cửa'' thuộc môn Bệnh Học Nội Khoa Cơ Bản. Giai đoạn cuối của tổn thương gan mạn tính Nội dung trọng tâm gồm việc hiểu rõ bản chất của Nguyên nhân do viêm gan virus B/C và rượu, Cổ trướng, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 7, 12, '["Nguyên nhân do viêm gan virus B/C và rượu", "Cổ trướng", "Xuất huyết tiêu hóa do vỡ giãn tĩnh mạch thực quản", "Hôn mê gan"]'::jsonb, 'NOT_STARTED', NULL, NULL);
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-benh-hoc-noi-khoa-08', 'sub-med-internal', 'Bệnh Thận Mạn (CKD) & Hội Chứng Suy Thận', 'benh-hoc-noi-khoa-8', 'Bài học ''Bệnh Thận Mạn (CKD) & Hội Chứng Suy Thận'' thuộc môn Bệnh Học Nội Khoa Cơ Bản. Mất dần chức năng lọc cầu thận Nội dung trọng tâm gồm việc hiểu rõ bản chất của Các giai đoạn bệnh thận mạn, Protein niệu, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 8, 13, '["Các giai đoạn bệnh thận mạn", "Protein niệu", "Hội chứng ure huyết cao", "Chỉ định lọc máu chạy thận nhân tạo"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-benh-hoc-noi-khoa-08');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-benh-hoc-noi-khoa-09', 'sub-med-internal', 'Bệnh Tai Biến Mạch Máu Não (Đột Quỵ Nhồi Máu Não & Xuất Huyết Não)', 'benh-hoc-noi-khoa-9', 'Bài học ''Bệnh Tai Biến Mạch Máu Não (Đột Quỵ Nhồi Máu Não & Xuất Huyết Não)'' thuộc môn Bệnh Học Nội Khoa Cơ Bản. Thời gian là não bộ Nội dung trọng tâm gồm việc hiểu rõ bản chất của Dấu hiệu nhận biết FAST, Cửa sổ vàng tiêu sợi huyết, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 3, 9, 13, '["Dấu hiệu nhận biết FAST", "Cửa sổ vàng tiêu sợi huyết", "Chụp CT/MRI sọ não", "Phục hồi chức năng sau đột quỵ"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-benh-hoc-noi-khoa-09');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-benh-hoc-noi-khoa-10', 'sub-med-internal', 'Hội Chứng Nhiễm Trùng Huyết (Sepsis) & Sốc Nhiễm Khuẩn', 'benh-hoc-noi-khoa-10', 'Bài học ''Hội Chứng Nhiễm Trùng Huyết (Sepsis) & Sốc Nhiễm Khuẩn'' thuộc môn Bệnh Học Nội Khoa Cơ Bản. Phản ứng viêm toàn thân đe dọa tính mạng Nội dung trọng tâm gồm việc hiểu rõ bản chất của Tiêu chuẩn SOFA / qSOFA, Hạ huyết áp không đáp ứng bù dịch, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 1, 10, 7, '["Tiêu chuẩn SOFA / qSOFA", "Hạ huyết áp không đáp ứng bù dịch", "Kháng sinh sớm giờ đầu", "Bù dịch và thuốc vận mạch"]'::jsonb, 'IN_PROGRESS', NULL, 'ses-top-benh-hoc-noi-khoa-10');
INSERT INTO public.academic_topics (id, subject_id, title, slug, summary, difficulty_level, order_index, estimated_reading_minutes, required_concepts, status, highest_clarity_score, active_session_id) VALUES ('top-benh-hoc-noi-khoa-11', 'sub-med-internal', 'Bệnh Học Nội Khoa Cơ Bản - Chuyên Đề Nâng Cao #1', 'benh-hoc-noi-khoa-11', 'Bài học ''Bệnh Học Nội Khoa Cơ Bản - Chuyên Đề Nâng Cao #1'' thuộc môn Bệnh Học Nội Khoa Cơ Bản. Nghiên cứu chuyên sâu và tình huống ứng dụng thực tế trong Bệnh Học Nội Khoa Cơ Bản. Nội dung trọng tâm gồm việc hiểu rõ bản chất của Khái niệm nâng cao #1A, Kỹ thuật tối ưu #1B, vận dụng phương pháp giải thích đơn giản hóa của Feynman để liên kết với các ứng dụng thực tế.', 2, 11, 12, '["Khái niệm nâng cao #1A", "Kỹ thuật tối ưu #1B", "Phân tích tình huống", "Ứng dụng thực tiễn"]'::jsonb, 'NOT_STARTED', NULL, NULL);
